/**
 * SAFETY LESSONS LOG — every entry from the old site's two volumes:
 *   safety/SftyLssnsLg.asp      (volume 2, current)
 *   safety/SftyLssnsLgPrev.asp  (volume 1, earlier)
 *
 * GENERATED by tools/parse-safety-log.mjs. Hand edits are fine; re-running the
 * generator would overwrite them.
 *
 * The point of this log is that members read it. The page shows the most recent
 * five years and loads more on request, with a search box, because a single
 * 422-entry page is one nobody scrolls to the bottom of.
 *
 * SAFETY-CRITICAL CONTENT. This is the club's own record of what went wrong and
 * what was learned. Do not paraphrase entries to make them read better.
 */

export type SafetyLesson = {
  id: string;
  /** ISO year-month, for sorting */
  date: string;
  displayDate: string;
  year: number;
  title: string;
  report: string;
  lessons: string;
  actions: string;
  /** 1 = the earlier volume, 2 = the current one */
  volume: 1 | 2;
};

export const safetyLessons: SafetyLesson[] = [
  { id: "2026-05-0", date: "2026-05", displayDate: "May 2026", year: 2026, title: "Flight Over Airfield", report: "Glider A on approaching the airfield at circuit height at the end of a cross-country flight, - the end of which was being logged at the time it crossing the airfield, - was flown across the airfield whilst another glider, B, was on its launch and still attached to the cable. Glider A then proceeded to fly an abbreviated circuit and landed. This was witnessed, amongst others, by the launch marshal and the winch driver each of whom were involved in the launch of glider B. Their debriefings are the basis of this report. Reports of the de-briefing of pilot of glider A revealed that he was unaware of the Camphill rules about finishes. Nor was any radio call made warning of his arrival and intention to carry out a finish of a task by crossing the airfield.", lessons: "It was apparent that the pilot was not familiar with content of the Pilots Manual which precludes finishing over the airfield. Crossing the track of a winch launch whilst it is progress risks collision with the cable dropping from the glider after completion or abandonment of its launch, so is a significant breach of airmanship. Pilots flying from Camphill are expected to comply with the Pilots Manual. At section 2.16 Final Glides it states that finishes from final glides may not be carried out over the airfield but should instead use remote turn points such as “Camphill Start/Finish”. Pilots wishing to log the time of finishing final glides at the CPH turn point should use a finish line, perpendicular to their final task leg, which extends from the CPH turn point or from one of the remote turn points. They should give notice of their intention on the airfield radio channel, then monitor the radio for information about traffic in the circuit. They should arrive with enough height, or speed to convert to height which enables a normal circuit and approach", actions: "The CFI and Safety Officer (Flying) were informed of the incident A Safety Lessons Log report was raised. The pilot of glider A was de-briefed regarding the safe combination of both club and task rules. The pilot of glider A was re-briefed regarding Club rules and safe airmanship in the circuit. The launch point team and winch driver were debriefed by way of support after witnessing this shocking incident. Further Action . The content of the Pilots Manual relating to logger timed finishes should be amended to match the content in the Lessons Learned column", volume: 2 },
  { id: "2026-02-1", date: "2026-02", displayDate: "February 2026", year: 2026, title: "Wood Block on K18 Seat", report: "Whilst re-boarding the glider at the launch point having got out to adjust the rudder pedals, the pilot noticed a small piece of wood, described as approx. 25mm square, lying on the energy absorbing seat cushion. Because the purpose of the wood block could not be identified, the glider was returned to the hangar for investigation.", lessons: "The decision to not fly the glider was wise and demonstrated due caution. The block was identified by an aircraft inspector as having become detached from the headrest. After re-attachment the glider was returned to service.", actions: "Reported to CFI and Safety Officer Reported to, and repaired by, a/c workshop This item added to Safety Lessons Log", volume: 2 },
  { id: "2025-11-2", date: "2025-11", displayDate: "November 2025", year: 2025, title: "Insecire Safety Pin", report: "During a DI of a K18,, a visual check in the space underneath the fairing between the wings indicated that a spring clip (referred to as a “safety pin”) that secures the connection between the fuselage and the aileron drive appeared to be not secure. After the fairing was removed to enable full access, it was seen that whilst the straight arm of the spring clip was in place (passing through the starboard connector mechanism), the other arm of the spring clip was not hooked round the securing arm - which should prevent the straight arm from coming out of the connector mechanism . Photographs of the finding were taken with the clip in place as found. The spread of the spring in the securing arm of the clip from the straight arm indicates the spring in the clip was serviceable. The clip was made secure and the glider marked as serviceable, with the action taken re the clip recorded in the DI book. No second check or rigging check of the resecured aileron connection was noted in the DI book. The absence of a rigging check record in the DI book following both an earlier and this removal of the fairing for investigations was noted.", lessons: "The member who, during a daily inspection, spotted the insecure clip in the aileron connection in the space between the wings, is to be congratulated on a finding that had some potential for serious consequences. It remains unclear how the situation occurred. There was no report that the safety clip in question was other than serviceable. Although there is no clear record in the DI book of secondary checks (akin to “rigging” checks) after securing of control linkages, it is hoped that they took place. The absence of records of secondary checks in the DI book is a shortcoming that should be addressed by instructions on this matter.", actions: "The facts were reported to the CFI, CSO and Club Aircraft Inspector (CAI). The CAI subsequently issued instructions on when and how secondary checks after any dismantling must be recorded in DI books.", volume: 2 },
  { id: "2025-07-3", date: "2025-07", displayDate: "July 2025", year: 2025, title: "Cable over public road", report: "On the day in question, the winch was operating from a position at the South West corner of the field, with a 15-20kts wind from the West. At the top of a launch the winch engine cut-out after the power reduction by the driver. In spite of attempts to do so, the winch engine could not be immediately restarted. Consequently, it was not possible to pull in the cable as normal. The strop end of the cable landed in the South East area of the field but some of the Dyneema cable landed in the road which is adjacent to field. One road vehicle drove over the cable, without any reported consequences, before the cable was retrieved from the road. The winch engine was restarted to pull in the retrieved cable without any further issue. It was reported indirectly that during the launch in question there was insufficient lay off to the west to compensate for the cross wind. Launching continued thereafter without discussion with, or request by, an instructor or launch marshal about relocating the winch/winches.", lessons: "It was fortunate that the parachute, strop and associated iron work did not fall where any passing vehicle on the public road may have struck it or vice-versa causing serious injury or damage. Even the cable falling on the road might have had some unfortunate consequences. Hence the incident must be seen as one from which safety lessons can be learned or re-learned. Launching in either a N to S or S to N direction on our airfield when there is a cross-wind component demands that pilots prevent being drifted with the x- wind by “laying off” during the launch in order to prevent the cable and its components from doing damage or injury by falling to land anywhere other than on the airfield. That means it must not land on any perimeter track, buildings, caravans, or over boundary walls. It can also make it very difficult to recover if it lands in the trees on the airfield boundary or over the ridge on the west side of the airfield. The subject of launching in cross winds, especially with respect to avoiding dropping the cable off the airfield, is covered in one of the Training Articles that can be found on the members’ website, via a link in the Links Library page, specifically at this link The take away lesson(s) are reminders ... The correct lay-off during the launch will be judged insufficient if it has not prevented any of the above off-airfield landings of the parachute, strop or cable after the release from the glider or a cable break. Pilots must apply the content of the Training Article mentioned above. The Winch Operation Manual (in section 9.2) states that if the winch driver is finding it difficult to keep the descending parachute on the airfield …. the WD must request the duty instructor, via the launch marshal, for a change of winch position.", actions: "The incident was reported to the CFI, Safety Officer and later to the Winchmaster . The stalling of the winch was reported to the winch maintenance officer", volume: 2 },
  { id: "2025-07-4", date: "2025-07", displayDate: "July 2025", year: 2025, title: "Winch moved during launch", report: "Whilst the power was being increased by the winch driver in response to the “All Out” signal, the winch moved “a little” towards the launch point, then slewed to an out-of-line angle, at which point the winch driver stopped the launch. The glider being launched had accelerated sufficiently in a shallow climb to an estimated 3 to 5 feet, but when the acceleration stopped, the pilot abandoned the launch, and landed ahead with no consequences. The winch driver reported that in spite of the wheel chocks being down as normal, they slid over the ground, thus not preventing the winch from moving. The glider being launched was a type which is heavier than others routinely launched. It was subsequently successfully launched with a towing vehicle attached to the winch.", lessons: "Any launch which is abandoned because of some failure in the system, presents an increased risk because it requires out of ordinary action to ensure a safe outcome. Because the reported occurrence was so unusual it was decided it should be added to the Safety Lessons Log (SLL). Informed opinion is that the ground at the position of the winches on that occasion was too hard (because of dryness) for at least one of the wheel chocks to dig in, as it should, to anchor the winch against being moved by launch forces.", actions: "Added to the SLL (Safety Officer) Notified to CFI and then to the Winch Master for consideration of need for documented measures to prevent a re-occurrence.", volume: 2 },
  { id: "2025-05-5", date: "2025-05", displayDate: "May 2025", year: 2025, title: "Crash at start of launch", report: "Launching was to the North with wind from the NE. Some reports stated the wind was about 15 kts with occasional gusts. After the wing tip runner on the right wing let go of the wing, the left wing went down and scraped across the ground for several yards. The glider then started to yaw to the left, at the same time lifting off with the right wing high and the fuselage some several feet in the air. The yawing continued, the glider pitched nose down, the nose struck the ground whilst the glider travelled some distance backwards. By the time the glider came to rest, the yaw had continued for some 220 to 260 degrees and the glider had travelled about 100 yards. Fortunately, the pilot was not injured, and could climb out unaided. Damage to the glider was serious and extensive. The pilot reported that his hand had slipped off the cable release knob and only when he managed to pull the knob at the second attempt was the cable released. The winch driver, on seeing the glider’s unusual attitude, immediately disconnected the drive and applied the brake within an estimated maximum of one second. It could not be determined which action was first, releasing the cable or stopping the winch.", lessons: "The outcome of occurrences in which a wing drop impacts the ground and stays there, without the winch launch being stopped, are more often than not, fatal for the pilot. This is because the upper wing lifts the glider right up until it is rotating around the tip on the ground. The result is the nose diving into the ground with tragic results. The event is called a cartwheel. This incident in question was an example of a wing tip dragging on the ground at the start of a launch. It occasionally happens. Because of the potentially serious consequences of such cases the following safety points are stated as important reminders:- Safety of the launch is significantly impaired if the wings do not remain level as the glider starts to move. If the pilot cannot keep the wings level, the release must be pulled immediately. To ensure that this can be done, the release control must be being held by the pilot as the launch starts. Pilots should make themselves aware of the view from the cockpit so that they can see when wings are not level. A wing runner must not attempt to prevent the wing tip from being forced up or down by gusts. If that force happens, at any time, they must SHOUT STOP. If a wing tip does strike the ground after the launch commands are given, anyone can shout STOP and the signaller must be alert to the need to respond immediately. Pilots should be particularly alert to the upwind wing tip being lifted by any cross wind. No launch must be made over grass (or other vegetation) that is 4 or more inches (10 cms) high, preferably less. All pilots and ground crew are well advised to watch a video that demonstrates the consequences of a launch with a wing tip dragging on the ground; or by long grass. See this link", actions: "The occurrence was notified to the BGA and the AAIB. A full report was submitted to the BGA. The occurrence was notified to the Safety Officer The pilot is investigating a method of ensuring a guaranteed grip on the release control. The CFI will be drawing special attention of all club flying members to this SLL item. The relevant content of the Launch Marshals Manual and Ground Training Manual will be reviewed. The potential installation of a system for direct communication from Launch Marshal by radio link to Winch Driver to be investigated further.", volume: 2 },
  { id: "2025-05-6", date: "2025-05", displayDate: "May 2025", year: 2025, title: "Proximity with PG", report: "Having found a thermal and started to soar and centre in it, a glider pilot observed a paraglider (PG) soaring nearby. The glider pilot judged that the two were separated by “plenty” of horizontal and vertical separation. After a few more turns the glider pilot observed that the PG had joined the thermal the glider was in, with turns in the same direction, flying a circle with the same centre, below and climbing at the same rate. At some point the PG climb rate increased and it soared up to the same height as the glider. The glider pilot mentions that the PG and the glider were “closest” at this, or the following, point. The PG changed the centre and direction of its turns. The glider pilot observed there was then increased separation as the PG left the thermal.", lessons: "All pilots who wish to share thermals with paragliders should learn and understand why that is an activity requiring skills and understanding. An article, which can be found via the link “Training Articles” in the Pilot Training section of the Links Library in the Members’ Website, should be considered essential reading. In summary it states “Joining, sharing and leaving a thermal with other soaring aircraft requires a high level of airmanship and spatial awareness. It brings with it a higher risk of collision.” If it’s found to be difficult to be sure of avoiding conflict with another aircraft of whatever type, when sharing a thermal, you should leave the thermal.", actions: "The glider pilot discussed the occurrence with the PG pilot. Each agreed to make their own reports to the Airprox Board. Reported to the Safety Officer and CFI Added to the Safety Lessons Log", volume: 2 },
  { id: "2025-05-7", date: "2025-05", displayDate: "May 2025", year: 2025, title: "Launch point tractor towing incident", report: "A glider having been towed to position for a launch, the pilot acting as brake person on the leading edge of the right wing, signalled to the tractor driver to stop. The wing tip holder was on the right wing. Without the tow rope having been disconnected, the tractor driver moved off making a turn to the left. The tractor driver did not respond to several loud shouts to stop. The wing tip holder being unable to move forward sufficiently, to follow the tractor, caused the glider to yaw to the right. The pilot acting as brake person dived to the ground under the right wing suffering only broken sunglasses. The tractor driver either heard shouts or saw what was happening, came to a halt, but by this time the glider was beginning to be dragged sideways to the left. The glider had been moved about 20 metres. The pilot acting as brake person appeared to suffer no injury. There was no damage to the glider.", lessons: "Fortunately there was to injury or damage. It was concluded that the tractor driver had stopped but had then moved off after ensuring by looking for evidence that the tow rope was disconnected from the glider. It is the responsibility of drivers of towing vehicles to thoroughly check for signals from the crew walking with the glider that it is safe to move off when the tow starts and when the tow finishes. As well as this the towing vehicle driver should be looking back at those with the glider as much as looking forward.", actions: "", volume: 2 },
  { id: "2025-05-8", date: "2025-05", displayDate: "May 2025", year: 2025, title: "Cable retrieve incident", report: "The tow out vehicle was towing out 4 cables. On seeing “late” a 2 seat glider on approach in a direction that was believed to be in line with the track of the tow out vehicle, the driver brought the tow out vehicle to an emergency stop . The consequence was that the cables on all 4 winch drums got slack cable loops round them. Whilst the winch driver dealt with clearing the loops on 3 of the 4 drums, the tow out driver made ready to resume the tow without having made contact with the winch driver to ensure he was free from danger. In doing so the cable for the drum 4th uncleared drum was hooked onto the towing bar by a cord loop that was not a weak link because after the weak link had failed on the first attempt at a resuming the tow out. The consequence that when the tow was resumed the uncleared drum prevented the cable from being pulled out causing the towing spreader bar to be bent out of shape and become totally unserviceable. Having tried but failed to establish radio contact with the tow out driver the winch driver turned on the winch stop light and attempted by radio to get the launch point crew to take a radio to the tow out driver But that attempt at radio contact was also unsuccessful. The tow out driver admits to being was unaware of the radio in the vehicle. It was established that the radio in the tow out vehicle was not switched on.", lessons: "", actions: "", volume: 2 },
  { id: "2025-04-9", date: "2025-04", displayDate: "April 2025", year: 2025, title: "Proximity at top of launch", report: "During a launch to the South a pilot of a single seat glider (glider B) reported releasing before the top of the launch because of concern about the proximity of another single seat glider (glider A). It was logged that glider B was launched 5 minutes after glider A. The pilot of glider A reported that after his launch he turned East along the S edge where he found some lift and started to explore this by making S tums but not circling. The pilot of glider B reports that the launch point crew had confirmed his own view that the position of glider A would not obstruct his launch. The wind direction for the day was logged as SE .", lessons: "It is clear that the height of gliders in the vicinity of the top of the launch was over estimated. It is also possible that insufficient allowance had been made for the drift of glider A towards the airfield whist searching for lift in the SE wind. It is a unwritten rule that, as a matter of courtesy, a pilot is allowed to search for lift at the top of the launch for a short time (not more than about 5 minutes) in order to “get away” but any use of that allowance requires watching for preparations for the next launch. Having left the area a pilot must not return. After that no pilot should not fly across the airfield less than 500 feet above launch height except as part of a circuit for landing", actions: "A report was submitted by the pilot of glider B. An item was added to the Safety Lessons Log The launch crew contribution was reported to the CLM", volume: 2 },
  { id: "2025-03-10", date: "2025-03", displayDate: "March 2025", year: 2025, title: "Winch tow hook safety breach", report: "It was discovered that a winch tow hitch had been held in the open, and therefore unlocked, position by an inserted pebble acting as a chock. This habit of compromising the winch towing mechanism has been discovered TWICE before and reported in this log in September 2020 and January 2022. The dangers of using a chocking pebble were made clear in the Safety Lessons Log on those occasions", lessons: "The reasons for this habit have been understood: it is practically near impossible to hold the hitch lever up and open, whilst the jacking handle is turned to raise or lower the hitch while connecting or disconnecting the winch to/from its tow vehicle. The potential consequences of a towed runaway 3.5 tons winch because it is not safely connected, are extremely serious. It has now been agreed that the insertion of any chock (for example a pebble) to hold the hitch locking lever open is prohibited and any transgression will be considered a serious breach of safety. The practical difficulty will be obviated by making it mandatory that the process of hitching and unhitching of the winch from the tow vehicle must be carried out by two persons, one to hold the hitch lock lever open and one to turn the jacking handle. These rules are to be invoked immediately, publicised and written into an update of the Winch Operating Manual.", actions: "Modifications are to be made to the Winch Operating Manual by the Winchmaster. This report and lessons are to be included in the Safety Lessons Log by the Safety Officer", volume: 2 },
  { id: "2025-03-11", date: "2025-03", displayDate: "March 2025", year: 2025, title: "Unsafe cable recovery", report: "The winch started to wind in a cable that had drifted, after a launch fail, over the winches shed. The winding in by the winch was stopped after the pilot of the glider, that had landed mid-field, contacted the winch driver. Winding in was resumed only after the parachute assembly and cable were retrieved by hand to the field. The winch driver had not made checks as to the position of the fallen cable and parachute assembly. There was no injury or damage caused by the premature action by the winch driver.", lessons: "The lesson from this incident is obvious form the report. Winding in of a cable after a launch must proceed only if the winch driver can clearly see that the parachute and cable can be seen to be is on the field. Refer to section 8.6 of the Winch Operating Manual.", actions: "Reported to the Safety Officer . Entered into the Safety Lessons Log", volume: 2 },
  { id: "2025-03-12", date: "2025-03", displayDate: "March 2025", year: 2025, title: "Mobile found in glider", report: "After exiting a two seater at the end of a training flight check flight the crew heard a mobile telephone ringing in the glider. It was found down the side of a front seat. It had been called by someone trying to locate a missing phone. It transpired that the phone had inadvertently been left or dropped in the glider by the previous front seat pilot. The pilot was debriefed", lessons: "Perhaps fortunately the phone had not fallen into a position in the glider where it might have interfered with any control mechanism. Because of the danger of interfering with the control mechanisms it is essential that items carried in a glider are kept secure of such possibilities by being kept in zipped pockets or in the side pockets of gliders. If mobile phones are to be used for photography they must be held in lanyards round the neck", actions: "Reported to Safety Office . Occurrence added to Safety Lessons Log", volume: 2 },
  { id: "2024-09-13", date: "2024-09", displayDate: "September 2024", year: 2024, title: "Launch signal safety incident", report: "A witness at the launch point, who observed a launch being initiated, reported that after the Launch Marshal (LM) called \"Take Up Slack\" (TUS), there was no immediate vocal confirmation from the signaller heard , but after a few seconds the signaller said \"Wait a Minute.\". The witness states that the signaller then gave the TUS signal. The glider did not move. The Launch Marshal (LM) shouted \"STOP\" for no known reason. The launch did not proceed. The witness reported that the signaller appeared to have mis-operated the signalling box.", lessons: "The launch did not proceed. Exactly why is not clear. The LM called STOP, which was wise if he/she recognised the possibility of an un-safe launch. Maybe the winch driver saw that the TUS signalling had started but was discontinued and/or no All Out signal was given. Maybe the signaller didn’t operate the control of the signalling control box in exactly the correct way. Given the lack of clarity about events, the lesson learnt remains as a statement of how launch signalling should be managed. Signalling system operators must be sufficiently adroit at use of the control box. That means they must be able and ready to operate the correct box buttons in response to one of the only three correct commands, issued normally in sequence: “Take Up Slack”, “All Out” and “STOP”. Note that “STOP” can of course be commanded before “All Out”. The signaller must confirm the commands by repeating them in a loud voice. As the Launch Marshal Manual states: \"Ensure that the signaller repeats the command back to ensure it has been heard correctly.\" There are potential dangers if there is any delay in sending a STOP signal to the winch. Operators of the signalling control box must be ready to signal STOP immediately with a thumb ready over the STOP button. Then if STOP is commanded, ensure that the STOP button is pressed and NOT the Master Control Switch. The latter disarms the signalling system and no STOP light is illuminated.", actions: "Reported to CSO and CFI Added to Safety Lessons Log", volume: 2 },
  { id: "2024-08-14", date: "2024-08", displayDate: "August 2024", year: 2024, title: "Canopy strap in glider", report: "At end of day it was found that one of the Puchacz canopy cover fixing bungees had slipped down behind the rear seat and wrapped itself around part of the wheel brake mechanism. A test of applying the wheel brake showed that it couldn’t be applied.", lessons: "It was evident that at start of day the canopy cover had not been put inside its containing bag before being properly placed on the stowage platform behind the rear seat. This allowed one of the bungees to escape to where it affected the wheel brake mechanism. The result of the failure to stow the canopy cover, with its bungees safely in preparation for flight made it a loose article in the cockpit. Loose articles can end up in positions where they seriously affect the action of controls. It was fortunate that this was not a major problem on this occasion.", actions: "Reported to CSO and CFI. Add to Ground Training Manual the correct stowage of canopy covers Added to SLL", volume: 2 },
  { id: "2024-06-15", date: "2024-06", displayDate: "June 2024", year: 2024, title: "Canopy locking mechanism partial failure", report: "Whilst flying, the pilot of a single seat glider became aware of a whistle from the front of the cockpit. It was apparently associated with the canopy. Being entirely certain that the canopy was firmly locked down before the launch the pilot continued the flight. Subsequent investigation showed that the canopy locking mechanism was apparently effectively locking down, but the locking was incomplete due to a failure of a component within it.", lessons: "It is difficult to generalise about any lesson learnt from this occurrence because it was specific to the glider type. Nevertheless, given the potential seriousness of the consequences of a canopy opening in flight, there is a lesson to be learnt. It is important that canopy locking mechanisms are checked for integrity and security, both routinely and at DI.", actions: "The occurrence was reported to the Safety Officer for inclusion of this report in the Safety Lessons Log. The occurrence was brought to the attention of other members with the same type of canopy locking mechanisms. The reporter has notified the BGA of this occurrence.", volume: 2 },
  { id: "2024-06-16", date: "2024-06", displayDate: "June 2024", year: 2024, title: "Canopy damaged during DI", report: "A two seat glider was parked to the East of the hangar for daily inspection (DI), nose to the South. At the time of the occurrence the wind was “strong” from the SW.. The right wing was being held down by a wing bag (without stakes) with a “large” tyre over it. Having completed the daily inspection, the member standing beside the cockpit turned their attention to signing the DI book. Whilst engaged in that task, a gust of wind lifted the right wing, throwing the tyre off. The still open canopy was then blown closed with a slam before the member was able to stop it. On inspection It became clear immediately that a crack had propagated from the base of an existing temporary repair, along the path of that repaired crack and over the top of the canopy.", lessons: "The perspex of glider canopies is very vulnerable to fracture if shock loaded. They cost thousands of pounds to replace. Good repairs are difficult and are rarely tolerably invisible. That is why so much attention must be given to their care. The glider was correctly parked with its right wing down, which minimise the potential of the canopy closing itself under gravity. However, wing bags should be staked in the lee of the hangar where it can be gusty. It was accepted that insufficient attention had been paid to the prevailing wind conditions, In such conditions, canopies should be held by a helper whilst they are open during a DI.", actions: "The canopy was removed for repair locally, which was completed. Reported to the Aircraft Officer Occurrence added to the SLL", volume: 2 },
  { id: "2024-06-17", date: "2024-06", displayDate: "June 2024", year: 2024, title: "Launch with cable over wing", report: "Launching was taking place from the East launch point. To avoid soft ground the cables were being towed out along the line of the extinct East/West road. This resulted in the cables at the launch point lying South of the Launch Point Bus (LPB) at a distance which allowed gliders to launch from a position between the LPB and the cables. From witness reports it is concluded that for the 5th launch of the day, the port side wing tip of the glider was near or over the three lying cables. The wing runner was on the starboard wing tip and reports having no problems with holding the wings level whilst staying with the wing “as long as he could”. During the first few seconds of “all out” the glider rolled slowly, yawed “towards the hangar” (i.e. to the south). the port wing tip dropped to the ground and went under the South most of the three lying unused cables. The glider rotated into the climb. The pilot reports being unaware of the wing drop, nor of the picked up cable and allowed the launch to continue, but was hearing what was to him an unusual sound, which it is assumed would have been the sound of the picked up cable running over the left wing. The pilot released at c.500 feet QFE (usual launch height for the conditions), found the rudder was behaving sluggishly, until hearing a “slapping” noise after which all appeared normal. It appears that noise was the guillotined cable falling off the glider. The flight was curtailed but continued uneventfully to a normal landing. The picked up cable carried its parachute up with it. On seeing this happening an urgent call was made to the winch driver requesting that cable to be guillotined. After the glider released the launching cable, the winch driver, also seeing what was happening, guillotined the picked up cable. The launch marshal who was controlling the signal lights was advised by an instructor not to signal stop to the winch during the launch, having considered that recovery from a stopped launch, in the situation, at the height and position seen, was no less hazardous.", lessons: "The primary cause of the occurrence was that the glider was launched from a position between the LPB and the cables on the south side of the LPB. This increased the probability of its port wing, if it dropped to the ground, (which it did), picking up a cable during the launch ground run. It appears that the potential consequences of not complying with the normal configuration of the East (or any) launch point should always be fully considered and applied. Whilst the dropping of a wing to the ground during the launch ground run can and happen without the pilot being aware, a grounded wing tip has lots of potential for a very serious accident. Pilots must take care to prevent this and be prepared to abandon the launch if it is even suspected. It’s important to be familiar with the view from the cockpit when there is a wing tip on the ground. Whilst there is variation of opinion on whether and when it is best to not call STOP after a launch has started or is in progress, the default advice for the time being is to call STOP at any time when anything not normal occurs or is seen. Pilots should abandon a launch immediately if anything not normal is heard, seen or felt.", actions: "Submit a report to the BGA Add an entry re this occurrence to the Safey Lessons Log Review the content of the Launch Marshals Manual (LMM) w.r.t. • When to, or when to not signal STOP • Consider nomination of an LM of non-rota days (i.e. weekdays). • Launch supervision", volume: 2 },
  { id: "2024-05-18", date: "2024-05", displayDate: "May 2024", year: 2024, title: "Undercariage not down", report: "At the end of a short flight in a glider type new to him, the glider was landed without the retractable undercarriage having been lowered. There was no significant damage reported. The pilot reported he had modified his circuit plan due to the presence of paragliders.", lessons: "In the pilot’s own words: Always follow your landing routines. If an extra complication is introduced, you should focus even more on following and not missing out the basic steps. In this case mixing with different aircraft and adapting the circuit should make the circuit preparation and landing checks even more important to be followed.", actions: "Reported to CFI and CSO Added to Safety Lessons Log", volume: 2 },
  { id: "2024-04-19", date: "2024-04", displayDate: "April 2024", year: 2024, title: "K13 cushion misfitted", report: "During a DI it was found that a K13 had a front seat cushion fitted without using what are believed to be the loops in the seat provided for the purpose. It was tied to the triangular attachments which hold the lap straps in the glider. However, even if tied to the correct restraint point the cushion could slide forward and restrict the elevator control to “less than half up” elevator. The reporter noted that edge of the cushion has been “dented” by what appears to be compression from the stick – perhaps for some time.", lessons: "This report demonstrates the degree of observation needed in a DI. A seat cushion should be well fitted and fixed so that there is no interference with back movement of the stick, nor should it allow the pilot to slide forward such that there is any difficulty in keeping completely safe control. All gliders must be fitted with energy absorbing (EA) cushions. Those for club gliders are marked as such. Other cushions are firm. Any foam filled cushions must be removed from the Launch point bus, or glider because they must not be used in gliders.", actions: "Documented in SLL Referred to CFI To be referred to Aircraft Officer", volume: 2 },
  { id: "2024-04-20", date: "2024-04", displayDate: "April 2024", year: 2024, title: "Launch signalling with shock rope beside glider", report: "At the start of a K8 launch a take-up-slack signal was given and the cable started to move. A witness at the launch point heard all-out given and saw that the signals changed to All Out. The witness saw that there was still shock rope doubled back on itself to the side of the glider so shouted STOP, loudly and several times. That command if heard was not acted upon. The parachute started to move rapidly, there was a bang as the weak link failed. The glider remained almost stationary. The parachute set off down the field briefly.", lessons: "So that the Launch Marshal (LM or acting LM) and the pilot can see how the launch is progressing, the parachute, shock rope, and strop should be laid out straight towards the winch in front of the glider. This is described in the Launch Marshals Manual (LMM). If there is excess slack, the shock rope should be doubled back on itself, but still in front of the glider. That situation is not specifically described in the LMM, but should be.", actions: "Documented in SLL Referred to CFI To be referred to Chief Launch Marshal for addition to Launch Marshals’ Manual", volume: 2 },
  { id: "2024-04-21", date: "2024-04", displayDate: "April 2024", year: 2024, title: "Mobile loose in cockpit", report: "During the recovery phase of an exercise to simulate launch failure a mobile phone of a P2 in the front seat, escaped from the side pocket of the cockpit and went up to the top of the canopy due to negative g. It then fell down to the side of the seat. There were no ensuing consequences", lessons: "It was fortunate that the phone ended up where it didn’t cause a problem – as might have been the case if it had fallen into bottom of the cockpit close to the glider’s flying controls. It was also fortunate that the canopy wasn’t damaged as happened (elsewhere) when a glider in circuit suffered turbulence such that a loose hand held radio caused a hole in the canopy. The lesson here is obvious. Side pockets are primarily for holding maps or glasses and may also safely hold some refreshments. Heavier objects like phones or cameras must be held securely in pockets with strong closures (e.g. a zip fastener).", actions: "Documented in SLL Referred to CFI To be publicised to Instructors", volume: 2 },
  { id: "2024-04-22", date: "2024-04", displayDate: "April 2024", year: 2024, title: "A Ka18 glider ran across a launch rope", report: "A Ka18 glider ran across a launch rope on its landing ground run and the rope caught on the tailskid. At the launch point the launch parachute and equipment was pulled away for about 20 metres. There were no consequences resulting from this occurrence.", lessons: "Any landing glider can \"snag\" a launch rope when crossing over it on the ground. It's important to be alert to the possibility and to alert others. This is particularly so if others are standing close to launch equipment or preparing it for the next launch. The possibility increases and can be anticipated when it is necessary for launches to be at an angle to the approach directions .", actions: "Documented in SLL Reported to (and seen by) CFI", volume: 2 },
  { id: "2024-03-23", date: "2024-03", displayDate: "March 2024", year: 2024, title: "During a DI of a K13, it was", report: "During a DI of a K13, it was found that the battery strap can be eased apart when apparently secure. This occurs when the buckle is horizontal across the top of the battery. It holds firmly when vertical against the side of the battery.", lessons: "This is the third report of a potentially loose battery within a club glider since just prior to and including the two in November last year. The prospect of a battery coming loose during flight are so serious that those undertaking a DI must ensure that the securing mechanisms of batteries are serviceable and are applied correctly", actions: "Included in SLL To be referred to Aircraft Officer", volume: 2 },
  { id: "2024-03-24", date: "2024-03", displayDate: "March 2024", year: 2024, title: "During the DI of K13, a pair of", report: "During the DI of K13, a pair of glasses was found under a rudder pedal foot rest / platform.", lessons: "There was no indication that this object presented a safety problem where it was found, but care must be taken not to leave anything loose in a glider which should not be there. Any personal item that is missing after a flight must be reported, in case it has been left in the glider.", actions: "Documented in SLL Reported to CFI", volume: 2 },
  { id: "2023-11-25", date: "2023-11", displayDate: "November 2023", year: 2023, title: "Before the first launch of the day and", report: "Before the first launch of the day and at the launch point, it was noticed that the battery securing strap was connected and in place but it was loose. It was found that the strap had been threaded through the plastic clip incorrectly so that the clip did not anchor the strap. The strap could easily be pulled out of the clip. The strap was subsequently threaded correctly and the security of the strap checked without further incident.", lessons: "This is the second occurrence re an insecure battery within 3 weeks. See the otjher Safety Lessons Log entry for November 2023. As stated then, a loose battery in the cockpit can endanger safety by restricting the controls or even breaking through the canopy. A battery, not properly secured presents a serious hazard in flight and it's fortunate the loose strap was noticed before the first launch. It's important not only to look at an item being checked but, whenever possible, to test the item.", actions: "The person who carried out the daily inspection was de-briefed by the CFI. The Aircraft officer was notified. This addition was made to the SLL", volume: 2 },
  { id: "2023-11-26", date: "2023-11", displayDate: "November 2023", year: 2023, title: "Whist a single seat glider was being prepared", report: "Whist a single seat glider was being prepared for flight at the launch point, it was noticed that the battery was insecure. The battery had been installed without its securing strap for holding the battery being in place and tight. The glider had already been flown twice that day. On investigation it was revealed that the battery had been improperly installed by one person but that the Daily Inspection (DI) had been undertaken and signed off by another.", lessons: "Fortunately, the glider during its first two flights that day had not encountered any significant turbulence, nor any reduced or negative G - as can happen during recovery from a launch failure. Had it done so, the battery would have been loose in the cockpit where it could have endangered safety by restricting the controls or even breaking through the canopy. The person carrying out a DI, and signing they have completed it, is solely responsible for that inspection and may not assume that any preparation for flight has been satisfactorily completed by another person.", actions: "The member who carried out the DI was reminded by an instructor of his responsibility. The occurrence was reported to the CFI and Safety Officer for inclusion in the Safety Lessons Log", volume: 2 },
  { id: "2023-10-27", date: "2023-10", displayDate: "October 2023", year: 2023, title: "The occupant of the front seat of a", report: "The occupant of the front seat of a Puchacz was unable to exit the glider because the end of one of the parachute straps he was wearing was trapped in a slot beside the seat used for the glider’s lap strap. The occupant was freed by first removing this parachute whilst still seated in the glider. The parachute was then freed by manipulating its strap out of the slot.", lessons: "The occupant of the glider would not have been able to exit the glider in an emergency. Hence the situation had potentially fatal outcome. Those acting as P1 must ensure that free ends of P2 parachute straps are not wrongly located.", actions: "Occurrence reported to Aircraft Officer Report added to Safety Lessons Log", volume: 2 },
  { id: "2023-10-28", date: "2023-10", displayDate: "October 2023", year: 2023, title: "Because of deteriorating weather during a flight, two", report: "Because of deteriorating weather during a flight, two CPH gliders (A and B) returned from different directions to the site they were flying from (not CPH) in poor visibility, with drizzle obscuring vision through canopies. Whilst Pilot B reports hearing Pilot A reporting his position in the circuit, Pilot A heard nothing from Pilot B. Pilot B has stated he had reported his position when retuning to the airfield but decided to make no radio report of his position below 1000 ft QFE. Pilot A became aware of the position of glider B only when on approach and could see glider B landing ahead of him. The configuration of the airfield enabled pilot A to land without conflict with glider B. It was subsequently established that the two gliders had flown mirror circuits. It was reported that the quality of radio transmission from glider B was a known issue prior to this occurrence. Reception from glider B had been reported as level 2 or 3 (of 5). A local rule states that all gliders fly with operational radio. Pilot B has reported that subsequent to the event he found a technical fault with the microphone of his glider which was then repaired.", lessons: "It was fortunate that the mirror circuits flown did not lead to a conflict situation. The lesson learned was that absence of audible radio reports transmitted by pilots with information about their position in the circuit can, and in this case did, cause anxiety to other another pilot also committed to landing. Compliance with the local rule about radio equipment may have avoided anxiety to another pilot about risk of conflict between gliders landing in poor visibility.", actions: "Oral and written reports were received by the CFI and CSO. CFI debriefed Pilot B. The CFI is taking steps which may require some gliders launched from CPH to have operational radios. This occurrence will be added to the Safety Lessons Log.", volume: 2 },
  { id: "2023-10-29", date: "2023-10", displayDate: "October 2023", year: 2023, title: "A glider launching to the South grounded the", report: "A glider launching to the South grounded the left wingtip during the launch ground run. The launch continued without further incident. The pilot reported that he was aware the wing was low but not aware that it had touched the ground. Witnesses at the launch point confirmed the grounding. One estimated that the wing tip was on the ground for 10 feet. Wind was SW 10 to 15 kts with what the pilot reported as a noticeable cross wind. The pilot submitted a video with a forward view from the cockpit. The video shows a change from wings level at the start of the launch, to left wing low lasting for about 2 seconds.", lessons: "There is always concern about a wing tip dragging on the ground during the initial stages of a winch launch. This is a reportable occurrence because, it is from this situation that the glider can yaw round wing tip that is dragging, whilst the other wing lifts the glider so that it flies round the grounded wing tip and ends up diving into the ground. If that happens the consequences are serious or worse. If the pilot can release quickly enough they may save the situation but there isn’t time to stop the winch. The result is called a “cart wheel”. This link from the BGA website demonstrates it vividly. So, a pilot needs to be alert to not being able to keep the wings level. This tends to be more difficult to detect with longer wingspan gliders. It is wise for pilots to familiarise themselves with the view from the cockpit with the angle of bank with each a wing tip on the ground. It remains vital to have a hold of the release during the ground run to operate it immediately wings cannot be kept level, i.e. a tip is going down and before it is on the ground. There is reason to suspect that the left wing going down in this case was caused by the cross wind lifting the right wing. Pilots should be alert to this effect in any cross wind.", actions: "The ground crew reported the occurrence to the pilot who submitted a report to the CSO and CFI. The pilot’s video will be used as an aid to educating pilots about the issue. Added to the Safety Lessons Log", volume: 2 },
  { id: "2023-09-30", date: "2023-09", displayDate: "September 2023", year: 2023, title: "Whilst a Puchacz was parked outside the hangar", report: "Whilst a Puchacz was parked outside the hangar at end of day for extracting cockpit contents, the canopy was left open by two members who left it to take the battery and parachutes to the parachute store. The open canopy was noticed by nearby members one of whom immediately shouted “Canopy”. But at the same moment the canopy slammed shut. It was seen that a crack in the Perspex had developed from part way up a recent repair and extended beyond the end of the original. The glider was parked across a slope with the “wrong” (i.e. the left) wing tip down on lower ground so that the open canopy was almost at tipping point, thus allowing it to overbalance with the slightest breeze.", lessons: "Cracked Perspex cannot ever be completely and invisibly repaired. Canopies cost multiple thousands to replace. Those who had left the canopy open immediately accepted their responsibility. However there remained a question as to why a key rule about canopies, which is to never ever leave one open unattended, had not been applied. It is also a rule that club gliders, with canopies hinged on the right, are parked with right wing down so that when open, canopies have less tendency to topple closed. The occurrence suggests that more thought might be given to training on these aspects (as well is others re canopies) as specified in section 4.2 of the Ground Training Manual.", actions: "The occurrence suggests that more thought might be given to training on these aspects (as well is others re canopies) as specified in section 4.2 of the Ground Training Manual. Members undertaking open cockpit actions should watch for and take care about lack of attention to this matter , ensuring that if left open one person has agreed to hold it. Reported to the CSO for adding to the Safety Lessons Log.", volume: 2 },
  { id: "2023-09-31", date: "2023-09", displayDate: "September 2023", year: 2023, title: "This is based both on the pilot’s own", report: "This is based both on the pilot’s own account and the trace from the flight logger in the glider. He described his experience as a scare. In what were patchy soaring conditions on the west ridge, the pilot in a glass single seat glider whilst tracking south, north of the airfield manoeuvred to be clear of another glider by making a r/h turn. This turn continued until the glider was on a track south but on the east side of the “gulley”. By this point the pilot had elected to land. He found he was in severe sink. He abandoned any circuit east of the airfield’s east boundary wall , flew to the south west continuing in severe sink positioning to land in the north end of the airfield. The extremely strong sink continued - measured on his logger trace as up to 50 feet per second, this exacerbated by flying well above normal approach speed. The glider cleared the north west boundary wall by an estimated 5 metres, and landed without any consequence. The forecast from RASP on the day predicted lee wave with a bar positioned upwind or over of the site.", lessons: "The track of the glider seen in the logger trace indicates it was making a turn to the south, downwind of the small ridge on the SW side of a lower area called the “gulley”, a small valley. It may have been that the ridge feature generated an unusually strong and local low level down draft on its lee side, i.e. NE, side. In soarable conditions on the west edge of the airfield, there is a well-known phenomenon in the area to the East and North East of the airfield which is subject to exceptionally marked sink, especially when there is a southerly component in the wind. Because if that, the phenomenon is known as the “Clutching Hand”. This phenomenon is described in the Pilots Manual. Furthermore there is guidance in sections 4.4.6 and 4.4.7 on how to fly R/H circuits in soarable westerly or south westerly winds. This guidance is based on many years of hard won experience. The lesson for us all is to note and comply with the significant wisdom of flying circuits in a variety of conditions at Camphill as specified in the Pilots Manual.", actions: "Reported to the CSO and CFI for the purpose of lessons to be learned in the Safety Lessons Log.", volume: 2 },
  { id: "2023-09-32", date: "2023-09", displayDate: "September 2023", year: 2023, title: "A single seat glider with retractable undercarriage, which", report: "A single seat glider with retractable undercarriage, which was lowered for landing, collapsed on touch down. The undercarriage doors were torn off. The pilot accepted that the mechanism was not fully locked down.", lessons: "It is clearly best when lowering the undercarriage to confirm visually and manually when operating the mechanism that it finishes in the locked position. Not related to this case but if the u/c is lowered as the first action after deciding to land it provides more time for checking that in subsequent pre-landing checks.", actions: "Reported to the CSO for adding to the Safety Lessons Log.", volume: 2 },
  { id: "2023-07-33", date: "2023-07", displayDate: "July 2023", year: 2023, title: "The pilot reported that during a practice landing", report: "The pilot reported that during a practice landing on the airfield with self-sustainer engine deployed, and undercarriage down, the wheel retracted on touching down. An observer saw that the wheel was seen to be down on approach. An undercarriage door was damaged. It was concluded by the pilot that on lowering the undercarriage, he pushed the control lever all the way forward, but failed to notice that the locking lug (as fitted on the glider type) was not completely in its retaining slot . Hence the retractable undercarriage was down but not locked. The pilot reports that it was his error was to not check that the lug was fully in place and suggests that red paint he had applied, that made the position of the lug more obvious to him, had worn off.", lessons: "The lowering and locking down of a retracting undercarriage prior to landing always requires added attention. Practice landings with an extended but stopped self-sustainer engine are wise. However, when undertaking that, there is an extra workload on the pilot whilst preparing the glider for landing. This arises from getting the engine up and handling the effect of the added drag of the extended engine and propellor. It would reasonable to suggest that in this case added work load was the cause of mis-operation of the undercarriage lowering mechanism.", actions: "Debriefed by the CFI . Reported to the CSO for adding to the Safety Lessons Log.", volume: 2 },
  { id: "2023-07-34", date: "2023-07", displayDate: "July 2023", year: 2023, title: "This reports a canopy coming open whilst a", report: "This reports a canopy coming open whilst a glider was mid launch. The canopy edge lifted about 3 inches. The pilot was able to hold the canopy down using an elbow, until it could be locked it down at the top of the launch, so enabling the flight continue with no further consequences. The pilot recalls the following pre-launch actions …”completed the checks: brakes closed and locked, canopy closed and locked and resisting upward pressure \". Post flight the canopy locking mechanism was inspected, more than once, and found to be operating normally and securely. It was found however that it was possible to position the locking lever in the locked position without engaging the mechanism which would keep the canopy locked. The pilot accepts that the check to resist upward pressure check may not have been carried out with sufficient application of upward pressure.", lessons: "The opening of canopy in flight is a potentially serious occurrence. It was fortunate that in this case the pilot noticed what was happening, reacted promptly with actions to recover the situation thus avoiding any potential damage or other consequences. Managing Flying Risk has these words for the check on the canopy: \"CANOPY closed, locked and doesn’t open with applied pressure?\". That implies that as well as the familiar upward pressure applied above/behind the head, the check should include confirming that the locking lever is in place by looking, and if pressure is applied in the opening direction, to any canopy component, including the locking lever, the canopy doesn’t open. The latter are particularly relevant for heavier (e.g. two-seater) canopies. After a previous unrelated SLL report of a canopy on another glider type which was found to be insecure, and not applicable to this incident, it was advised that the hooker on should help by looking for and querying any misalignment or gap between the canopy edge and the fuselage. This advice should be added to that for the hooker on in the Ground Training Manual.", actions: "Reported in the Safety Lessons Log Recommendation re the Ground Training Manual to be referred to the relevant manual editor..", volume: 2 },
  { id: "2023-06-35", date: "2023-06", displayDate: "June 2023", year: 2023, title: "The following summary is based on written reports", report: "The following summary is based on written reports from the pilot, launch point crew, winch driving crew and a witness. During the Take up Slack phase of a launch, the glider began to roll forward, the glider main wheel moved ahead of the cable strop, whereupon the strop was seen to have been lifted by the wheel into the wheel box near the time that the All Out command was given. This was seen by at least the Launch Marshal and others who issued the command to stop the launch. The operator of the signals control unit when attempting to comply, mistakenly pressed the rim of the stop button, rather than on its centre. Consequently, the stop signal light was delayed. By the time the stop light became illuminated, the glider launch was under way with the winch cable pulling the glider via the strop engaged with the wheel. Whilst the glider continued to launch, attempts to request the winch crew to stop by PMR radio were not effective. The winch crew however became aware that the glider was unable to release the cable, because it failed to do so at the normal time and was not flying in a normal direction. Without delay the winch crew operated the guillotine allowing the glider fly away from the winch. The glider pilot, in communication with the launch point by air band radio, was informed that the cable had been guillotined and that the glider was trailing the strop, parachute and the full launch length of Dyneema cable. The pilot made a circuit of the airfield and landed without any further consequences.", lessons: "This was a very serious incident. If a glider flies away from the winch with the pilot unaware that it is still connected to the winch, having failed to release from it, the consequence can be fatal. The glider could be pulled down without any ability to regain control. It helped that the trapping of the strop by the wheel was noticed by the launch crew and that the winch drivers became alert to the situation. The first of two emergency mechanisms, the stop light signal, was too late to be effective, but the guillotine was operated at the right time and this prevented possible further consequences. Factors that were contributory were … The glider had been positioned for launching on ground which sloped down in the direction of the launch. The LM manual specifies measures to prevent the glider rolling forward over the strop during TUS. Answers to enquiries revealed that none of these were applied. It has been learned that the focus of attention of winch drivers necessarily switches early on during the launch from the signal lights to the glider on the launch. After that point a stop light signal is probably not seen and thus can be too late to stop the launch continuing. ____________________________________ Action Taken (this transferred from column 3) Recorded in Safety Lessons Log Actions agreed by CFI, Chf Lnch Mstr and Dpty, Wnch Mstr, Grnd Trng Coordntr, Safety Offiicer A number of actions were identified to mitigate against a repetition, or improve response. These are listed here with appointed actioners. o Remind LMs and launch point crews and pilots of the current contents of the LM Manual that refer to the mandatory action to prevent any rolling forward by a glider between the attachment of the cable, and the signaling of All Out for initiating winch acceleration.[ CLM issued bulletin 19/7/23] o Add to daily checks the functioning of STOP lights buttons on the launch point vehicle and reminding launch point crews that they are there and available for emergency stop action. [CLM issued Bulletin 19/7/23] o Review use of the signals control unit with a view to avoid mis-operation. [ For DCLM ] ......continued in column 3", actions: "o Review radio communications protocol and mechanisms between the launch point, the winch and a glider on the launch so that any emergency messages are unambiguous and heard by all three listeners. [For Flying Committee] o Ensure that the audible confirmation of launch and stop signals can be clearly heard at the launch point. [ For DCLM ] o Continue to pursue the purchase of a system that enables a stop command from a device held by the LM to display a stop signal and sound an alarm in the winch. [For Flying Committee] o Document and issue guidance to pilots about actions in the event of a hang-up. [For Flying Committee] o Confirm that a record is updated of routine checks on the action of guillotines. [For Winch Master] o Add training for launch signals operation to the Ground Training Manual. [ For Ground Training Coordinator] o Review the specification of strops with a view to making them less prone to being picked up by a wheel. [Winch Master]", volume: 2 },
  { id: "2023-04-36", date: "2023-04", displayDate: "April 2023", year: 2023, title: "A family of 8 (adults and children) walked", report: "A family of 8 (adults and children) walked from East to West across the airfield from the hangar towards the wind sock during flying operations. The group were booked in for introductory flights and had visited the site for that. There were 2 (at least) gliders in the air. Launching was stopped and there were no consequences. Members of the group were asked why they had not complied with signage or the guidance in documents sent to them. No satisfactory answers were obtained.", lessons: "This occurrence has been designated a safety incident. It was fortunate that no gliders were landing at the time, so the possibility of collision with pedestrians incurring severe injuries did not arise. Whilst a significant amount of safety guidance is always sent to purchasers of vouchers for introductory flights, and is on display in the car park for visitors, it was concluded that the responsible adults in this group had not been sufficiently prompted to comply with guidance about not venturing onto the airfield. Consequently, a review has commenced of documents sent to voucher holders, the protocol for the ensuing visits of these voucher holders, and the signage which is in place, all of which should prevent safety occurrences of this kind. The objectives are to more effectively draw attention of visitors to inherent dangers and how they must avoid them.", actions: "Recorded in the Safety Lessons Log The documentation sent to voucher holders is to be improved. Action: Admin Officer, CSO and Office Staff. Signage directing pedestrians to launch points and to keep off the airfield to be enhanced. Action: Airfield Officer and CSO.", volume: 2 },
  { id: "2023-02-37", date: "2023-02", displayDate: "February 2023", year: 2023, title: "At a daily inspection it was found that,", report: "At a daily inspection it was found that, although full deflection was possible, some restriction was found in the freedom of movement of an aileron on deflection by the stick. Inspection of the derigged wings revealed a fault in the control linkage in one wing. After that was corrected the problem was resolved.", lessons: "It was apparent that the fault had not been noticed and recorded in spite of the glider having been DI’d and flown with the issue. What was found by inspection did not endanger safety, but the lesson here is that what appears as unusual at DI should be reported for investigation and never dismissed without reporting.", actions: "Completed as described. Recorded in Safety Lessons Log", volume: 2 },
  { id: "2023-02-38", date: "2023-02", displayDate: "February 2023", year: 2023, title: "Pilots of a club single seat glider reported", report: "Pilots of a club single seat glider reported that unfamiliar sounds were heard on landing. After inspections and test flying it was established that a worn bearing in the main wheel was moving inside its housing. The bearing was replaced and secured in the wheel with a locking compound.", lessons: "The reporting by pilots ensured a timely repair that may well have prevented further damage by a totally seized wheel.", actions: "The action required was undertaken by the in-house glider maintenance team. Report added to the Safety Lesson Log", volume: 2 },
  { id: "2022-11-39", date: "2022-11", displayDate: "November 2022", year: 2022, title: "A single seat medium performance flapped glider landed", report: "A single seat medium performance flapped glider landed on an area of moorland approx 200 meters east of the airfield. The pilot was not injured. The glider was not damaged. The wind was 10-15knt WNW. Visibility was “excellent”. Soaring in wave lift to the west of the site was achievable from launch top height at c.1300 feet. From observers reports and the pilot debrief the glider started a circuit flying to the east from a high key area at c.1200 feet NW of the airfield. The pilot reports setting landing flap at this point. This downwind leg was observed by launch crew to take the glider unusually far east before continuing to descend further whilst flying a cross wind leg tracking to the southeast. On turning west to approach, it became evident to the pilot the airfield could not be reached, so a landing, without incident, was made on the moor. On debrief the pilot admitted to flying whilst stressed about his lack of familiarity with use of flaps settings, his concern about the turbulent conditions and also probably not able to comply with one or more aspects of the IM SAFE mnemonic", lessons: "This was an incidence of a not unknown event at Camphill. It is an established fact that in westerly winds there is significant descending air to the east of the airfield. This is known as the Clutching Hand – a meaningful description of how gliders lose height quickly when in the circuit over the moor. In wave conditions the effect can be even more pronounced. Pilots landing to the west are briefed to fly the cross wind leg with a high look down angle to the reference point, being close to the eastern boundary of the airfield and then accept the need for a steep descent after the final turn onto the last part of the approach to land. After two debriefs it was accepted that the pilot had, in the circumstances outlined in the report above, lost or lacked judgement to cope with the conditions prevailing at Camphill on the day. This incident also exposed the need for pilots converting to flapped gliders to become familiar with the effect on glide angle of landing flap settings.", actions: "Detailed debriefs undertaken by the duty instructor and by the CFI. The pilot was asked to undertake some retraining which included using the simulator to practice landings to the west in a glider with flaps. Added to SLL", volume: 2 },
  { id: "2022-10-40", date: "2022-10", displayDate: "October 2022", year: 2022, title: "Safety lesson", report: ". The \"hooker on\" noticed that the ring could not be freely placed in position on the launch hook mechanism, despite full operation of the release handle. The release mechanism failed the free fall test and the planned launch was abandoned. On inspection, it was found that the cable from the release handle to the release mechanism had come off a pulley and become jammed between it and the bulkhead. Further research in the aircraft's Workshop Manual showed that a collar over the pulley was misaligned. Another pilot, who was familiar with the type was aware that correct alignment of the collar, prevents such an occurrence.", lessons: "The right practice is that the hook of a glider is checked during DI using a spare set of “Tost” rings. That check should test that when the cockpit hook release is operated, 1. the rings drop off under their own weight (a ”free drop”), and 2. that they come away from the hook when under forward tension. Also 3. that when pulled backwards they “back release” from the hook. These safety checks are critically important and anything that looks, feels or sounds unusual must be investigated and a remedy found and implemented. The \"hooker on\" is to be commended for reporting this malfunction which could have had serious consequences had it not been identified.", actions: "Reported to CFI . Reported to Aircraft officer Occurrence added to the SLL", volume: 2 },
  { id: "2022-10-41", date: "2022-10", displayDate: "October 2022", year: 2022, title: "Safety lesson", report: ". During a first launch on type the airbrakes of a single seat glider were seen by the ground crew, to open on the ground run and remain open throughout the launch to approximately 500 feet agl. The pilot closed the brakes after completing the launch. Also, at that point a radio call from the ground was made to advise what had happened. Post flight the pilot reported that he was preparing to undertake a landing away from the airfield but after closing the airbrakes it became clear that a safe circuit could be – and was - completed. The airbrake locking mechanism was checked after the flight, by another pilot who was familiar with the type and found to be satisfactory. It transpired that the owner had misunderstood the airbrake locking process, which is not specified in the Flight manual. A second launch and soaring flight was carried out without incident.", lessons: "It was learned that the airbrakes locking mechanism on this glider is by the mechanical “over-centre” operation common to most gliders and which requires a firm push forward of the brake lever until it is holds itself against back pressure in the fully forward position. During conversion to a new type, pilots must be sure they have familiarised themselves with the feel of the airbrakes locking mechanism and its operation", actions: "Pilot de-briefed by CFI Occurrence added to the SLL", volume: 2 },
  { id: "2022-09-42", date: "2022-09", displayDate: "September 2022", year: 2022, title: "At the stage of steepening the climb angle", report: "At the stage of steepening the climb angle of a winch launch, between 10 and 20 feet, without being released, the cable separated from the glider. The subsequent recovery action failed to avoid the glider landing very heavily on its wheel and belly. The pilot suffered some spinal injury. Some of the structure of the fuselage under the seat and undercarriage was damaged. The local wind strength was recorded as fresh & variable (“gusting”).", lessons: "No fault was found with the hook mechanism or the cable attachment components so there was no clear explanation for the un-commanded release. Reports from the pilot and those who witnessed the occurrence do suggest that failure to recover from the launch failure was probably due to loss of sufficient airspeed, maybe influenced by the gusty conditions.", actions: "Reported to Emergency Services (who responded). Reported to AAIB (no response), BGA, CFI and Safety Officer. Entered as occurrence into Safety Lessons Log.", volume: 2 },
  { id: "2022-09-43", date: "2022-09", displayDate: "September 2022", year: 2022, title: "A pair of cars with gliders being towed", report: "A pair of cars with gliders being towed tail first were stopped, both facing in the same direction, on a down slope, one ahead of the other. The towing system of the gliders required nobody but the car drivers. Whilst the drivers of each car were out of the vehicles, the car higher up the slope ran forward and struck the glider ahead of it. The glider lower down the slope suffered damage to a wing and to its rudder. The bar connecting this glider its tow car was significantly deformed. The car also suffered some damage. The damaged glider required repair at the premises of a professional repairer. The driver of the car that ran forward has reported doubt about whether it was left in gear as the car manual advises because of uncertainty about the effectiveness of its electric parking.", lessons: "In terms of damage, it was fortunately less extensive than it might have been. The history of expensive consequences of accidents and incidents whilst moving gliders around should teach us how important it is to ensure that the vehicles and towing equipment are in good order and used with significant care especially with modern electric parking brakes. The up and down slopes of our airfield add to the level of attention needed. There were no known issues with vehicle insurance in this case, it does highlight the need to ensure that vehicles parked or used on the airfield are appropriately insured. This incident also reminds about the importance of securing tractors against running away on slopes, by always leaving them with hand brake on, in gear and with either high or low ratio selected.", actions: "The occurrence was added to the SLL", volume: 2 },
  { id: "2022-08-44", date: "2022-08", displayDate: "August 2022", year: 2022, title: "It was discovered that the bottom edge of", report: "It was discovered that the bottom edge of the rudder of a K18 had been punctured three times. The occurrence of damage had not been reported and not discovered during daily inspections. This is not the first time such damage has been found. The damage required that the glider be taken out if service for repair.", lessons: "This component is made of thin plywood and forms part of the structural integrity of the rudder. It is easily pierced by being lowered onto the spigot of the towing dolly which is inserted into the glider’s tail skid for towing. Consequently, the integrity of the rudder structure was impaired and the holes allow the ingress of debris and water. It’s clear that there had been lack of care when lowering the tail skid onto the towing dolly. Those DI’ing K18s are reminded that they should look for this damage. This is a critical part of the rudder construction and should be reported when seen.", actions: "Reported to the Aircraft Officer who sent an email to all pilots notifying them of the damage and requesting consistent care with attaching the towing dolly and the importance of the need to report such damage Added to Safety Lessons Log", volume: 2 },
  { id: "2022-08-45", date: "2022-08", displayDate: "August 2022", year: 2022, title: "During an instructional flight in a two seat", report: "During an instructional flight in a two seat glider, one of the ballast weights came partially detached from its fixing during a winch launch. One of the attaching bolts fell into the bottom of the fuselage. The ballast weight in question had been checked prior to the launch and was believed to be secure. There were no consequences of this event.", lessons: "Whilst there were no consequences, it worth noting that any solid or heavy object which is insecure is a significant danger if it can move within a glider to where it could prevent the free movement of a flying control. There have been serious accidents from such causes. Whilst a pre-flight check was correctly carried out, this event shows that the condition of ballast fixings requires close attention.", actions: "The ballast weights were taken out of service and subsequently the securing bolts were repaired. Reported to CFI, Aircraft Officer and Safety Officer. This entry added to Safety Lessons Log.", volume: 2 },
  { id: "2022-06-46", date: "2022-06", displayDate: "June 2022", year: 2022, title: "A visiting glider (Capstan) was at the take", report: "A visiting glider (Capstan) was at the take up slack stage of a launch when it was stopped by a call “STOP” made it is believed by the pilot, presumably because he had detected that a rudder lock was still in place. The device was in the form of a wooden wedge about 12cms long and 3cms high, painted the same colour as the glider, fitted between the bottom of the rudder and the tail plane. The LM reports that he nor the ground crew had been notified of the use of this device .", lessons: "Because of the nature of the device and its difference from rudder locks used at Camphill, the LM nor ground crew had noticed it before the launch routine was started. But more importantly, it is evident that the pilot had not properly completed all checks. I.e. he had not ensured that the rudder was free to move, during external ABCD checks prior to boarding, nor had detected it during pre-fight cockpit checks prior to accepting the cable.", actions: "Reported to CFI for amendment to Visitor Pilots’ Manual. Entry made in Safety Lessons Log by the Safety Officer. Recommendation made to CLM re amendments to LM Manual: - extra care needed with visiting pilots ; - form of rudder lock may be specific to glider type.", volume: 2 },
  { id: "2022-06-47", date: "2022-06", displayDate: "June 2022", year: 2022, title: "A visiting pilot, who had flown nine solo", report: "A visiting pilot, who had flown nine solo flights at his own club, was cleared for solo flight at Camphill. He was preparing to strap into the Ka8 when a resident solo pilot asked if he needed the additional ballast weights. It was only then that the pilot checked the placard limits. It was found that his weight, together with a parachute was below the minimum. The ballast weights were fitted and the first solo flight on type was conducted without incident.", lessons: "When de-briefed by an instructor, the pilot owned up that he had forgotten to carry out the ABCD, pre-flight check which he usually did. He was aware of the possible consequences of flight below the minimum cockpit loading and the BGA recommendation that the minimum cockpit load should be exceeded by at least 15lbs when flying a new type or for early solo flights. A special flying event was taking place that week and a large number of visiting pilots were in attendance. It is thought likely that the excitement and distraction of the circumstances for a relatively inexperienced pilot caused the oversight", actions: "Pilot de-briefed. Supervising instructor informed. CFI informed Reported in SLL", volume: 2 },
  { id: "2022-05-48", date: "2022-05", displayDate: "May 2022", year: 2022, title: "In a brisk wind ( 15 – 20", report: "In a brisk wind ( 15 – 20 kt WNW) day a glass single seat glider abandoned a winch launch from the East launch point after a wing tip dropped to the ground. The pilot reported that the wingtip holder had hung on a reasonable time but the left wing dropped as soon as it was let go. The pilot released the cable immediately and rolled down the slope to the peri track, stopping just before it, having used full wheel brake. The plot judged that the conditions were not suitable for another attempt. He mentioned that the type was susceptible to wing drop in the prevailing wind conditions. It was not reported whether STOP was called by the wing runner or after the down-going wing hit the ground", lessons: "The pilot acted immediately in the correct way and so prevented a potentially serious crash outcome in which the upper wing lifts the glider whilst yawing round the lower tip on the ground – sometimes referred to as a “cartwheel”. The incident was the first to be reported under a policy of recording all such incidents together with specified data.", actions: "Following this a list of data required after a wing drop was specified in a Chief Launch Marshal’s Bulletin. This entry was recorded in the Safety Lessons Log", volume: 2 },
  { id: "2022-05-49", date: "2022-05", displayDate: "May 2022", year: 2022, title: "After a landing to the S and coming", report: "After a landing to the S and coming to a stop the left wing tip of a glider scuffed the wall of the vehicles storage shed, and the wing tip was slightly scuffed also. Although the wind was light WSW, because of the presence of HGs/PGs near to the N & W of the airfield, the standard circuit for the time was L/H. In the downwind leg the pilot encountered more than expected sink, so abbreviated the circuit, then significant lift during the left turn onto approach. To avoid both two landed gliders in the normal landing area for a SW wind and to avoid landing on the cables, the pilot opted to land to the S on the east side of the cable run. The landing was longer than expected because of, in the pilot’s view, the lack of headwind. In spite of application of wheel brake and rudder the landing run was affected by the cross slope and ended as described above.", lessons: "It appears that the direction of landing chosen here was the least best of the options available. The lesson learned is that where there are obstacles, particularly buildings, that might be difficult to steer away from on landing, always choose a lower risk, safer, landing direction that is less potentially affected by any overshoot, cross wind or slope.", actions: "The pilot was debriefed by the duty instructor. The incident was reported to the CFI This entry was made into the Safety Lessons Log. The damage to the glider was formally inspected and declared to be superficial.", volume: 2 },
  { id: "2022-05-50", date: "2022-05", displayDate: "May 2022", year: 2022, title: "Not for the first time the tell-tale wire", report: "Not for the first time the tell-tale wire that threads through the hinge pins of Puchacz canopies to prevent the pins from too easily being pulled out of the hinge AND/OR to indicate that the pin had been migrating by creep out of the hinge, was found broken, the break being hidden. At the same time it was also found that the pin that retains the attachment of the canopy opening restraint wire to the canopy was partly, but significantly, withdrawn.", lessons: "This occurrence may have happened by inadvertent partial operation of the canopy jettison lever that releases the canopy from the glider to enable a bale out. Care must be taken to monitor for and prevent this. It has been considered more likely that the occurrence was due to creep of the hinge retaining pins as a result of day to day opening of the canopy. The occurrence has significant importance because of the serious consequences of an unintended jettison of a canopy in flight. Even on the ground the damage can be very costly to repair. It has been accepted that breaks in tell-tale wires are easily hidden where they pass through the hinge pin and so guidance to those who DI the Puchacz should be issued to take account of this. It has also been accepted that the tell-tale wire are easily broken and that a more robust specification should be fitted", actions: "Recorded in SLL and referred to CFI by CSO Referred to Aircraft Officer who has fitted more robust tell-wiring and has issued a photo to illustrate the way to apply that. Members who DI the Puchacz have been briefed by CFI on the findings of this incident and issued with guidance on the daily inspection of the security of canopy hinge pins.", volume: 2 },
  { id: "2022-04-51", date: "2022-04", displayDate: "April 2022", year: 2022, title: "On more than one occasion the quick release", report: "On more than one occasion the quick release coupling that joins the strop and weak link to the cable parachute became separated on its own accord. On one occasion this resulted in a launch failure during Take Up Slack. On investigation it was discovered that the jaw of one or more of the couplings in use had widened through wear.", lessons: "It is believed that a coupling is not liable to become detached because of the wear observed whilst under tension from All Out onwards. If that is the case then there no additional risk of a launch failure from this. However, the couplings in use are believed to have been in use for several years so a routine check is required. It was commendable that the deterioration of the couplings in use was discovered through watchful investigation.", actions: "Reported to the CFI, CSO and Winch Master. Recorded in the Safety Lessons Log The coupling hooks on all cables have been replaced with new. The documentation of the routine checks on the condition of the cable termination components (Tost rings, strop, weak link, parachute and shock rope) to include the coupling hook.", volume: 2 },
  { id: "2022-04-52", date: "2022-04", displayDate: "April 2022", year: 2022, title: "The wing dolly of a private glider, whilst", report: "The wing dolly of a private glider, whilst it was being taken out of its hangar, collapsed. This caused the tail of the glider to strike the structure of the hangar. As a consequence, the tailplane and fin were damaged to an extent that a repair was required at the workshop of a repairer.", lessons: "This unfortunate occurrence does show how vulnerable gliders are when being manoeuvred in confined spaces. Repairs to damage occurring as a result of wing or tail dollies failing are often very costly and can require a glider to be out of action for weeks. Consequently, the general lesson here is that any defects and deficiencies in wing dollies and tail dollies should be looked for whenever they are to be used, or in are use, and dollies should be considered unserviceable until improved or repaired", actions: "The occurrence was reported to the CFI, CSO, BGA and added to the Safety Lessons Log. All involved in towing gliders using dollies should take care to apply the lesson contained in the Conclusion / Lesson Learned.", volume: 2 },
  { id: "2022-01-53", date: "2022-01", displayDate: "January 2022", year: 2022, title: "A strop, shock rope and cable parachute lying", report: "A strop, shock rope and cable parachute lying very near the feet of two launch point crew (LPC) , were “whipped away” under winch power without warning. Launching had been suspended due to weather conditions. The two LPC were in conversation with the pilot in the glider. The glider was not hooked on. Unknown to the two near the glider a decision had been made to end flying for the day. Another member of the launch point crew (LPC3) communicated with the winch driver (WD) that unused cables could be wound in. There were two other cables lying in the normal waiting position. It was the cable near the glider that the WD chose to wind in first, presumably because it would have been the next for launching. Light signals were used for only the first cable to be wound in and the other two wound in at the WD’s discretion. Even though light signals were used for the first wind-in, it was as reported, begun without a slow take up slack.", lessons: "There was some danger of serious injury by entanglement of cables with the legs of two members of the LPC. It was confirmed that the person requesting the wind in of cables, LPC3, was unaware of the cable lying near the glider. Subsequent investigation established that there was no protocol (e.g. use of signal lights) for the safe wind-in of cables for the launch marshal or winch driver to follow. The incident was a reminder that all must be aware of the hazards associated with cables moving under power.", actions: "The incident was reported to the Safety Officer as one for the entry in the Safety Lessons Log. The incident was also reported to the Chief Launch Marshal and the Winch Master. Members are reminded that a protocol for the winding in of unused cables has since been established and inserted into the Launch Marshal’s Manual. A reciprocal entry in the Winch Manual has been requested.", volume: 2 },
  { id: "2022-01-54", date: "2022-01", displayDate: "January 2022", year: 2022, title: "A Skylaunch winch ran away out of control,", report: "A Skylaunch winch ran away out of control, down the sloping apron from the mechanical workshop entrance and was stopped from colliding with the office cabin by the safety bollards protecting it. The winch had become detached from its towing vehicle as it was backed out of the mechanical workshop. It was established that the coupling to the tow vehicle had been prevented from secure locking, prior to it being driven into the workshop, by the insertion of a pebble chock under the coupling release handle. This had been inserted earlier at the winching location to assist unhitching prior to flying. Its presence and the need to remove it before towing was not known to the vehicle driver. There were no injuries. 3 bollards were demolished. There was some superficial damage to the winch.", lessons: "It was hugely fortunate that the winch did not become uncoupled where it would have caused much more serious damage and maybe injury as well. The danger of the use of a chock to hold open the hitch on a winch towing mechanism was identified in this log in September 2020. It is regrettable to see/find that the lesson was not applied. It must be discontinued. All members coupling and un-coupling winches to tow vehicles must be made aware of a correct and safe method and this training recorded. An emergency restraint cable that prevents a winch from totally separating from a tow vehicle must be fitted and used when towing. A notice should be attached to the winch that warns that the coupling handle must be in the down position and locked prior to towing . Action Taken Although this was not a flying incident, because of its seriousness and that it was connected to a flying support activity, the Safety Officer made a report to the Club Committee. Under direction of the Committee, all members have been circulated by the winch master and by the club mechanic, notices to discontinue the practice of chocking open the coupling mechanism, and which describe a method of unhitching that obviates the need for a chock. Continued > Column 3", actions: "... contiinued from Column 2 A warning of the potential for litigation following serious damage or injury from such incidents has been noted. . Actions to comply with the lessons learned (see column 2 to left) have been initiated.", volume: 2 },
  { id: "2021-12-55", date: "2021-12", displayDate: "December 2021", year: 2021, title: "Safety lesson", report: ". A K8 took a launch to the North which was abandoned when it entered cloud. After descending to 400 feet agl, then making turns to improvise a circuit using intermittent and limited visibility of the airfield below, the glider landed normally on the airfield, in a northerly direction, without consequences. At the time of landing, or shortly after, the visibility on the ground was said be between 50 and 100 meters. On the day, flying had been started after conditions allowed. The wind was reported <5kts ENE. It was reported that mist filled the valleys surrounding the airfield. Some of the valley mist or fog was spilling over the airfield from the east and south of the site. There was low cloud over the moor to the east. On the day there had been 8 previous short but unremarkable flights. In preparing for his launch, the pilot sought and got a positive briefing from a senior instructor present. The launch was about 10 minutes after that. More than one report noted how rapidly conditions were deteriorating to non-flyable. Before proceeding with the launch the winch driver reported deteriorating conditions by radio to the launch point. After the occurrence flying was stopped for the day.", lessons: "It was fortunate that this flight ended with no adverse consequences. There was acceptance that it was a mistake. Lessons to be learned or emphasised are … The hill top location of Camphill makes it occasionally prone to weather which should prevent flying. Examples - the presence of wave rotor over the airfield, (as indicated by the windsock(s)), cloud at or below circuit height, mist/fog obscuring the local out landing fields. Any concern about the safety of launching, should be referred to the supervising instructor. If an individual remains concerned, they may opt not to assist the launch. If conditions deteriorate at all between briefing and launch, a pilot must get re-briefed by the supervising instructor, or another instructor.", actions: "Reports on the incident were obtained from the pilot, the duty instructor, the launch marshal and the winch driver. The CFI and Chief Launch Mashal and Winch Master have been notified of the incident and of the contents of this SLL item. This entry was made in the Safety Lessons Log.", volume: 2 },
  { id: "2021-10-56", date: "2021-10", displayDate: "October 2021", year: 2021, title: "A pilot of a single seater missed his", report: "A pilot of a single seater missed his mobile phone after landing. He believed he had dropped it into the pocket at the side of the cockpit but it wasn’t there. After some searching, the phone was under the seat. The pilot reports that either the phone came out of the pocket in a negative G event or he missed the pocket when dropping it in.", lessons: "The pilot is to be commended for making a search and retrieving the phone from where, if ignored or forgotten, it could have shifted to a place where it could have jammed the movement of the flying controls. Through wear, glider pockets can become insecure closures for mobiles or any other loose objects. If that is the case such items should be placed in securely closing pockets (by zip or velcro) in clothing.", actions: "Pilot thanked for his report. This SLL item copied to Aircraft Officer for information (re any maintenance point?) Entry made in Safety Lessons Log", volume: 2 },
  { id: "2021-10-57", date: "2021-10", displayDate: "October 2021", year: 2021, title: "In landing in a westerly direction, the ground", report: "In landing in a westerly direction, the ground run of a single seat glider crossed the perimeter track on the west of the airfield and came to rest nose down, on a ledge some 10 feet below the airfield level. There were no injuries and damage was superficial. The pilot reported that during the approach the glider pitched nose down in turbulence with increased airspeed. On recovery of stability he reports opening airbrakes fully. The pitching down was confirmed by an eye witness. Logger analysis confirmed significant loss of height with increased ground speed after pitching down, but was unable to confirm a flight path consistent with airbrakes being fully open.", lessons: "During recovery from a rapid loss of height in turbulence, the glider gained increased airspeed. At a point where it would be expected to be rounding out on the upslope, loosing airspeed with brakes fully open, it continued to fly, landing too late to prevent running over the edge of the airfield. It appears that the lesson here is to not allow actions taken to regain control (say because of turbulence) to result in an increased energy (i.e. airspeed) which is more than is safe for landing in the area available.", actions: "Pilot de-briefed by the CFI, then flew with a Full Cat instructor on an extended soaring flight 3 days later. Incident discussed at scheduled instructors meeting. The value of training pilots in safe manoeuvring near the ground was agreed. Occurrence reported to BGA and entered into the Safety Lessons Log", volume: 2 },
  { id: "2021-09-58", date: "2021-09", displayDate: "September 2021", year: 2021, title: "During the early part of a launch the", report: "During the early part of a launch the dead cable lying next to the live launching cable was lifted by the live cable. The pilot detected what was happening, abandoned the launch and landed ahead without any consequences. It was established from damage to the dead, picked up cable, that it had been lifted by the hook connecting the live (launching) cable to its parachute. It could not be established why this connecting hook came to be in a position to cause the pick up.", lessons: "Anything that impairs a successful winch launch (e.g. crossed cables) impacts on safety. Whilst all pilots are trained to handle recoveries from launch failures, however arising, the actions needed require an increased level of care to contain consequential risk. For whatever reason, light weight cables (i.e. Dyneema) don’t always lie low on the ground, can become crossed by being blown in a cross wind, or by being towed along a curved track. Both the Launch Marshals Manual and the Winch Operating Manual specify the responsibilities of the LM and WD roles with respect to ensuring that cables do not become or are crossed, and their actions in the event that they are or may be crossed.", actions: "Reported to CFI and Safety Officer. The Chief Launch Marshal and Winch Master have each agreed to re-enforce the actions specified in the relevant manuals which relate to avoidance of and checking for crossed cables. This event included in the Safety Lessons Log.", volume: 2 },
  { id: "2021-08-59", date: "2021-08", displayDate: "August 2021", year: 2021, title: "Whilst an instructor was demonstrating adverse yaw, which", report: "Whilst an instructor was demonstrating adverse yaw, which induced sideslipping to the left, the canopy opened suddenly, snapping the restraining wire, (which would normally prevent it from opening beyond its normal maximum,) and left the canopy hanging out of the right hand side of the fuselage on its hinges only. The instructor managed to close and secure the canopy. The glider landed without further incident with minor damage to the canopy structure. This was an early training flight. The instructor is confident that he had checked that the canopy was locked and secure by applying upward pressure. Subsequent investigation and reports from other pilots who had recently flown the glider, have established that the movement of the canopy locking lever on this glider was abnormally stiff, to the extent that it may have appeared to be fully in the locked position but was not..", lessons: "The consequences of a canopy opening in flight and possibly separating from the glider are potentially serious. It was fortunate that there was no loss of control. It is important to establish what lessons might be learned. In this case it is unclear. Care must be taken to ensure before launching that canopy locking is not overlooked, and is fully and completely operated effectively, The standard advice requires that the canopy resists upward pressure applied to some part of the canopy structure. This is not readily achievable in an effective way in the Puchacz. Consequently care must be taken to ensure the locking handles are fully and firmly in the locked position. If stiffness is experienced in the locking mechanism that could impede effective locking, it should be considered whether the glider is airworthy, Because of the positioning of the air scoop and sliding window of the front DV panel, then if either are adjusted there could be inadvertent interference with the front locking lever. Those flying the Puchacz should be wary of this hazard. The occurrence should be taken as a reminder of the importance of pre-flight checks by any pilot. These should include the recommendation that when checking anything, the item being checked should be looked at. It is also good practice to \"point at\" the item - which encourages a good look. These should be assisted by the hooker-on asking the pilot to confirm that air brakes are locked and that the canopy is securely locked.", actions: "Reported to BGA Office is & SRE Instructors informed and requested by CFI to emphasise at briefings the value and importance of the pre-flight checks. Added to Safety Lesssons Log", volume: 2 },
  { id: "2021-07-60", date: "2021-07", displayDate: "July 2021", year: 2021, title: "The retrieve tow rope having been attached to", report: "The retrieve tow rope having been attached to a two seat glider, ready for return to the launch point after an IF, the instructor saw that the tractor, without driver, but with engine running, was slowly moving forward and away down the slope on which it had been stopped for the hook on. The instructor ran to the tractor, stopped it moving, turned off the engine, applied the parking brake and left it in gear, then returned to the glider, which had moved forward, but stopped. There were no consequences. The tractor driver was understood to be not very familiar with the tractor type nor stopping the tractor in the best position for the hook on. The tractor parking brake was found to be not reliably effective.", lessons: "Fortunately, through alertness and swift action, this occurrence was brought under control without any consequences. It must be ensured that newer members are taught about and monitored when driving tractors that when parking them, even for a moment, they always adhere to the following : Whatever type of ground, flat or slope, turn the engine off. Make sure the tractor is left in gear. Do not rely on the parking brake, hand or foot.", actions: "Reported to Chief Launch Marshal the Safety Officer and entered into the Safety Lessons Log", volume: 2 },
  { id: "2021-07-61", date: "2021-07", displayDate: "July 2021", year: 2021, title: "A pilot reported that whilst starting a r/h", report: "A pilot reported that whilst starting a r/h circuit to land after soaring the west edge, at the point of crossing the gully to the north of the airfield , a hang glider flew from the north just behind the ridge at Bradwell over our winches toward our windsock. He estimates they were at similar heights - around 400ft QFE. The pilot reported that he didn't see the HG until he was very close and that he took avoiding action by slowing down and turning left to go behind the HG. He estimated the distance from the HG to be 20 feet. The occurrence was reported to the Chief Coach of Derbyshire Soaring Club.", lessons: "In discussion with the DSC representative, it was agreed that no further action can or should be taken but that lessons should be learned. From the point of view of DLGC pilots, the event reinforces the need for pilots to be vary watchful indeed of other aircraft in or near the circuit at the chosen circuit height. This requires continuous and repeated look out in all directions and having an avoidance plan in mind. When HGs and PGs are nearby there is a need to take account of their relatively slow speed, their smaller turning circles and higher rate of climb in the core of thermals. Also that HG and PG pilots have a restricted view upwards.", actions: "Reported to:- the CFI DSC the Safety Officer. Item entered into the Safety Lessons Log", volume: 2 },
  { id: "2021-06-62", date: "2021-06", displayDate: "June 2021", year: 2021, title: "After being warned that a member had emailed", report: "After being warned that a member had emailed the duty instructor that he’d lost track if a pair of spectacles, having flown a K18 the previous day, the person undertaking a DI on that glider decided to take out the seat. With the aid of a torch the spectacles were located in their case in the bottom of the fuselage some 3 feet behind the seat.", lessons: "A loose object inside the fuselage of a glider has significant potential for jamming the flying controls. As soon as such is suspected, immediate and exceptional steps should be taken to ensure, without doubt, that a search is undertaken before the glider is flown again. It is not known how the spectacles were dropped inside the glider, but there is a question of whether they fell out of a pocket without closure (e.g. unzipped).", actions: "Reported to the Safety Officer Recorded in the Safety Lessons Log", volume: 2 },
  { id: "2021-06-63", date: "2021-06", displayDate: "June 2021", year: 2021, title: "On approach to land to the SW, a", report: "On approach to land to the SW, a pilot found himself unable to land without flying over the edge of the airfield, in spite of attempts (he believed) to open the air brakes. After altering his direction of approach, the pilot flew over the airfield edge and successfully landed off the airfield, in a field. On this glider type, it is not possible to open the airbrakes if the flaps control is not engaged in one of it’s 5 possible detents. Nor alter the flap setting if the airbrakes are deployed.Whilst the relevance of it is not clear, after the event, the pilot had an inspector examine the airbrakes mechanism. It was found to be defective. A new part was needed.", lessons: "It was deduced and agreed later with the pilot, that in coping with the situation, he was either pulling the flaps lever, (with obviously no airbrake effect) or on the airbrakes lever (which would not move because the flaps lever was not engaged in a detent). Confusion between levers involving the airbrakes is not uncommon. So the advice is always to positively look and check that the airbrake lever has been got hold of. It was commendable that the pilot managed to select and successfully land in a field.", actions: "The flaps setting mechanism was repaired on the advice of an inspector. The pilot was debriefed by the CFI. A report (re the faulty flaps setting mechanism) is to be sent to the BGA technical officer. The occurrence was recorded in the Safety Lessons Log.", volume: 2 },
  { id: "2021-06-64", date: "2021-06", displayDate: "June 2021", year: 2021, title: "During a landing to the NW a glider’s", report: "During a landing to the NW a glider’s undercarriage door struck a yet to be used Dyneema cable. It was consequently pulled by that to the end of the ground run. The cable made a cut of about 1 inch in the u/c door. There was no other damage. The cable parachute had at the time been taken to the next glider waiting to launch and was left un-held whilst the landing glider landed. The parachute was “whipped away” as the glider caught the cable.", lessons: "It is known that Dyneema cable does rest above the level of the grass, more so when it is under any remaining tension. Unless and until a solution to this is found, pilots should aim to avoid allowing their landing run to cross the cable run unless it known that there are no cables on the field. It was commendable that the launch point crew were complying with safe practice by not holding the cable at the time.", actions: "The identification of a practical way to help prevent such occurrences remains under consideration. Notified to the CFI. Recorded in the Safety Lessons Log.", volume: 2 },
  { id: "2021-05-65", date: "2021-05", displayDate: "May 2021", year: 2021, title: "A single seat glider landed to NE up", report: "A single seat glider landed to NE up the slope at the N end of the airfield. The ground run ended with nose and a wing tip just touching the boundary wall. The only damage incurred was superficial. The wind was c. 15kt E with some veering to ESE. Circuits at the time were left hand with landings to the south. The pilot having encountered unexpected sink opted to not fly the circuit in use but to approach as described above during which the need to over fly winch cables, a higher than needed speed and becoming momentarily airborne again due to uneven ground, lead to an overshoot.", lessons: "The approach chosen is a safe and proven one when the launch point is in the lower, NW corner of the airfield. On this occasion the launch point was positioned in the higher NE corner. This was to avoid congestion and approach obstacles in the NW area. The consequence was that the cables were nearer the East boundary so reducing the available landing run after over flying them.", actions: "The conditions under which the North East launch point is used are under review. Recorded in the Safety Lessons Log.", volume: 2 },
  { id: "2021-05-66", date: "2021-05", displayDate: "May 2021", year: 2021, title: "Whilst a K8 glider was being prepared for", report: "Whilst a K8 glider was being prepared for a launch, a member of the launch point crew noticed that the glider was being hooked on with a higher rated weak link than specified for the glider type. The hooker on was stopped and de-briefed and then the correct weak link was used.", lessons: "The correct breaking strain of the weak link for each type of glider depends on the forces and aerodynamic loads that can be applied to the glider structure. A too low rated link can break unnecessarily which involves the enhanced risk of a launch fail recovery. A too high rated weak link can fail to protect a glider structure from over loading. Weak links are colour coded and when the glider has a colour marking near the wheel the colours should match. If you are in any doubt about the correct link, ask the pilot. This was a good example of alertness by the launch point crew.", actions: "Reported to the Chief Launch Marshal Entered in the Safety Lessons Log", volume: 2 },
  { id: "2021-05-67", date: "2021-05", displayDate: "May 2021", year: 2021, title: "A paraglider (PG) pilot reported that a glider", report: "A paraglider (PG) pilot reported that a glider flew directly under and very close to him. This was supported by a video recording made on board the PG. The video shows the glider turning on the outside of the turn of the PG with both turning to the right at the same height. The distance between the two increased as the glider’s turning circle was much wider. After 40 seconds the glider is seen in an approximately 30 degrees banked r/h turn which continued until it was flying head on towards the PG pilot’s right hand side, then flying directly under it. From the video it has been estimated that there was a vertical separation of about 3 metres between the turning glider’s higher wing tip and the PG pilot . In an email the PG pilot stated he was unsure whether he joined the thermal \"sufficiently considerately\". In an oral report the glider pilot stated that he accepted that he wasn’t aware of the relevant PG at the time of the close encounter. He also stated that at the time of the incident about 8 to 10 PGs were soaring in a thermal near which he was also attempting to soar . The incident is reported to have occurred whilst both the PG and the glider were soaring in thermal lift in clear visibility over Bradwell Edge at approximately1800 feet agl .", lessons: "This was very nearly what in all probability would have been a fatal mid air collision. No explanation has been established as to why the glider pilot did not see that a paraglider was ahead of him nor took any avoiding action. Compared with gliders, the relatively low airspeed, small turning circle, higher rates of climb in thermal cores and their propensity to cluster make it relatively difficult to fly with PGs in thermals. Joining, sharing and leaving a thermal with other soaring aircraft requires a high level of airmanship, control and spatial awareness. It is critically important to be aware of the positions of the other aircraft at all times, to the point that, if a contact is lost, the safest action is to leave the thermal. It is also important to position your aircraft in such a way that the other aircraft can see you. A constant, careful and thorough lookout is essential. A known hazard is that a pilot concentrates on, and is distracted by, a recognised potential conflict so that a new conflict is not picked up. Potential new conflicts must always be expected and looked for.", actions: "The glider pilot spoke with the PG pilot. The CFI * de-briefed glider pilot *notified SRE. *issued Safety Message to DLGC pilots. *submitted report to Airprox Board which issued AIRPROX REPORT No 202105", volume: 2 },
  { id: "2020-12-68", date: "2020-12", displayDate: "December 2020", year: 2020, title: "Safety lesson", report: ". Whilst there were problems with a misting canopy, the hooker on and pilot had a discussion about hooking on whilst the canopy was open. They were briefed by the LM that this was against both BGA and Club rules.", lessons: "To reduce the risk of the potentially serious consequences of a canopy opening during a launch, a cable must not be attached to a glider nor remain attached whist its canopy is open. If misting of the canopy is likely to be a problem, the correct procedure is as outlined in the Launch Marshals’ Manual, section 6.5, (Launch Supervision).", actions: "Referred to the Chief Launch Marshal Entered into the Safety Lessons Log", volume: 2 },
  { id: "2020-11-69", date: "2020-11", displayDate: "November 2020", year: 2020, title: "Nov", report: ". A single seat glider was seen to be circling in weak lift at about c. 500 or 600 feet QFE off the SW corner of the a/f . The witness “saw the glider nose down steeply and complete two full turns of a spiral dive before pulling out (estimated at around 200 ft QFE), at which point the pilot recovered a little height, executed a left turn onto final approach and landed safely on the airfield.” On debrief the pilot told an instructor that he had been flying slowly, on purpose, to try to make the most of the weak soaring conditions and realised he had overdone it. He said the wing dropped but he recovered using spiral dive recovery action.", lessons: "A loss of 300 or 400 feet whilst executing two full turns after a wing drop (in other words a stalled wing) is characteristic of a spin rather than a spiral dive. Vital lessons arise from this incident. When low, airspeed must be monitored assiduously to maintain a safe margin above stall speed. Stall speed is higher in a turn. If a wing drops unexpectedly and does not come up with aileron control, it is stalled and spin prevention action is required immediately. Very few people survive from a spin starting below 300 feet.", actions: "Referred to the CFI who debriefed the pilot on the day. Entered into the Safety Lessons Log", volume: 2 },
  { id: "2020-10-70", date: "2020-10", displayDate: "October 2020", year: 2020, title: "Safety lesson", report: ". Twice this month the cable tow out vehicle started its return from the launch point to the winch with one cable still attached. On each occasion the vehicle was fortunately stopped soon after setting off.", lessons: "If nobody had been watching there was a real likelihood of serious injury or damage. On at least one occasion in the past when this mistake was made the result was that a glider on the field was seriously damaged by the cable. Cable retrieve drivers must make a positive check that both cables are detached before departing from the launch point. Where the vehicle has wing mirrors they may be additionally used to confirm disconnections.", actions: "Entered into the Safety Lessons Log", volume: 2 },
  { id: "2020-10-71", date: "2020-10", displayDate: "October 2020", year: 2020, title: "Safety lesson", report: ". As the cable hooker-on stood up the wing tip holder set the wings to level, and without waiting, the LM started calling the launch sequence including “Take up slack” before the hooker-on had reached the wing tip to run with it. The launch was stopped by a call from the instructor who then de-briefed. It was understood that the LM had not actually checked that all was clear in front of the glider.", lessons: "In order to ensure the safety of the launching crew (as well as avoiding potential conflict with landing gliders, or obstacles on the airfield), the launching control sequence requires the LM to adhere to the detailed protocol as specified in the Launch Marshals Manual. Specifically, the LM will, without being rushed, check and then, if satisfied, confirm by calling that “ ALL IS CLEAR ABOVE, BEHIND AND AHEAD ” before proceeding to “ TAKE UP SLACK ” and then “ ALL OUT ” using those exact words.", actions: "Entered into the Safety Lessons Log", volume: 2 },
  { id: "2020-10-72", date: "2020-10", displayDate: "October 2020", year: 2020, title: "Safety lesson", report: ". Immediately after a 2-seat glider started into the launch the instructor noticed the blue handle moving back. He grasped it and firmly closed the brakes. The launch then proceeded as normal. The instructor reports he believes that the trainee hadn't locked the brakes even though he had just told the hooker-on that he had. The instructor admits he should be less trusting in future and check that the airbrake lever is fully forward immediately prior to launching", lessons: "It was good that the instructor was alert to what happened. It is not unknown for pilots to have taken a what is taken to be a normal launch followed by experiencing, but not understanding, a high sink rate because it was not realised that the airbrakes were open. Advice is that if the sink rate is strangely high, look out along the wing to see if the airbrakes are open and ensure the a/b lever is fully forward.", actions: "Occurrence entered into the Safety Lessons Log", volume: 2 },
  { id: "2020-10-73", date: "2020-10", displayDate: "October 2020", year: 2020, title: "Safety lesson", report: ". Whist a problem with the winch was being investigated 2 cables were pulled in without any indication from the winch to the launch point that this was going to be done. There were no consequences.", lessons: "Fortunately, no one was near the cables so the danger to the launch point crew of being caught up by the cables and dragged along didn’t arise.", actions: "Reported to the Winch trainer Entered into the Safety Lessons Log", volume: 2 },
  { id: "2020-09-74", date: "2020-09", displayDate: "September 2020", year: 2020, title: "After a two seat glider had been flown", report: "After a two seat glider had been flown with ballast weights fitted, it was discovered upon their removal at end of day that only one bolt was fitted into each of the two ballast weights. So two bolts of 4 were missing and the threads on the remaining bolts were found to be in poor condition. The bolt for one weight appeared to the installer to tighten but later on removal was found could not be tightened firmly. With help the bolt could actually be lifted out of its socket without unscrewing. After their installation and before flying that day, the weights were checked as being installed but only visually.", lessons: "The consequences of a heavy weight coming loose on the floor of a cockpit are potentially very serious indeed. The main flying controls of the glider can become jammed. So after installation, ballast weights MUST be checked by a second person to establish that the retaining bolts are fully screwed home and that the weights are firmly in place and resist being lifted.nsure secure retention of weights when in place, the threaded sockets on the floor must be clear of debris. This should be checked at DI. To keep the sockets clear, when the weights are removed, plastic placeholder bolts should be screwed into the floor sockets.", actions: "The weights were put aside for repair. The glider was marked as U/S for front seat pilots below minimum weight until the weights were returned into service. Publicised in the Safety Lessons Log CFI Informed", volume: 2 },
  { id: "2020-09-75", date: "2020-09", displayDate: "September 2020", year: 2020, title: "A pilot of glider A has reported that,", report: "A pilot of glider A has reported that, whilst ridge soaring, he noticed a glider B ahead on an approaching track. There seemed to be minimal vertical separation, and there may have been on a possible collision. The pilot of glider A got a warning from Flarm. He turned away, watching glider B which didn’t appear to change track. When, post flight, the pilot of glider A enquired of the pilot of glider B if he had seen him, the latter stated that his assumption was that the Flarm alert related to another glider, C, and so imminent conflict with glider A was not seen.", lessons: "It seems possible that the pilot of glider B was paying attention to the visual signals from his Flarm rather than looking out and along track for any potential conflict, particularly when the audible signals from his Flarm indicated that a collision threat was increasing rapidly. As for glider C, it can be ignored, because Flarm will always issue warning signals based on the greatest of multiple threat It’s worth repeating here that Flarm presents the direction of any threat as straight in line with the nose when its track over the ground is towards the threat glider. So when crabbing along a ridge or wave bar, if Flarm warns of a threat ahead, look for the threat along the line of travel, which may not necessarily be ahead in line with the nose . Pilots re-aquainting themselves with Flarm should read again the manual called Understanding Flarm on the Members website (Links Library).", actions: "Publicised in the Safety Lesons Log. CFI Informed", volume: 2 },
  { id: "2020-09-76", date: "2020-09", displayDate: "September 2020", year: 2020, title: "Whilst getting installed in the cockpit preparatory to", report: "Whilst getting installed in the cockpit preparatory to launching, the pilot closed the cockpit canopy for protection against the windy conditions but did not lock it. The unlocked status was not realised until, at the earliest, after the launch had started. The pilot proceeded with the launch and the early part of the flight whilst holding the canopy down. Consequently he was distracted and his look out was impaired. Evenentually he managed to engage one of the two catches that lock the canopy closed and continued with the flight without consequence. After the flight the pilot admitted that he had not got into the habit of applying upward pressure on the canopy during pre-flight checks to ensure the canopy was closed and locked.", lessons: "Whilst recovery in flight from an unlocked canopy can be successfully made, as in this case, the consequences of the occurrence can be serious, leading to loss of control. Such occurrences are viewed as serious failings in airmanship. The canopy check is probably the most important item within the standard pre-flight checks. The guidance in the BGA publication “Managing Flying Risk” is to check that the canopy resists upward pressure. Ground crew, before hooking on, must confirm with the pilot that the check for canopy is closed and locked has been completed, and should additionally confirm that by observation.", actions: "Pilot debriefed. Publicised in the Safety Lessons Log CFI Informed", volume: 2 },
  { id: "2020-09-77", date: "2020-09", displayDate: "September 2020", year: 2020, title: "Safety lesson", report: ". Becoming unsure that a wings attachment was entirely safely locked, the pilot, who was preparing to fly, stopped the launch. Not being entirely satisfied with the checking assistance obtained, the pilot got out of the glider to check the attachment himself. He did this in spite of his belief that rigging had been completed correctly.", lessons: "Anyone must stop a launch if something appears to be wrong. In this case, the pilot was right to stop the launch and double check that the rigging was correct. Much better to stop the launch than take any risk.", actions: "Publicised in the Safety Lessons Log CFI Informed", volume: 2 },
  { id: "2020-09-78", date: "2020-09", displayDate: "September 2020", year: 2020, title: "As a Skylaunch winch was being towed into", report: "As a Skylaunch winch was being towed into the vehicles shed, it became unhitched from the towing vehicle. The unhitched winch continued to move forward about 2 metres with the drawbar jack scraping along the ground. The jack fitting was consequently distorted and required repair. It was subsequently established that it has become a habit to assist the unhitching of the winch from the tow vehicle, by holding open the spring loaded lever that releases the drawbar cup from the tow ball on the towing vehicle. This was done by an improvised chock – a pebble. It appears that on this occasion when the tow vehicle was attached to the winch at end of day the release lever was still chocked open and forgotten, leaving the cup part of the hitch on the winch drawbar able to separate from the towball.", lessons: "There is no automatic braking system on the Skylaunch winch that activates if the towing vehicle separates from the winch (as on e.g. glider trailers). Consequently if the winch does separate from the tow vehicle while under tow, it can run away with obviously very serious consequences indeed.", actions: "Referred to Club mechanic for solution and any advice to winch drivers. Reported to Winchmaster Publicised in the Safety Lessons Log. CFI Informed", volume: 2 },
  { id: "2020-07-79", date: "2020-07", displayDate: "July 2020", year: 2020, title: "The wind was 10 to 15 kts westerly", report: "The wind was 10 to 15 kts westerly. After what appeared to be an unremarkable beginning to a right hand cross wind leg in preparation for a landing to the west, the glider was judged to be making a noticeably low, slow. and flat approach. At this time the air brakes were seen to be closed. The nose was then seen to lower, whereupon the glider contacted the ground hard, bounced up 3 or 4 feet and came down heavily. The wings flexed noticeably and the air brakes popped open. No damage to the glider was found during a heavy landing damage inspection before it flew again. On debrief, the pilot admitted that he knew he had “made a mess of the landing” and that he used the air brakes during the cross-wind leg", lessons: "Bleeding off height with air brakes in the circuit prior to the final turn onto the approach must be done with great care if it is to avoid a low final turn. The result can be a need to stretch the glide over the undershoot area and consequently getting slower than is safe particularly if there is a wind gradient present. A stall rather than a round out can occur from that situation. The pilot had recently restarted flying after the several months of Covid-19 lay off. That may have contributed to some loss of skill and/or judgement, so care must be taken to avoid the consequences of that.", actions: "Pilot was debriefed on the day, instructors were informed and this entry made in the Safety Lessons Log", volume: 2 },
  { id: "2019-11-80", date: "2019-11", displayDate: "November 2019", year: 2019, title: "Safety lesson", report: ". At another site a DLGC pilot, new to the glider type, failed to realise that the front hinged canopy was not locked down at the back. He had not applied the resist upward pressure check. The ground crew stopped the launch .", lessons: "Canopies opening during flight has become a more common incident. It is now recommended good practice for the pilot to apply upward pressure to check a canopy is locked and for the person hooking on the cable to ask if the canopy is indeed locked securely.", actions: "Publicised in Safety Lessons log Pilot de-briefed CFI informed", volume: 2 },
  { id: "2019-11-81", date: "2019-11", displayDate: "November 2019", year: 2019, title: "Safety lesson", report: ". At an aerotow site a glider’s wing tip of a DLGC pilot dragged on the ground because of prop-wash. The pilot didn’t notice it, the launch continued with no consequences.", lessons: "Another example of what could have been a classically disastrous accident in which the glider “cartwheels” round the lower wing. The same safety recommendation, i.e. to release the cable, applies to any kind of launch method.", actions: "Publicised in Safety Lessons log CFI informed Pilot de-briefed", volume: 2 },
  { id: "2019-10-82", date: "2019-10", displayDate: "October 2019", year: 2019, title: "Safety lesson", report: ". The pilot of a single seat glider failed to detect a wing tip dragging on the ground at the start of a launch. The glider started to climb whilst banked then made a turn with the lower wing tip only a few feet above the ground. The glider landed cross wind without any further incident. On debriefing the pilot admitted he was not in the correct frame of mind and that he did not act on known advice which is to release from the winch launch immediately, but tried to raise the wing instead.", lessons: "From the accounts by the pilot and from witnesses this could have been a classically disastrous accident in which the glider “cartwheels” round the lower wing with fatal consequences. As is often the case, this “classic” incident happened to an experienced pilot who admitted it came as a complete surprise for which he was un-prepared for. A thorough and careful “eventualities” check must not be neglected. Pilots should make themselves familiar enough with the forward view from the cockpit to see immediately if a wing is on or near the ground this confirmed if possible by a glance towards the wing tip.", actions: "Publicised in Safety Lessons log CFI notified Pilot de-briefed", volume: 2 },
  { id: "2019-10-83", date: "2019-10", displayDate: "October 2019", year: 2019, title: "Safety lesson", report: ". Whilst undertaking a pre-flight ABCD check the intending pilot found a mobile phone wedged between the seat and the fuselage.", lessons: "Well done the pilot finding the phone whilst carrying out ABCD checks. On debriefing, the previous pilot admitted that the mobile phone ended up where it did having slipped out of what was believed to be a secure zipped pocket. The possible consequences of the phone ending up under the seat where it could have jammed the controls are very serious..", actions: "Publicised in Safety Lessons Log Pilot de-briefed CFI informed", volume: 2 },
  { id: "2019-09-84", date: "2019-09", displayDate: "September 2019", year: 2019, title: "Safety lesson", report: ". Two paraglider pilots reported on the same day that they believe that a K18 (identified by colour) flew above them on Bradwell Edge close enough for them to feel threatened.", lessons: "On the assumption that the K18 pilot(s) was unaware that vertical separation from the PGs was insufficient for the PG pilots to not feel danger of collision then it would appear we as sailplane pilots must take care to keep clearly safe vertical separation from PGs. It is significant that glider pilots have an unrestricted view upwards but not downwards but it is the opposite for paraglider pilots.", actions: "Publicised in Safety Lessons log CFI informed Discussions between officials of the two Clubs followed", volume: 2 },
  { id: "2019-09-85", date: "2019-09", displayDate: "September 2019", year: 2019, title: "Safety lesson", report: ". A retractable undercarriage glider was landed with the U/C still retracted. One of the u/c doors was damaged.", lessons: "This is not an unusual incident. In this case the landing being on grass the damage was limited. It is best avoided by the pilot taking time in preparing to land and using a mnemonic to remind of what should be checked.", actions: "Publicised in Safety Lessons log Pilot de-briefed CFI informed", volume: 2 },
  { id: "2019-09-86", date: "2019-09", displayDate: "September 2019", year: 2019, title: "Safety lesson", report: ". On approach to land a pilot found that what he believed to be the air brake lever was ineffective. It was concluded that regrettably the pilot had mistakenly selected the undercarriage lever instead of the air brake lever. The glider was seriously damaged in the subsequent landing .", lessons: "This incident is not the first of its kind. It tends to occur on types where the air brake lever and the under carriage lever are on the same side of the cockpit. Pilots of all, but particularly relevant types are advised to positively look at the lever they are holding when lowering the u/c or operating the air brakes. Other advice includes fitting a lever grip that feels different, or an alarm that sounds when the brakes are opened but the undercarriage is not down and locked . BUT the latter is not recommended by the BGA (in their safety document Managing Flying Risks) because it may lead the pilot to lower the undercarriage during the final stage of landing resulting in an accident. A safer alternative solution is to utilise a facility within navigation programs like See You, XCSoar and LK8000, which sounds an alert having descended to a set height AGL.", actions: "Publicised in Safety Lessons log Pilot de-briefed CFI informed Report to BGA Occurrence drawn to the attention of owners of relevant gliders.", volume: 2 },
  { id: "2019-08-87", date: "2019-08", displayDate: "August 2019", year: 2019, title: "Safety lesson", report: ". Whilst about to accept the cable ready for a launch, the pilot noticed that the wing bag was still on the glider. The launch was postponed until the bag was removed", lessons: "A pilot preparing for a launch should never accept a cable for hooking on if the glider is not ready to fly. As well as any wing bag on a wing, this rule applies to rudder locks and tail dollies. It is good practice to remove such items as part of the ABCD pre-flight checks.", actions: "Publicised in Safety Lesssons Lessons Chief Launch marshal and CFI informed", volume: 2 },
  { id: "2019-06-88", date: "2019-06", displayDate: "June 2019", year: 2019, title: "Safety lesson", report: ". A tractor towing a Puchacz up the slope back to the North launch point stalled. The relatively light weight driver was unable to make the brakes work to prevent the tractor running backwards but managed to steer the tractor towards the adjacent wall so avoiding collision with the glider.", lessons: "It was fortunate that this incident did not end up with an injury or the need for an expensive repair to the glider. Subsequently the brakes of this tractor were serviced and all others were checked. Any member detecting a vehicle fault which has safety implications should report it to the duty instructor and make sure the vehicle is not used for the time being.", actions: "Publicised in Safety Lessons log Ground equipment officer informed", volume: 2 },
  { id: "2019-06-89", date: "2019-06", displayDate: "June 2019", year: 2019, title: "Safety lesson", report: ". Glider A was climbing in a thermal SE of the site, at 3000ft QFE, turning left, To avoid collision with another glider B heading West, glider A tightened his turn and left the thermal. Post flight the pilot of glider B stated he believed there was adequate vertical separation. Glider B had no Flarm fitted.", lessons: "Joining another glider in a thermal or flying through the airspace of a glider soaring in a thermal requires extra care. Both the correct and the incorrect approach of joining a glider already in a thermal are described and illustrated in the BGA Instructors’ Manual. This incident is illustrative of the value of Flarm – which would have sounded an alarm in both gliders in the circumstances. The fitting of Flarm is “strongly encouraged” by DLGC, this being re-affirmed at the last instructors meeting.", actions: "Publicised in Safety Lessons log Pilots de-briefed CFI informed", volume: 2 },
  { id: "2019-06-90", date: "2019-06", displayDate: "June 2019", year: 2019, title: "After a high acceleration launch to an estimated", report: "After a high acceleration launch to an estimated 10 feet, airspeed was lost such that with stick fully forward the nose could not be lowered. The winch then increased power, and the launch resumed without further incident. The winch driver had been briefed that the pilot required a launch speed of 70 kts.", lessons: "Whether requested or otherwise, a pilot should be wary of a high acceleration off the ground followed by a loss of airspeed whilst the winch driver adjusts for any wind gradient. The pilot must be aware that the effectiveness of the elevator may not be sufficient to overcome the rotational forces raising the nose under high acceleration and may also loose effectiveness at low airspeed. Some gliders are particularly susceptible to this effect and the glider’s manual must be consu", actions: "Publicised in Safety Lessons log Pilot de-briefed CFI informed", volume: 2 },
  { id: "2019-05-91", date: "2019-05", displayDate: "May 2019", year: 2019, title: "Safety lesson", report: ". The canopy of a K8 came off its hinges and fell towards the ground. The glider was being moved forward at the launch point with canopy open when the canopy was accidentally knocked backwards against the retaining spring and off its hinges. In a subsequent inspection, canopy screws were found missing and it was noticed that a drilled crack below the DV aperture had extended from the canopy edge to the aperture", lessons: "Canopies are expensive items and are vulnerable to damage. Every care needs to be taken when they are open. In this case the canopy was open whist the glider was being moved. If it’s best practice that canopies are left closed whilst gliders are being moved into and out of the hangar then perhaps the same should be applied at the launch point.. The detection and rectification of any defects at DI even if perceived as of a “minor” nature is important to avoid consequent damage later on.", actions: "Publicised in Safety Lessons Log Aircraft Officer Informed", volume: 2 },
  { id: "2019-05-92", date: "2019-05", displayDate: "May 2019", year: 2019, title: "As a consequence of loose straps the pilot", report: "As a consequence of loose straps the pilot slipped back in the seat at the start of his launch and his feet lost contact with the rudder pedals. After regaining control the pilot abandoned the launch and landed without any other consequence even though he was concerned about potential conflict with another glider in circuit.", lessons: "There are distinct dangers from not being strapped into the cockpit sufficiently firmly to prevent sliding backwards during a winch launch. The stick can be unavoidably pulled back so as to steepen the climb beyond what is safe and/or the cable release might be operated inadvertently . Launching a glider when there is another glider in circuit inevitably risks conflict if the launching glider has to abandon its launch.", actions: "Publicised in Safety Lessons Log CFI informed Chief Launch Marshall informed Pilot de-briefed", volume: 2 },
  { id: "2019-03-93", date: "2019-03", displayDate: "March 2019", year: 2019, title: "On the day there was a light westerly,", report: "On the day there was a light westerly, launching was N to S, with landings to W or SW. As he crossed the South Ridge, a pilot gave a radio call, indicating a LH circuit, landing West. On completing the final turn, the pilot saw a Puchacz launching across his approach. Fortunately he was able to land taking a line behind the launching glider In his report the landing pilot estimated that serious conflict was avoided by only 5 seconds. The Launch Marshal reported that he heard no in circuit radio call from the landing glider, but it has been reported that it was heard by the instructor in the Puchacz.", lessons: "It is a regular and necessary part of flying operations at Camphill, and it is a consequence of the shape of the airfield, that landings will often be across the launch line. This necessitates extra care to avoid conflicts between launches and landings. When a glider is returning to the airfield having been away for sometime and approaches from a different direction to all other approaches that day the pilot must take extra care to ensure a conflict does not occur. Whereas the pilot of a landing glider can help reduce the risk of a conflict by announcing his imminent landing, it cannot be assumed that the message is heard by all. The person managing the launch must watch for approaches from all directions, listen for radio calls and stop the launch if necessary to avoid conflict. The person managing the launch of a glider has responsibility to avoid conflict by watching for approaches from all possible directions. The question also arises – was the Camphill Base radio switched on, and were received messages audible on the launch point loud speakers?", actions: "Reported to the Chief Launch Marshal who -contributed to the Safety Lesson wording. Publicised in Safety Lessons Log", volume: 2 },
  { id: "2019-03-94", date: "2019-03", displayDate: "March 2019", year: 2019, title: "A tractor going to retrieve a landed glider", report: "A tractor going to retrieve a landed glider drove across the intended landing path of a two seater on a check flight. The P2 of the two-seater was distracted to the extent that he left the round out late. The tractor driver responded when asked that he knew the correct procedure, but had not noticed the landing glider until “the last minute”. .", lessons: "The Pilots Manual at 3.10.1.2 advises use of roads to reach the closest upwind point from which you can reach the aircraft in line with the general direction of landing. This is to minimise the obstruction caused by the tractor and makes the approach of gliders more likely to be seen by tractor drivers.", actions: "Reported to Chief Launch Marshal for consideration of further action. Publicised in Safety Lessons Log", volume: 2 },
  { id: "2019-02-95", date: "2019-02", displayDate: "February 2019", year: 2019, title: "A pilot believed, after making the required contact", report: "A pilot believed, after making the required contact with Camphill Base that he was cleared to climb above FL 85 into the Camphill box (usually referred to as the wave box). It was subsequently revealed to the pilot, by ATC, during a call requesting clearance to climb above FL100 that he was in fact not cleared above FL85 at that time. Immediate action was taken to descend the glider to below FL 85.", lessons: "Enquiries after event revealed that it had been understood that the Camphill box had been opened for climbing above FL85 from the time of the message back to the glider that the box was to be opened. Subsequently the protocol for the communications between Camphill Base, ATC (Scottish) and the gliders requesting climbs into the Camphill box were reviewed to ensure for all on Camphill Base radio. There was a need for these to be reprinted and posted in the launch point vehicle for compliance by ALL CLUB MEMBERS.", actions: "Actions taken by CFI to reinforce radio communications protocol. The required steps in the Safety Lessons column were completed. These steps were reported to the BGA and ATC (Scottish). Publicised in Safety Lessons Log", volume: 2 },
  { id: "2019-02-96", date: "2019-02", displayDate: "February 2019", year: 2019, title: "The wind of the day was from the", report: "The wind of the day was from the East. Launching was N > S. Reports received were that there had been significant lack of appropriate lay offs. In one exceptional launch, reverse layoff was applied with the result that the parachute and strop were nearly lost over the West edge. Another layoff to the East was so extreme (described as 45 degrees to the East) that the winch driver was reported to have done well “to pull the parachute in before it hit the aircraft workshop and/or landed all over the caravans”.", lessons: "These reports indicate a significant lack of attention to the execution of lay-off measures during cross wind launches. It appears that it was fortunate that there were no serious consequences. It’s part of the required airmanship of winch launching at Camphill that the need for lay off against cross winds is assessed correctly and undertaken proportionally. There are significant and potentially serious safety issues if the need for lay off is not addressed and applied. It should be part of every pilots consideration during pre-launch checks as much as actions to be taken in the event of a launch failure.", actions: "Reported to Chief Flying Instructor for consideration of further action. Publicised in Safety Lessons Log", volume: 2 },
  { id: "2019-02-97", date: "2019-02", displayDate: "February 2019", year: 2019, title: "A pilot believed, after making the required contact", report: "A pilot believed, after making the required contact with Camphill Base that he was cleared to climb above FL 85 into the Camphill box (usually referred to as the wave box). It was subsequently revealed to the pilot, by ATC, during a call requesting clearance to climb above FL100 that he was in fact not cleared above FL85 at that time. Immediate action was taken to descend the glider to below FL 85", lessons: "Enquiries after event revealed that it had been understood that the Camphill box had been opened for climbing above FL85 from the time of the message back to the glider that the box was to be opened. Subsequently the protocol for the communications between Camphill Base, ATC (Scottish) and the gliders requesting climbs into the Camphill box were reviewed to ensure for all on Camphill Base radio. There was a need for these to be reprinted and posted in the launch point vehicle for compliance by ALL CLUB MEMBERS", actions: "Actions taken by CFI to reinforce radio communications protocol. The required steps in the Safety Lessons column were completed. These steps were reported to the BGA and ATC (Scottish). ublicised in Safety Lessons Log", volume: 2 },
  { id: "2019-01-98", date: "2019-01", displayDate: "January 2019", year: 2019, title: "An instructor whilst strapping into the back of", report: "An instructor whilst strapping into the back of a Puchacz, and adjusting a lap strap, found that he couldn't lift his hand up again. The spring that holds the small gripping slider had come out of position, and the sharp end of it had penetrated about � inch under the skin a finger. Help was required to extract the spring. Upon repositioning the spring, it was observed that these springs are not well held in place.", lessons: "Fortunately the angle of penetration was such that that the injury was not as significant as it might have been. Given that it is an observed feature for these strap adjuster springs to become dislodged, their proper positioning should be checked and corrected if necessary, regularly and especially at DI", actions: "Reported to Aircraft Officer. Those undertaking 50 hour checks on Puchacz are being briefed to look for this known issue. Publicised in Safety Lessons Log. Those undertaking DIs should check that the springs are in safely located.", volume: 2 },
  { id: "2018-09-99", date: "2018-09", displayDate: "September 2018", year: 2018, title: "The P1 on a training flight abandoned the", report: "The P1 on a training flight abandoned the launch at the point of All Out after a faster than normal Take Up Slack (TUS) during which the glider yawed towards the 15kt c.45 degrees X-wind. There were no consequences. There is no report of which wing the wing runner was on but it was reported that the young relatively inexperienced member was doing his best but in doing so enhanced the yaw. The faster than normal TUS was typical of others previously observed. It is believed that a device to keep the winch engine running at fast tick over may be implicated.", lessons: "It appears that the fast TUS accentuated the wing runner’s difficulty of keeping the wings level. If he was on the upwind side that may explain the observation that he enhanced the yaw. Lessons to be learned here appear to be … a. if fast TUS are observed, report them to the winch driver. Ask if the tick over device is disabled. b. Remind the wing runner that he/she should call STOP if struggling to keep wings level and should not in any way steer the glider (e.g. by keeping hold of a wing that is accelerating away from him/her).", actions: "Reported in SLL Highlighted to Winch master and Chief Launch Marshal", volume: 2 },
  { id: "2018-09-100", date: "2018-09", displayDate: "September 2018", year: 2018, title: "A solo pilot at the top of the", report: "A solo pilot at the top of the launch to the S at 900 feet, found a visiting glider about 100 feet below and 100 metres ahead travelling E>W. His perception was that the launch had been terminated early to avoid the cable intercepting the other glider. The same pilot had achieved 1200 feet on an earlier launch.", lessons: "This was an uncomfortably close encounter apparently caused by the visiting glider tracking over the winch area at well below launch height. That was poor, even dangerous flying. No glider should be flown so close and low to the winch as to risk conflict with the launching cable or glider.", actions: "Reported in SLL The pilots were de-briefed", volume: 2 },
  { id: "2018-08-101", date: "2018-08", displayDate: "August 2018", year: 2018, title: "During DI of a club single seat glider,", report: "During DI of a club single seat glider, five coins were found lodged well back in the fuselage.", lessons: "This was excellent observation by the pilot undertaking the DI. The conclusion is that one or more pilots had flown with loose coins in pockets without zips or not zipped up. The potential consequences are serious. Coins can jam control mechanisms. A search under and behind seats is awkward, uncomfortable but essential", actions: "Reported in SLL", volume: 2 },
  { id: "2018-08-102", date: "2018-08", displayDate: "August 2018", year: 2018, title: "After a very low simulated L/F the glider", report: "After a very low simulated L/F the glider nose wheel struck the ground sufficiently firmly to require a hard landing check.", lessons: "To prevent potential damage in the situation described, the response must be to hardly lower the nose at all and allow the glider to land ahead. Do NOT lower the nose firmly as for L/F recovery at a higher level. Whilst this is being learned instructors will guard the controls. During training, this exercise is a “demonstration only”. In this case the experienced P2 was being tested. The testing instructor has learnt not to assume a successful outcome.", actions: "Reported in SLL Highlighted to Instructors.", volume: 2 },
  { id: "2018-07-103", date: "2018-07", displayDate: "July 2018", year: 2018, title: "After a member exited the tow out Discovery", report: "After a member exited the tow out Discovery by the passenger door, the near side rear wheel ran over and trapped his toes preventing him from stepping away. As his foot became free he was struck on the spine by the retracted spreader bar, which knocked him to the ground. The member consulted his GP. He suffered pain and discomfort for 3 weeks but has no lasting effects. The tow out driver stated he was convinced that the member was clear before he moved off.", lessons: "The member was fortunate that the impact from the spreader bar was not more severe. The lesson is that, whilst care is needed when driving or riding in or on any club vehicles, particular care must be taken when driving the tow-out vehicle or being near it when it’s on the move. The protruding spreader bars, even when retracted, are a potentially serious hazard", actions: "Published in the SLL . Consideration will be given to the spreader bar design.", volume: 2 },
  { id: "2018-07-104", date: "2018-07", displayDate: "July 2018", year: 2018, title: "After a sim L/F during a S>N launch", report: "After a sim L/F during a S>N launch the cable landed across the hangar and some caravans. Whilst the cable was being handled for recovery, the winch driver started to wind in the cable, trailing it across the hangar apron lighting and very narrowly missing a parked glider. There was a westerly component in the wind.", lessons: "Because of the difficulty of avoiding the consequences of drift of cables towards the hangar and caravans in a x-wind from the West, practice L/Fs on launches in this launch direction are not practiced. This rule was accidentally overlooked. As well as being fortunate that there were no injuries or serious damage where the cable fell that also applies to the winding in of the cable. When a cable lands off the field it has to be the rule that the winch driver starts winding in only after getting an all clear signal that the cable is clear of all obstacles and people. All those on the airfield have a responsibility to monitor the safety of the flying operation. The instructor who had forgotten or overlooked the Club rule would have benefited from a prompt", actions: "Published in SLL Highlighted to Instructors and Launch Marshals (Instr Mtgs Oct 2017 and Nov 2016)", volume: 2 },
  { id: "2018-07-105", date: "2018-07", displayDate: "July 2018", year: 2018, title: "After a sim L/F on a N>S launch,", report: "After a sim L/F on a N>S launch, the cable end assembly fell onto and penetrated the felt on the hangar roof. There was a westerly component in the wind.", lessons: "Whilst drift of the cable on L/Fs in this launch direction do not normally cause a problem it is concluded that this was a failure to monitor the strength of the cross wind and /or the degree of lay off required to avoid the consequences.", actions: "Reported in SLL Highlighted to Instructors and Launch Marshals (Instr Mtgs Oct 2017 and Nov 2016)", volume: 2 },
  { id: "2018-07-106", date: "2018-07", displayDate: "July 2018", year: 2018, title: "At the end of flying a battery was", report: "At the end of flying a battery was found unsecured on the tray behind the seat of a club glider not in its box. The securing strap was found slack as though it hadn't been tightened.", lessons: "No explanation was found. It should be needless to say that an unsecured battery able to move around within the cockpit presents a significant danger of jamming the controls, with fatal consequences. It is to be hoped that this was not a failure to properly secure the battery at start of day and/or a lack of attention to detail at DI.", actions: "Reported in SLL Equipment was checked for serviceability", volume: 2 },
  { id: "2018-07-107", date: "2018-07", displayDate: "July 2018", year: 2018, title: "A launch was initiated whilst the wing of", report: "A launch was initiated whilst the wing of another glider being brought to the launch stopped over the top of the wing of the glider being launched. The P1 of the launching glider aborted launch. The launch point had been positioned such that the wings of gliders being launched were overlapping the path of glider wings being brought to the launch point on the perimeter track. This arrangement had been adopted to ease grass wear at the usual position of the launch point", lessons: "Until the launch was stopped an unnecessary risk was being taken. Had either the launching glider or the glider on the peri-track rocked wings there would have been a clash with probable damage. Care should be taken … 1. by LMs to ensure that gliders in the launch queue are free to launch safely. 2. to configure and position launch points to keep collision risks to a minimum. 3. towed gliders near launch points are moved without causing risk. 4. Whenever a routine arrangement is changed, all must be alert to possible un-expected consequences.", actions: "Report in SLL Chief Launch Marshal informed.", volume: 2 },
  { id: "2018-07-108", date: "2018-07", displayDate: "July 2018", year: 2018, title: "During a pre-flight walk round, the R clip", report: "During a pre-flight walk round, the R clip that double secures the connection of the elevator to it’s drive mechanism at the top of the fin was seen to be hanging, on its attachment cord, beside the fin, i.e. not in position securing the elevator drive to the elevator. The glider had been DI’d, and flown twice that day and on previous days since rigging. On this type of glider the elevator connection with R-clip is made before the tailplane is fixed in position", lessons: "No reason for the R-clip not being in position was established. The R-clip was not found to be faulty. It was re-inserted and found to be correctly in position on derigging. It’s difficult not to conclude that the R-clip was either not inserted partially or not at all during rigging. Pilots are reminded via this of the usually fatal consequences of a launching with a disconnected elevator. Double checking any control connections during rigging and DI is essential. A familiar routine can lead to complacency", actions: "Published in SLL. The syndicate pilots were de-briefed", volume: 2 },
  { id: "2018-06-109", date: "2018-06", displayDate: "June 2018", year: 2018, title: "Undercarriage un-expectantly banged down during a positive G", report: "Undercarriage un-expectantly banged down during a positive G manoeuvre. Subsequently, u/c would not lock down prior to landing. The glider was landed left hand on stick with u/c control lever held. The pilot who habitually raises the u/c during the winch launch admits to not checking that the u/clever was in the fully locked up position after raising it.", lessons: "It was subsequently found that that the lug which engages with a notch to keep the undercarriage up or down was distorted. It was concluded that this happened when the u/c banged down during the +ve G manoeuvre and that this occurred because the u/c was not firmly locked up. Lesson: Concentrate on essential and sometimes urgent actions required during the winch launch, and methodically double check by looking and testing", actions: "Published in SLL Pilot self briefed.", volume: 2 },
  { id: "2018-06-110", date: "2018-06", displayDate: "June 2018", year: 2018, title: "When the control connections on a privately owned", report: "When the control connections on a privately owned glider were given an independent check, it was found that one control had not been connected at all.", lessons: "The private owner routinely asks another person to help not only with positive control checks but to double check the security of the l’Hotellier linkages inside the fuselage. It is well known that L’Hotellier linkages require special attention and the owner is particular about his checking routine. It is fortunate that the double check by another person revealed the oversight. Lesson: Mistakes are made by the most careful of pilots and that straightforward, simple safety checks can avoid potentially disastrous consequences", actions: "Published in SLL. Pilot debriefed", volume: 2 },
  { id: "2018-05-111", date: "2018-05", displayDate: "May 2018", year: 2018, title: "It was reported orally to the Safety Officer", report: "It was reported orally to the Safety Officer that a member was seen driving a tractor with a child on his knees", lessons: "The Pilots’ Manual states that only flying and associate members of the club, over 14 years of age, may drive or ride on club vehicles. Additionally there is clearly danger in driving with more than one occupant of the driver’s seat.", actions: "Published in Safety Lessons Log", volume: 2 },
  { id: "2018-05-112", date: "2018-05", displayDate: "May 2018", year: 2018, title: "The pilot of a glider with a front", report: "The pilot of a glider with a front hinged canopy found whilst flying that the canopy was not fully closed. It became clear after landing that attempts to rectify that whilst flying nearly jettisoned the canopy but that the canopy was retained by the its locking bolts. . The pilot recollects that during pre-launch checks the canopy resisted upward pressure, so it appeared locked. It transpires that one of the ground crew saw that the canopy ajar but did not call STOP. It was subsequently established that the rear locking bolts can slide fully back but outside their slots keeping the rear of the canopy ajar. In that situation only the front locking bolts are holding the canopy closed and do so sufficiently to make it resist lifting.", lessons: "Plainly the pilot was fortunate not to have imperilled himself and glider by attempting to rectify the situation in the air. That he admits was unwise. There is clearly a lesson for the launch marshal’s crew and indeed anyone at the launch point. If anything is seen that just looks wrong, they should without hesitation shout STOP. It does not matter if the call was mistaken. Nobody will ever be corrected for making an unnecessary STOP call. As well as checking verbally with the pilot that brakes and canopy are locked, (as stated above for January 2018), hookers on can and should check the same visually if possible.", actions: "Incident drawn to the attention of the Chief Launch Marshall Published in Safety Lessons Log", volume: 2 },
  { id: "2018-05-113", date: "2018-05", displayDate: "May 2018", year: 2018, title: "A glider made a final turn to land", report: "A glider made a final turn to land relatively low and close to the downwind side of the launch point at about the same time as another glider had just completed a launch. The landing glider hadn’t been seen approaching. No radio call was heard. The launch point radio was found to be not switched on. The visibility under the inversion on the day was “slightly impaired”.", lessons: "The lesson from the incident points to the need for particularly careful look out for gliders that may be approaching, maybe at low level, from unusual directions when their profile against the background will be at its minimum, The incident also illustrates the importance of glider to launch point radio communications during the circuit prior to landing. Landing pilots should try to land where they are least likely to interfere with a launch in case they have not been spotted.", actions: "Published in Safety Lessons Log", volume: 2 },
  { id: "2018-04-114", date: "2018-04", displayDate: "April 2018", year: 2018, title: "The screen of a radio in a club", report: "The screen of a radio in a club glider was smashed. This wasn't mentioned when it happened and was only discovered later in the day. It is impossible to know for certain but in the past damage of this nature has invariably been caused by swinging buckles on the parachute harness.", lessons: "If straps are unfastened whilst getting in or out of the glider or if the parachute is placed on the seat or removed carelessly the buckles can act like a flail and damage anything they strike. To minimise the probability of such damage the ends of leg straps should be clipped into the dog clips and not left loose. Everyone should take care when handling parachutes near aircraft as instruments and canopies aren’t cheap.", actions: "Published in Safety Lessons Log", volume: 2 },
  { id: "2018-04-115", date: "2018-04", displayDate: "April 2018", year: 2018, title: "A single seat glider was seen to land", report: "A single seat glider was seen to land towards a line of 3 gliders across its path, that had already landed.", lessons: "If the landing had been mis-judged, or the wheel brake had not worked if needed, at least 2, possibly 3 gliders would have been damaged, as there was not sufficient space between those on the ground to safely go between. The pilot’s manual specifies the many different landing options available. It is important to weigh up the safest options in particular circumstances and choose the one which is least demanding of personal flying skills.", actions: "The pilot was de-briefed about the other, safer, landing options available at the time. Published in Safety Lessons Log", volume: 2 },
  { id: "2018-04-116", date: "2018-04", displayDate: "April 2018", year: 2018, title: "A dog ran at high speed from the", report: "A dog ran at high speed from the trailer park straight across the active airfield. It crossed two potentially live cables and went up to near the west edge to a glider that had just landed. The dog then ran back across the airfield to the road to the trailer park where its owner was standing.", lessons: "Loose dogs on the airfield are a danger to gliders during take off and landing. That is why it is a rule that dogs brought onto the airfield are kept on a lead during flying operations.", actions: "Incident drawn to the attention of the Chief Launch Marshall Published in Safety Lessons Log", volume: 2 },
  { id: "2018-03-117", date: "2018-03", displayDate: "March 2018", year: 2018, title: "A plastic protective end plug to part of", report: "A plastic protective end plug to part of the structure of a one person IMI rigging aid was found, during an annual inspection, inside the fuselage of a glider. It was deduced that it had become detached from the rigging aid, and had fallen into the fuselage during rigging or de-rigging.", lessons: "It was fortunate that this object was discovered and reported. Loose foreign objects inside a fuselage can and have on occasions fouled the movement of control mechanisms. The consequences can be very serious..", actions: "Owners of IMI one person rigging aids were alerted and a report was sent to the BGA . Recorded in the SLL", volume: 2 },
  { id: "2018-02-118", date: "2018-02", displayDate: "February 2018", year: 2018, title: "Safety lesson", report: ". At daily inspection a small wooden wedge approximately 3 inch by 1 inch in size was found loose under the rear seat of a K13. The wedge was identified as a left over tool whilst fitting a new canopy. The aircraft had had two daily inspections following the maintenance", lessons: "There was a risk that under acceleration the wedge could have moved fouling the controls. It needs the pilot doing the DI to lean so far forward with feet maybe off the round, to get a good view of under the seat to see what shouldn’t be there. Loose foreign objects inside a fuselage can and have on occasions fouled the movement of control mechanisms. The consequences can be very serious.", actions: "Recorded in the SLL", volume: 2 },
  { id: "2018-02-119", date: "2018-02", displayDate: "February 2018", year: 2018, title: "Safety lesson", report: ". The towing dolly for a K18 came separated from the tail skid whilst the glider was being towed on a down hill slope. This was found to be caused by the vertical towing pin through the tail skid dropping out because its retaining R clip came out. The clip was found to be distorted. As a consequence the rudder was damaged. It required a repair that took the glider out of service for several days", lessons: "Fortunately the damage was limited because the glider was stopped from running into the tractor by the tail skid digging in. It’s evident that the distortion of the R clip allowed it to detach itself from the towing pin. If there’s a lesson here it would be that we should be on the look out for deterioration of items that do not operate correctly or are about to fail. If found do something about it right away!", actions: "Recorded in the SLL", volume: 2 },
  { id: "2018-02-120", date: "2018-02", displayDate: "February 2018", year: 2018, title: "Safety lesson", report: ". A club glider was left in front of the hangar incompletely picketed, whilst DI’s were proceeding on others. The wing tip was staked and weighted but there were no tyres under the nose, nor against the downwind side of the tail.", lessons: "The reasons for correct picketing should be well known. At the least, a glider can rock violently between wing tips. If the tail is not prevented from being blown with the wind the glider can yaw into wind with a wing potentially colliding with any nearby parked gliders. At worst a glider can be lifted by the wind and be overturned causing damage that cannot be economically repaired. Proper picketing is an important discipline even when the wind is light as conditions can change unexpectedly. It is important that anyone who notices a glider incompletely picketed completes the task.", actions: "Report to be drawn to the attention of the instructors’ meeting and Chief Launch Marshall. Recorded in the SLL", volume: 2 },
  { id: "2018-01-121", date: "2018-01", displayDate: "January 2018", year: 2018, title: "The two seater canopy was held open while", report: "The two seater canopy was held open while the cable was hooked on and not closed until the “take up slack” signal was given. The launch continued and there were no consequences.", lessons: "BGA reports reveal a surprising increase in the number of canopies opening unexpectedly in the air. No locking mechanisms faults have been found so it’s concluded that the causes are failure to check that the canopies were securely locked. It is now practice that the person who hooks on the cable is required to confirm with the pilot that both the brakes and canopy have been checked and are locked. Only if these checks have been carried out is the cable attached. There is no safe reason to have the canopy open once the cable is attached. If the cable has been attached and the canopy is seen to be open then the launch process must be stopped.", actions: "Incident drawn to the attention of the Chief Launch Marshall Published in Safety Lessons Log", volume: 2 },
  { id: "2017-11-122", date: "2017-11", displayDate: "November 2017", year: 2017, title: "Whilst someone was still hooking on a glider", report: "Whilst someone was still hooking on a glider preparatory to a launch but hidden from view from the launch marshal, the signal to take up slack was given and the cable started to move. This was stopped as soon as the launch marshal was alerted. There were no consequences", lessons: "Because this had happened more than once before and because of the potential for injury to the hooker on, it was made good practice some years ago that the launch marshal should supervise the launch from a position where the hooker on can be seen. It’s in the Launch Marshals manual. That practice wasn’t, but should have been, adhered to in this case.", actions: "Publicised in Safety Lessons Log Protocol for hooking on to be reviewed.", volume: 2 },
  { id: "2017-11-123", date: "2017-11", displayDate: "November 2017", year: 2017, title: "On an instructional flight a wing tip of", report: "On an instructional flight a wing tip of a glider went down and dragged on the ground for about a metre. The wing came up but the glider was not released from the launch and so it continued uneventfully into a normal launch.", lessons: "See this column for October 2017. The frequency of this type of incident is a concern. In this case neither the P1 or P2 released the cable. It is good practice for Pupil and Instructor to both have hands on the release knobs – ready for an instant response to a wing going down uncontrollably. To repeat – if this happens and the glider is not released, the consequences are potentially fatal. Every pilot should watch the BGA simulated videos on the Safe Winch Launching page of the BGA website. It is at this link.", actions: "Publicised in Safety Lessons Log", volume: 2 },
  { id: "2017-11-124", date: "2017-11", displayDate: "November 2017", year: 2017, title: "An early solo pilot, whilst carrying out pre-launch", report: "An early solo pilot, whilst carrying out pre-launch checks in a single seat glider, was approached by an instructor who, in the words of the pilot, “began to hurry me so that the line [of gliders behind] could be progressed”. The pilot chose to restart his checks and there were no subsequent consequences.", lessons: "There is no excuse for anyone, let alone an instructor, to interrupt a pilot completing his/her pre-flight checks. Failure to complete such checks carefully are the cause of accidents every year – especially failure to lock the canopy securely or failure to lock the airbrakes. If interrupted, unless it is for a valid safety reason, tell the individual firmly to go away, and then do as this pilot did, start over again.", actions: "Publicised in Safety Lessons Log To be brought to attention of instructors", volume: 2 },
  { id: "2017-11-125", date: "2017-11", displayDate: "November 2017", year: 2017, title: "The weak link in the launch cable was", report: "The weak link in the launch cable was broken when the signal for All Out was given to the winch before all the slack had been taken out of the cable. The winch driver has reported that the interval between the glider type radio message and the start of signalling was unusually long. This lead him to being unprepared, then admittedly rushing, so that the symptoms of a still slack cable when All Out was signalled were missed.", lessons: "When the winch accelerates without the cable being first tightened it causes a “snatch” launch. The weak link may break, but in any case it is unsettling to the pilot(s) and may cause the glider to yaw, roll or even pitch up uncontrollably and so is potentially dangerous. Extreme care must be taken by launch marshals and signallers to not cause this. It is considerate to inform the winch driver about unusual delays. And timing the “next launch is …” radio message to give the winch driver about a minute’s warning helps his/her preparation. Arming the signalling system so that the launch point beacon starts a few seconds before signalling Take Up Slack is additionally helpful.", actions: "Publicised in Safety Lessons Log Potential revision to Launch Marshals Manual", volume: 2 },
  { id: "2017-10-126", date: "2017-10", displayDate: "October 2017", year: 2017, title: "A single-seater glass glider was being launched from", report: "A single-seater glass glider was being launched from the East launch point. A wing tip went down onto the grass, and dragged for several yards before the glider lifted off and continued the launch uneventfully.", lessons: "The reason the wing went down is not known. It is possible that the wing tip holder was resisting an up or down force and didn’t call STOP, as he/she should have. It must have been the case that the pilot was not paying enough attention to whether a wing was nearing or was on the ground. Any un-commanded rolling or a quick glance to the side would have confirmed this. Either that happened - or the pilot saw it and was too slow to pull the release. In this case it was fortunate that the wing did come back up, because the consequences of that not happening are serious damage and are often fatal. Every pilot should watch the BGA simulated videos on the Safe Winch Launching page of the BGA website. It is at this link", actions: "Publicised in Safety Lessons Log", volume: 2 },
  { id: "2017-10-127", date: "2017-10", displayDate: "October 2017", year: 2017, title: "The pilot of a glider has reported that", report: "The pilot of a glider has reported that in spite of his experience on type he was surprised by the degree of over rotation that occurred immediately after lifting off and up to an estimated height of 20 to 30 feet in spite of holding the stick fully forward. After recovery of attitude, the launch continued with no consequences.", lessons: "It was concluded that on this occasion the winch driver had opened the throttle more quickly than the pilot was accustomed to. The causes of, dangers of and avoidance of over rotation are discussed in an published articles and can be accessed via the links in the paragraph on Winch Driving on the Safety Page of the Members’ web site. The links are repeated here and here . These should be read by all winch drivers.", actions: "Publicised in Safety Lessons Log", volume: 2 },
  { id: "2017-08-129", date: "2017-08", displayDate: "August 2017", year: 2017, title: "The person who was in a position to", report: "The person who was in a position to release the tow rope from a two-seat glider at the end of its retrieve to the N launch point chose to do so by back releasing using his foot. He reassured the tractor driver, who queried it, that the disconnection was complete. It wasn’t. When the tractor duly set off the glider swung in an uncontrolled turn round the tip holder on the right wing. Shouts alerted the tractor driver who stopped quickly enough to narrowly avoid the glider colliding with the launch point bus and the tail of another glider.", lessons: "It has to be said that this was another incident where injury and/or damage nearly occurred because of lack of care by those undertaking simple tasks. It’s vital that those responsible for such tasks pay due attention. There’s a relevant saying - to ASSUME can make an ASS out of U and ME. That applies to tasks both you and others are undertaking. It’s a good habit if the disconnected tow rope is thrown clear of the glider so that the tractor driver can see it’s OK to drive away.", actions: "Publicised in Safety Lessons Log", volume: 2 },
  { id: "2017-08-130", date: "2017-08", displayDate: "August 2017", year: 2017, title: "Whilst a two seat glider on a check", report: "Whilst a two seat glider on a check flight was on approach in a NW direction, and about to pass the S launch point, another glider was seen to start a launch. The launching glider’s launch was discontinued at low level. The landing glider landed long. It was subsequently learned by the reporter that (a) the winch driver had stopped the launch and (b) the launch controller had not observed the glider on approach.", lessons: "It appears that prompt action by the winch driver who observed the developing situation prevented a potentially serious conflict between a landing and a launching glider. It’s to avoid such situations that launch controllers must be assiduous in visual checks before announcing ”all clear above, behind and in front”.", actions: "Publicised in Safety Lessons Log", volume: 2 },
  { id: "2017-08-131", date: "2017-08", displayDate: "August 2017", year: 2017, title: "Whilst a glider was landing on a R/H", report: "Whilst a glider was landing on a R/H circuit to the W, a glider was launched from the S launch point. The landing glider had made an in-circuit radio call. There was no recollection of that call being heard. Glider battery issues were suspected.", lessons: "A glider was launched without a landing glider having been adequately looked for. The controller of any launch must ensure that there is no glider on approach from any direction. Landings to the W from R/H circuits when launching is from the S are a regular practice which requires launch marshals to take particular care to observe. There must be no sole dependency on hearing a radio call If a pilot has any reason to doubt that a R/H circuit will be seen from the S launch point, he can opt for a L/H circuit to land to the west, during which he will be more readily seen by the launch point crew", actions: "Publicised in Safety Lessons Log", volume: 2 },
  { id: "2017-07-132", date: "2017-07", displayDate: "July 2017", year: 2017, title: "After a launch from S in a wind", report: "After a launch from S in a wind estimated as WNW at “20mph”, the parachute landed just inside the airfield E boundary, S of the hangar. The reporter suspected this was a practice launch failure. On a subsequent launch, the launch rope, parachute and shock rope landed on the vehicles shed, hanger and aircraft workshop. This was known to have resulted from a practice launch failure that had proceeded in spite of a warning, received at the launch point from the winch driver, about the impact of the wind. Visiting public were walking the peri-track to/from the launch point that day", lessons: "Because of the potentially tragic, let alone costly, consequences for people, gliders, vehicles or buildings being hit by falling ironmongery, it became the rule at the instructors meeting in November 2016 that practice launch fails would not be undertaken when there is a risk of the cable/parachute falling off the airfield. So this incident is perplexing. All should be aware of this rule. The winch driver was correct in raising concern. If he was over-ruled that is very regrettable. Nobody should be willing to involve themselves in practice launch failures in this situation.", actions: "Publicised in Safety Lessons Log", volume: 2 },
  { id: "2017-07-133", date: "2017-07", displayDate: "July 2017", year: 2017, title: "The cables tow-out vehicle got more than half", report: "The cables tow-out vehicle got more than half way back to the winch at the N end before it was alerted by radio to stop. It returned to the S launch point whereupon the occupants learned that a cable had not been detached before it had set off back to the winch. There being no gliders, vehicles or persons in the area of the field where the cable had been dragged there were no consequences, other than the need to uncross the cables.", lessons: "It was very fortunate that no there were no serious consequences. The incident serves to warn how important it is to ensure that even the simplest of procedures must get all the attention it should have. Those detaching cables from tow-outs, and the driver of the vehicle, must between them be absolutely sure that all cables are detached and the spreader bars are retracted before the vehicle moves off.", actions: "Publicised in Safety Lessons Log", volume: 2 },
  { id: "2017-07-134", date: "2017-07", displayDate: "July 2017", year: 2017, title: "A pupil failed to respond to the instructor’s", report: "A pupil failed to respond to the instructor’s instruction to relinquish control of the aircraft on the final approach and flew the glider into the ground, by failing to round out, resulting in damage to the underside of the front section of the fuselage. No one was injured in the accident. The pupil has a hearing impairment and on the day of the accident was testing a new type of hearing aid. It appears that the aid picked up airflow noise on approach that made the instructors words inaudible. The instructor was unaware that the hearing aid was on trial.", lessons: "It is obviously vitally important that communication between instructor and pupil is assured, particularly with impaired hearing. Any technical aid to communication method must be demonstrated to be effective before being depended on. Any alternative or fallback method of telling the pupil to hand over control must be understood and practiced before flying.", actions: "Any new electronic aid to a P2’s hearing will be evaluated before being adopted and will be tested as working before every flight. A CFI ’s notice was issued to remind that the protocol re hand over of control must be taught and applied and to advise that will be an established practice that stick shaking by an instructor tells the pupil that “I have control”.", volume: 2 },
  { id: "2017-07-135", date: "2017-07", displayDate: "July 2017", year: 2017, title: "An early solo pilot in a single seater", report: "An early solo pilot in a single seater made a low (estimated by experienced witness as 100 feet) 180 degree r/h final turn at what was later established to be 45kts from a low circuit position to land on the north half of the field The wind was light NE. The same witness suggested that the safer option would have been a reciprocal landing. The pilot reported he got low due to unanticipated sink.", lessons: "Low turns are hazardous. Low and slow final turns are fraught with danger of spinning because the lower wing is less wind due to wind gradient. So these should be avoided by not joining the circuit so low that unexpected sink forces one into that position. If for whatever reason the circuit is low at the high key area, the option of a reciprocal landing can be safer that stretching the circuit to a low position for the final turn.", actions: "Publicised in Safety Lessons Log", volume: 2 },
  { id: "2017-07-136", date: "2017-07", displayDate: "July 2017", year: 2017, title: "Safety lesson", report: ". Having left the west ridge lower than ideal the pilot flew more than ideal downwind, increased speed to ensure reaching the airfield, ballooned his round out, closed the airbrakes, ballooned again, saw that he was approaching the west peri track, fully opened the airbrakes, hit the ground hard, and crossed the peri track. To avoid going over the edge of the airfield the pilot ground looped the glider through 90 degrees and stopped with a wing tip over the steep slope. Others reported seeing no airbrakes deployed before the first round out. The pilot reports that he did not visually confirm deployment as is his habit because of play in the airbrake linkage. The glider was checked for damage and none was found.", lessons: "The conclusion is that the pilot got flustered after finding himself in an unfamiliar and hazardous position so did not maintain sufficient control of his speed to land without nearly overshooting over the W edge of the airfield. The incident highlights why pilots are trained to join the circuit from soaring the west edge at a height which has margins within which an approach to a safe reference point with good speed control can be easily achieved. There is no known report of a defect in the airbrakes control system.", actions: "Publicised in Safety Lessons Log", volume: 2 },
  { id: "2017-06-137", date: "2017-06", displayDate: "June 2017", year: 2017, title: "What has been taken to be a burn", report: "What has been taken to be a burn mark has been reported on the rear panel of a club two seat glider. This is believed to have been caused by solar radiation being focussed by the canopy whilst the glider was parked.", lessons: "This is a well known phenomenon which can and has caused fires in glider cockpits. This is another very good reason why canopy covers should be in place on parked gliders, especially in strong sun.", actions: "Publicised in Safety Lessons Log", volume: 2 },
  { id: "2017-06-138", date: "2017-06", displayDate: "June 2017", year: 2017, title: "Whilst on a launch to the S and", report: "Whilst on a launch to the S and near the top, the pilot of a single seat glider had to release early to avoid conflict with 3 gliders just ahead which were attempting to thermal soar, (one turning the opposite way to the other two). The wind was SE.", lessons: "This is another case within two months of a glider(s) thermal soaring in airspace which must be reserved for launching gliders. This is so dangerous that reports of it happening should be reported to the duty instructor, the CFI and the Safety Officer. See the April 2017 report of a glider attempting to thermal near the launch path and the lessons to be learned from that.", actions: "Publicised in Safety Lessons Log", volume: 2 },
  { id: "2017-05-128", date: "2017-05", displayDate: "May 2017", year: 2017, title: "(delayed inclusion in SLL) A glider landing to", report: "(delayed inclusion in SLL) A glider landing to the SW, already committed to a landing direction between other landed gliders, chose to increase brakes setting from half to full, increase its approach speed, make a “fly on” landing and use of wheel brake to reduce landing run to avoid collision with a retrieve tractor that had driven onto the intended line of landing and had stopped. The landing glider stopped with the stationary tractor about 100 yards ahead.", lessons: "It was fortunate that the pilot of the landing glider was sufficiently experienced to be able to adjust his landing to avoid a collision. It seems clear that the driver of the tractor had not taken due care to look for landing gliders before encroaching onto the airfield. Having seen the landing glider late, rather than move swiftly out of the way the driver chose to stop in the only landing space available at that stage. The lesson is that retrieve tractor drivers must be very observant of landing gliders. Whilst it is a rule that a landing glider has right of way it is not always best to yield to that right by stopping in the way. When the situation demands it move to reduce the degree of obstruction; next to landed gliders for example", actions: "Publicised in Safety Lessons Log", volume: 2 },
  { id: "2017-05-139", date: "2017-05", displayDate: "May 2017", year: 2017, title: "Whilst the Launch Marshal (LM) was still in", report: "Whilst the Launch Marshal (LM) was still in front of the glider after attaching the cable, the lights signaller, having already armed the lights control box, inadvertently initiated (how is not known) the take up slack lights signal, before the LM issued the T.U S. command. Hearing shouts (but not the word STOP), the signaller mistakenly attempted to display the stop signal by disarming the control box. After the control box was re-armed, and the stop light signal was given, the winch stopped the take up slack.", lessons: "Several lessons arise from this: The one word that must be shouted loudly when a launch sequence must be halted is “STOP!” Anyone can and must call that the moment they see – or just think - that anything is amiss. Nobody must ever be told that they should not have called STOP. The only word to shout is STOP. Other words (like “pull off”) will be likely less effective. It is safer to not arm the signal lights control box until the take up slack command is given. Lights signallers must be sure they know how, without hesitation or mistake, to initiate the stop signal when at any time, especially hearing anyone call STOP.", actions: "Consideration to be given to modifying the signal light control boxes so that there is no difference in function between the arming on/off button on control box and the similar emergency stop buttons on rear of the launch point bus. Publicised in Safety Lessons Log", volume: 2 },
  { id: "2017-05-140", date: "2017-05", displayDate: "May 2017", year: 2017, title: "Whilst the P1 of a two-seat glider was", report: "Whilst the P1 of a two-seat glider was undertaking pre-launch checks in a cross-wind, the un-held canopy of the glider was blown completely over from the fully open position and as a consequence suffered some significant cracks and was eventually declared u/s until repaired. The P1 states his attempt at preventing the upwind wing tip lifting by use of ailerons diverted his attention", lessons: "It is to be hoped that nobody is unaware that glider canopies are so fragile, so expensive and so difficult to repair, that any inattention to their safety is inexcusable. If there is any cross wind from the right hand side or the wind is at all gusty, then the prime attention must be to have the canopy held whilst it is open. Anybody can be called on and should be willing to assist in this respect", actions: "Publicised in Safety Lessons Log", volume: 2 },
  { id: "2017-04-141", date: "2017-04", displayDate: "April 2017", year: 2017, title: "Safety lesson", report: ". A K8 was left with nobody in attendance improperly picketed in the area in front of the hangar in a gusty wind. Whilst a wing tip was secured, there was nothing under the front skid to stop the tail from lifting nor was there anything at the tail to prevent the glider weather cocking.", lessons: "Every flying member, other than the very newest to gliding, knows (or if they don’t, should know) the correct way to picket a glider when it is not being closely attended. It is the responsibility of every and any member to take steps to prevent a glider on the ground being damaged or written off by being tipped over by wind.", actions: "Publicised in Safety Lessons Log", volume: 2 },
  { id: "2017-04-142", date: "2017-04", displayDate: "April 2017", year: 2017, title: "When replacing the canopy onto a K13 fuselage", report: "When replacing the canopy onto a K13 fuselage which itself was loaded onto a trailer, the weight of people standing on the trailer to fit the canopy was enough to make the trailer jockey wheel assembly slip through its clamp thus allowing the nose of the trailer to drop to the ground. It is not known how, but this caused a fresh crack to appear amongst the several around the rear DV panel and a small triangle of perspex to fall out.", lessons: "This was an unfortunate incident in that canopies are time consuming and difficult to repair satisfactorily or very costly to replace.The moral of the story is - always make sure the trailer supports are properly tightened. \"That'll do\" may not do .", actions: "Publicised in Safety Lessons Log", volume: 2 },
  { id: "2017-04-143", date: "2017-04", displayDate: "April 2017", year: 2017, title: "Whilst making turns in an attempt to thermal", report: "Whilst making turns in an attempt to thermal soar near the airfield at a little below 1300 feet, a single seat glider (G1) drifted in the cross wind across the launch line. The P1 of a two-seater (G2) launching to the N saw the situation and having assessed the separation continued the launch. Logger traces showed that G2 whilst still launching reached the location where G1 had been only 3 seconds earlier but about 280 feet lower. G2 came off the launch at about 1300 feet. The logger trace of G1 showed that it was much further across the launch line and towards the launch point than the pilot believed based on his report.", lessons: "Venturing into airspace above the airfield or into an area above the winches at a height less than the maximum launch height for the day is plainly a serious risk. Not many years ago the front pilot of a 2-seat glider died on the airfield because of a collision between glider and the winch wire. So glider G1 flew into a potentially dangerous place when searching for lift. As a rule of thumb, no pilot should fly over or near the winch launch path less than 500 feet above it. And great care must be taken in determining the glider’s position when over the airfield and near or lower than launch height. Prevention of this sort of conflict is primarily the responsibility of the soaring pilot. However the launch marshal can help by not initiating a launch when any glider is seen above the winches or is about to fly below that and near the launch line. There is one exception. A pilot may with care attempt to soar away at launch height above the winch for only about a minute and only immediately after launching", actions: "Pilot of G1 debriefed by email and shown logger traces which emphasised proximity. Publicised in Safety Lessons Log", volume: 2 },
  { id: "2017-04-144", date: "2017-04", displayDate: "April 2017", year: 2017, title: "Whilst boarding a two-seat glider, the second pilot", report: "Whilst boarding a two-seat glider, the second pilot to get in lost his grip on the canopy whilst leaning into the cockpit to read placards. It blew over in a gust and struck him on the head, creating a 3.5cm long cut which subsequently required medical attention. The canopy was undamaged.", lessons: "It is advisable to get another person to hold the canopy when boarding a glider. It is essential that this is done if it is at all gusty.", actions: "Publicised in Safety Lessons Log", volume: 2 },
  { id: "2017-04-145", date: "2017-04", displayDate: "April 2017", year: 2017, title: "Occupants of 2 two-seat gliders (G2A, G2B) had", report: "Occupants of 2 two-seat gliders (G2A, G2B) had uncomfortably close encounters whilst ridge soaring, with the same single seat glider (G1). In the first incident, G1 overtook G2A abnormally close then turned across its path. In the opinion of the handling pilot in G2A had he not already started a turn away from G1 before G1 turned, there would have been a collision. In the second incident G2B had to make a hard right turn to avoid a head on conflict with G1. The Flarm in G1was not operational because its software had not been updated in the previous 12 months.", lessons: "Mid air collisions at low levels are almost always fatal. These two incidents involving the same pilot were very alarming for the crews of the two seat gliders. There are two safety lessons. First, is the need to unfailingly take care to look out and to keep a safe separation from other gliders, particularly when ridge soaring. Awareness and consideration of the consequences of changed relative paths when turning near other gliders is vital. The second is that it is essential that Flarm devices have annual software updates before the due date, otherwise potential conflicts with other gliders will not trigger Flarm alerts in either glider.", actions: "In a debrief of the pilot of G1 he was advised to maintain more separation from nearby gliders. The out of date Flarm unit was updated. Publicised in Safety Lessons Log", volume: 2 },
  { id: "2017-04-146", date: "2017-04", displayDate: "April 2017", year: 2017, title: "Whilst pre-launch checks were being undertaken it was", report: "Whilst pre-launch checks were being undertaken it was seen that one airbrake paddle was not operating as it should. It was found that the hotelier connection for the airbrake was not connected. The pilot believed he had confirmed connection integrity by rigging check and positive control checks. His subsequently analysis was that the small projection on the ball part of the connection can catch the cup part sufficiently to make it wrongly appear that the connection is secure.", lessons: "It was fortunate this disconnected control was seen before launching. The value of this aspect of pre-launch checks was demonstrated. Having only one airbrake working correctly will clearly risk an accident. Subsequent review of the rigging check procedure showed that the direction of pull which demonstrates that the connection is good, must be in the direction the connection is separated. That direction can vary with and within the glider type", actions: "Publicised in Safety Lessons Log. Pilot briefed (whilst undertaking connection) about assured way to test security of Hotelier connector", volume: 2 },
  { id: "2017-04-147", date: "2017-04", displayDate: "April 2017", year: 2017, title: "No weak link of the correct rating was", report: "No weak link of the correct rating was immediately available to launch a glider. The pilot was offered a choice of either weaker link or a stronger link. The pilot opted for the stronger. A full launch followed without incident.", lessons: "Although no consequences resulted, the incident was not without risk. The breaking load of the weak links used for winch launches are accurately calibrated to protect the glider from excessive loads when launching. The weak link used for this launch had more than the specified breaking load for the glider type. Launching on a weaker link also has risk and so is not good airmanship. The probability of a weak link breaking is increased and the consequent recovery from the launch failure has a higher risk than a normal launch. The pilot is responsible for making sure the correct weak link is used. The “hooker on” can assist with this by observing the colour of any circular sticker on the fuselage near the hook.", actions: "Publicised in Safety Lessons Log", volume: 2 },
  { id: "2017-04-148", date: "2017-04", displayDate: "April 2017", year: 2017, title: "Whilst a glider was being towed on the", report: "Whilst a glider was being towed on the perimeter track behind the launch point, a wing tip struck a tractor. The tractor had been “double parked” so was nearer the track than the minimum 10 metres. The glider wing tip suffered some damage.", lessons: "It was fortunate that the damage was slight but nevertheless the glider was out of service for several days. Whilst gliders are being towed constant vigilance, particularly by the driver, is required to ensure that wing tips are not in danger of striking objects or persons. All at the launch point should ensure that vehicles and gliders are stationed at least 10 metres from the perimeter track (i.e. more than half the widest wing span operating on site).", actions: "Publicised in Safety Lessons Log", volume: 2 },
  { id: "2017-03-149", date: "2017-03", displayDate: "March 2017", year: 2017, title: "A club single seat glider was seen on", report: "A club single seat glider was seen on a r/h downwind leg (for a landing to the S) reportedly lower (except by the pilot who has said he was higher) than a two seat glider not far ahead of it. The single seat glider was then seen on a low approach from the N, and landed seconds after the two seat glider. On reaching the glider the retrieve crew were shown the altimeter set at +1000 feet. The pilot believed the altimeter was faulty but that was subsequently established as not true. Two other pilots who had flown the glider earlier in the day had successfully set the altimeter to zero in spite of the low atmospheric pressure on the day", lessons: "It appears that the pilot was fortunate to have a landed without an accident. Before launching pilots must as part of their pre-launch checks ensure that the altimeter is zeroed, unless opting to set it (or leave it set) at say +1000 feet (because low atmospheric pressure prevents a zero setting). Allowances for any non-zero settings must of course be continually applied when flying. If a pilot finds him/herself low prior to having to land then as the circuit progresses, the alternative landing options become fewer. Alternative options for every circuit and approach must to be learned and kept in mind for as long as possible until the final option has to be chosen but without delaying until the only choice becomes a poor one. The options available if not left too late include abbreviating the circuit and landing further up wind on the airfield. If this is judged impossible a decision must be made early enough to make a circuit into a field off site.", actions: "Publicised in Safety Lessons Log. Pilot debriefed and re-briefed about the need for due care and attention when undertaking pre-launch checks and for options when low in circuit as outlined in column 2.", volume: 2 },
  { id: "2017-03-150", date: "2017-03", displayDate: "March 2017", year: 2017, title: "During a launch ground run of a club", report: "During a launch ground run of a club single seat glider it was reported that the wing tip went down and struck the ground “hard” and “bounced” back up. The launch continued without further incident. The pilot is reported to have admitted on return to the launch point that he felt the wing tip hit the ground hard", lessons: "This was a potentially disastrous incident because the pilot (even having been aware the wing strike the ground) did not release the cable. It is hoped that by now all pilots have it fixed in their minds that if a wing drops uncontrollably, they must, with hand on yellow release handle, pull it immediately. Failure to do that has killed several pilots when the glider “cart wheeled”! If you want to see what it looks like and how quickly it happens watch the BGA winch launching videos available on the instructors’ clubroom computer.", actions: "Publicised in Safety Lessons Log. LMs to be requested to .. a. report all incidents, especially this type. b. debrief any wing runner who apparently holds wing level against up/down force and/or does not call STOP..", volume: 2 },
  { id: "2017-02-151", date: "2017-02", displayDate: "February 2017", year: 2017, title: "After the cable had been accepted by the", report: "After the cable had been accepted by the pilot (and so the pilot had thereby permitted the launch sequence to start), the pilot opened the canopy to clear misting. On seeing the canopy open the Launch Marshal stopped the launch. It is reported that the cable was not released from the hook before the canopy was closed again and the launch sequence restarted.", lessons: "If the canopy is open the glider is not ready to launch. So the glider should not be, nor remain, attached to a cable when the canopy is open. If there is a need to open the canopy after the cable has been accepted the cable must be released from the hook first. Adherence to this rule will prevent the potentially serious consequences of a launch starting with the canopy open or unlocked.", actions: "Publicised in Safety Lessons Log", volume: 2 },
  { id: "2017-02-152", date: "2017-02", displayDate: "February 2017", year: 2017, title: "Several launches failed when the cable pulled out", report: "Several launches failed when the cable pulled out of the hooks of gliders with CofG hooks, just in front of the wheel. It was suspected that super cooled water, ice, dirt or frozen grass had been thrown up from the wheel as the gliders were being towed backwards. After cleaning of hooks the problem was resolved", lessons: "Owners of gliders with CofG hooks must be aware that in snowy or icy conditions, hooks need attention to ensure they are clean and freely working before cables are attached to them.", actions: "Publicised in Safety Lessons Log", volume: 2 },
  { id: "2016-09-153", date: "2016-09", displayDate: "September 2016", year: 2016, title: "Safety lesson", report: ". A member removing the ballast weights from a two seat glider, found that one was not screwed down at all. It is not clear whether the weight was left like that by someone not completing its removal or whether the glider had been flown with a totally unsecured weight.", lessons: "The consequence of a loose ballast weight jamming controls are obviously very serious. If the glider was flown with an unsecured ballast weight it was very fortunate that it did not move. Ballast weights must never be placed or left in a glider without being secured. Where there is more than one weight they must be loaded or removed separately. ABCD checks prior to boarding must include a check that any ballast weights are tightly anchored.", actions: "Publicised in Safety Lessons Log", volume: 2 },
  { id: "2016-09-154", date: "2016-09", displayDate: "September 2016", year: 2016, title: "When operating the lights signalling for a launch", report: "When operating the lights signalling for a launch the trained operator pressed the “All Out” button before being given the command to do so by the launch marshal. This resulted in a “snatch” which caused the pilot to abandon the launch immediately.", lessons: "Launching is potentially hazardous. Control of launching is therefore a responsible task. This includes signalling. Wrong signals can lead to an accident. That is why only trained members are permitted to operate signals. Those engaged in signalling must take great care.", actions: "Publicised in Safety lessons Log. Member involved debriefed and requested to not to operate lights for the time being.", volume: 2 },
  { id: "2016-08-155", date: "2016-08", displayDate: "August 2016", year: 2016, title: "Upon hearing the command STOP the trained light", report: "Upon hearing the command STOP the trained light signaller turned off the lights control unit by pressing the on/off knob when the STOP button should have been pressed. Consequently the lights signalling ceased rather than a continuous stop light signal being displayed", lessons: "Launching is potentially hazardous. Control of launching is therefore a responsible task. This includes signalling. Late or missing STOP signals can lead to an accident. That is why only trained members are permitted to operate signals. Those engaged in signalling must take great care.", actions: "Publicised in Safety lessons Log Member involve debriefed and requested to not to operate lights for the time being. Consideration being given to change of colour (from red) of the on/off knob on the control box", volume: 2 },
  { id: "2016-08-156", date: "2016-08", displayDate: "August 2016", year: 2016, title: "Safety lesson", report: ". During “push over” from a simulated launch failure the contents of a pocket in a two seat glider came out and fell into the foot wells. The condition of the elastic closure on the pockets was noted as poor.", lessons: "Loose items in a glider are a serious potential threat to safety. In launch failures or turbulence heavier items can cause canopy damage or jam the controls. Whilst light items can be stored in pockets these must be airworthy – i.e. able to retain contents in negative G situations.", actions: "Aircraft officer notified. Pocket edges elastic renewed. . Publicised in Safety lessons Log", volume: 2 },
  { id: "2016-08-157", date: "2016-08", displayDate: "August 2016", year: 2016, title: "Safety lesson", report: ". The pilot of a glider on a launch from N to S, when at c.700 feet, saw he was climbing towards another glider, close to his climb path, flying in the same direction. Fearing collision the pilot abandoned the launch. The pilot of the other glider has reported he was unaware of the launching glider. The proximity was also reported by other witnesses. The launch was in a cross wind blowing from the W – i.e. from the ridge side of the airfield. From reports it appears that the pilot on the launch was laying off to the W to counteract drift in the cross wind whilst the pilot of other glider had either allowed his glider to drift E from the ridge onto a track that took it over the airfield, or had chosen to cross the airfield in search of lift.", lessons: "This was a potentially serious event. There was a fatal accident at Camphill not many years ago from a collision between launching cable and another glider over the airfield. It is plainly very hazardous to fly over the airfield with winch launching in progress. A safe minimum is launch height plus 500 feet, except where and when there is unquestionably going to be no conflict with a launch. It is especially the case that if the launching is to the SW with the winch positioned on the West edge of the field that ridge soaring gliders must ensure they are flying well to the west clear of the winches. There is no evidence that it was a factor in this event, but launch marshals must ensure that they are looking up as well elsewhere before initiating a launch. The BGA has issued a recent safety warning re this.", actions: "Publicised in Safety lessons Log", volume: 2 },
  { id: "2016-08-158", date: "2016-08", displayDate: "August 2016", year: 2016, title: "Whilst on a launch, the pilot of a", report: "Whilst on a launch, the pilot of a glider found he could not release at the top of the launch however much he attempted operate the release mechanism. The cable eventually detached itself and there were no subsequent consequences. The hook was later replaced.", lessons: "This appears to have been a technical incident due to some wear in the hook mechanism which exacerbated the difficulty to release under tension. It is good practice to not release under tension by definitely lowering the nose prior to release when that can be done safely.", actions: "Publicised in Safety lessons Log. Referred to Instructor forum re any training issue.", volume: 2 },
  { id: "2016-08-159", date: "2016-08", displayDate: "August 2016", year: 2016, title: "A glider landed wheels up whilst landing reciprocal", report: "A glider landed wheels up whilst landing reciprocal from a reportedly low position on the ridge", lessons: "Whilst it is unlikely that the glider was damaged because the landing was on grass, this was an example of poor airmanship. Pilots should be thinking sufficiently about preparing the glider to land – even if they are under pressure by being low,", actions: "Publicised in Safety lessons Log", volume: 2 },
  { id: "2016-08-160", date: "2016-08", displayDate: "August 2016", year: 2016, title: "A member drove his car across the airfield", report: "A member drove his car across the airfield and in doing so drove over cables whilst they were on the move being retrieved to the launch point.", lessons: "This is an airmanship issue. Crossing the airfield on foot or in a vehicle whilst it is operational should only be undertaken if there is a good reason to do so (e.g. for safety). It requires extreme care to avoid conflicting with launching or landing gliders. Driving over a moving cable can cause tow-out weak links to break, hence is disruptive. Dyneema cable will be expensively damaged.", actions: "Member debriefed Publicised in Safety lessons Log", volume: 2 },
  { id: "2016-07-161", date: "2016-07", displayDate: "July 2016", year: 2016, title: "A glider G1 tracking South on the ridge", report: "A glider G1 tracking South on the ridge at nearly the same height as glider G2 tracking North, came very close to collision. Just prior to this G1pilot had taken a Flarm alert as relating to another glider G3 that he was safely passing right to right. With the Flarm now sounding an extreme alert, he then saw late and close glider G2 approaching directly on a collision course. Because of glider G3 on his right he turned sharp left whilst G2 continued without deviating. The pilot of glider G1 estimated lateral separation as a wingspan. Logger traces confirm the proximity.", lessons: "It appears that a head on collision was avoided by the action of the G1 pilot about 2 seconds before impact. It was fortunate that the G2 glider did not turn right in accordance with the avoidance rule. The pilot of glider G1 believes that he was misled by the Flarm visual display. The display was alerting to a threat on track, He wrongly took that to be an indication relating to glider G3 which he had seen and he decided that was not a threat. These gliders were ridge soaring and so were to some extent crabbing along the ridge. Their heading and track were different. Flarm shows threats on track as “straight ahead” on its display, implying they are to be seen by looking straight ahead over the nose – i.e. in the heading direction. Any glider seen there may mislead the pilot into ignoring a real threat which is on track. It appears that this was the case in this incident. Flarm will always visually and audibly warn of the greatest threat when there is more than one potential conflict. Distinguishing between threats on a busy ridge is a recognised issue with Flarm. The lesson is that when the audible alert sounds keep LOOKING OUT until you have identified the threat. Resist the instinctive reaction to look at the display. If you do, remember that when ridge or wave soaring the threat is almost certainly NOT in the heading direction.", actions: "Publicised in Safety Lessons Log The club document called “Understanding Flarm” will be enhanced to emphasise even more strongly the messages covered in the lessons learned column. Instructors will be consulted on the extent to which BGA Recommended Practice 23 re Ridge Soaring is appropriate to and should be applied at Camphill.", volume: 2 },
  { id: "2016-07-162", date: "2016-07", displayDate: "July 2016", year: 2016, title: "Safety lesson", report: ". The full range of flap settings became impossible to select in flight. It was found that a cable and plug of a wrongly positioned voltage reducer box has migrated down to be near the undercarriage mechanism such that only when the u/c was raised did the plug and/or socket interfere with the flaps control mechanism. The owner acknowledges that he wrongly positioned the voltage reducer box during the ARC renewal work", lessons: "The event exemplifies the importance of ensuring that everything fitted or carried in a glider should be suitably secure to avoid any possibility of interference with the movement of controls. In this case, it was fortunate that the control was not vital, nor the degree of inference very significant.", actions: "Publicised in Safety lessons Log", volume: 2 },
  { id: "2016-06-163", date: "2016-06", displayDate: "June 2016", year: 2016, title: "Whilst a member was preparing to attach a", report: "Whilst a member was preparing to attach a cable to a glider, a K18 landed, catching the cables, resulting in snatching the cable from his hands. There were no other consequences. The member admits to not watching if a glider was landing.", lessons: "Because a landing glider can catch and pull a cable on its landing ground run, it is advisable when a glider is on approach to land, to not hold cables (to avoid possible injury), or not to attach them to gliders, or, if the are already attached, to release them from the glider,", actions: "Publicised in Safety lessons Log", volume: 2 },
  { id: "2016-06-164", date: "2016-06", displayDate: "June 2016", year: 2016, title: "During an evening introductory flights session a member", report: "During an evening introductory flights session a member took a visitor on a tractor to retrieve a glider. Having aligned the tractor in the direction of retrieve, the member proceeded to give the visitor a re-brief on starting whilst he (the member) stood in front of the offside rear wheel. It appears that, with the clutch only partially disengaged, the high/low ratio lever was engaged with the main gear lever also engaged. The tractor leapt forward, knocking over and then running over the member. By great fortune the member was not seriously injured. The member admits to yielding to the pleading of someone assumed mistakenly to be a member, to be allowed to drive, against his better judgement - and also that of an instructor.", lessons: "The strict interpretation of section 3.11 of the Pilots Manual does not permit temporary members other than visiting pilots and their crews to drive club vehicles. That section of the manual gives comprehensive guidance on the training of tractor drivers which, even had driving been permitted in this case, appears not to have been addressed. Plainly the enthusiam of poeple must not be mistaken for competence.", actions: "Publicised in Safety Lessons Log (SLL)", volume: 2 },
  { id: "2016-05-165", date: "2016-05", displayDate: "May 2016", year: 2016, title: "Safety lesson", report: ". The pilot had planned, prepared and been formally briefed for a “goal” task. The pilot reported that after about 1� hrs he neglected navigation in favour of finding lift, in increasingly difficult soaring conditions. He became unsure of his position. Realising he might be close to restricted airspace he decided to and did carry out a cautionary landing in a farmer’s field. The wind was almost straight across the intended task track. The pilot set off slightly downwind of the intended starting point. The best soaring conditions tended to be downwind of track. These 3 factors combined to cause a significant divergence from the planned task track. There were no consequences as a result of the incident", lessons: "The effect of wind drift is subtle but relentless and must constantly be accounted for. Difficult soaring conditions distract attention away from navigation. Cross country qualifications and coaching do not equip a pilot to deal with all the vagaries of flight management. Awareness of difficulties and distractions and how to deal with them comes only with solo practice, preferably on short, local tasks. Practice also improves familiarity with and knowledge of navigation devices.", actions: "Pilot and colleagues participated in a flight de-brief/ discussion. Pilot prepared a flight report including views on lessons learned. Club Newsletter article published based on lessons learned. Club newsletter message from the CFI published, drawing attention to the incident. Flying committee to consider suitable guidance to avoid future incidents. Coaching paper to be added to the Society of Silver Seekers ( SOSS ) web page.", volume: 2 },
  { id: "2016-05-166", date: "2016-05", displayDate: "May 2016", year: 2016, title: "On this date there were reports of two", report: "On this date there were reports of two instances of a parachute opening during a launch, and one of it almost opening. On one occasion the pilot abandoned the ;launch and on the other two, the launch continued. On one where the pilot didn't release the parachute was fully open for 3-4 seconds. He wasn't aware the parachute had opened. All these launches were on the Dyneema cable. There were later other reports of this parachute behaviour on the Dyneema cables, with some pilots abandoning launches. Whilst the inflation caused alarm, there were no reports of contact with gliders or consequences of abandoned launches", lessons: "Because of the potential for gliders to contact inflated and upward flying parachutes, the phenomenon was addressed urgently. Analysis suggested that the cause was any of or a combination of the light weight of Dyneema, its inelastic qualities and the size of the parachutes. All parachutes were effectively reduced in size by being \"reefed\". This problem has apparently been solved. Pilots should be alert to the need to great care if abandoning a launch in these circumstances.", actions: "Issue notified to Winchmaster. Solution implemented by club's winch maintenance staff.", volume: 2 },
  { id: "2016-04-167", date: "2016-04", displayDate: "April 2016", year: 2016, title: "Safety lesson", report: ". The pilot of a single seat glider, during the acceleration phase of the launch, saw a loose strop being picked up by the launching cable not far ahead. It was seen to fall away almost immediately and there being no apparent consequence the pilot continued with the launch. The same events had been seen by the launch marshal who decided not to stop the launch because the strop had fallen clear.", lessons: "Whilst there were no consequences in this case, if something unusual or unexpected occurs during the ground run of a launch, the safest option is to stop the launch or for the pilot to release the cable, so that any problem can be identified. The incident was over quickly but the safest option for the pilot was to release the cable. The loose strop (with weak link) assembly had previously and inadvertently been left in the grass, un-noticed. It is good practice for a pilot to walk a few paces in the direction of the intended launch run to check for any impediments before getting aboard the glider.", actions: "Publicised in Safety Lessons Log (SLL)", volume: 2 },
  { id: "2016-04-168", date: "2016-04", displayDate: "April 2016", year: 2016, title: "Safety lesson", report: ". A glider was being towed back to the launch point. A member was standing on the back of the tractor supervising a new young member who was driving the tractor. After a stop to change the wing being held, the instructor was walking back to the fuselage to be beside the cockpit when, before any signal was given, the tractor trainee moved off suddenly jerking the glider forward. The leading edge of the wing hit the instructor's thigh with considerable force. The supervising member noticed the instructor's distress and had the tractor stopped. A week on, the instructor was in varying degrees of pain, sometimes severe and could only sit or walk with difficulty.", lessons: "The power and controllability of tractors means that there is potential for significant damage to gliders and more seriously, injury to those involved with towing them. Tractors are relatively difficult to control safely. That is why the need and extent of training required by members is fully detailed in the Pilots Manual at section 3.11. Nobody should be driving a towing tractor who has not assuredly demonstrated ability to control it and has demonstrated they watch for and obey signals from the crew walking with the glider.", actions: "Publicised in Safety Lessons Log (SLL)", volume: 2 },
  { id: "2016-03-169", date: "2016-03", displayDate: "March 2016", year: 2016, title: "Whilst climbing at 3.7 knots in a thermal", report: "Whilst climbing at 3.7 knots in a thermal about 2k above and about 1km north of the airfield the pilot of a single seater noticed a two seat glider, now known to be on an instructional flight, approaching apparently to join the thermal above him. After continuing his thermal turn away from the approaching glider he lost sight of it until it appeared flying in the same direction alarmingly close above him - estimated to be 30 to 50 feet. Analysis of logger traces from each glider that showed that when the approaching two seat glider was first seen the vertical separation was 300 feet but this had reduced to 131 feet 4 secs after the two had passed the same horizontal position. When asked about the event, neither of the pilots in the two seat glider was able to say they had been aware of the climbing glider below them. The pilot of the single seater admitted that it would have been safer to leave the thermal when sight of the approaching glider was lost", lessons: "Mid air collisions are some of the most serous accidents. Many have fatal consequences. It appears fortunate that the pilot of the single seater was practicing scan cycle technique and in looking up saw how close the two gliders were and was able to take action to increase separation. If the pilots in the two seat glider knew that they were joining another in a thermal they should have complied with the BGA guidance on thermal joining which states that the entry to the (thermal) turn should be planned to retain continual visual contact with all other aircraft at or near the planned entry height, and to ensure no glider already turning will be required to manoeuvre to avoid the joining glider. If they didn’t know that they were flying through a thermal in which a glider was soaring, then it must be questioned whether they were scanning as they should have been.", actions: "Publicised in Safety Lessons Log (SLL)", volume: 2 },
  { id: "2015-12-170", date: "2015-12", displayDate: "December 2015", year: 2015, title: "On a launch to the bowl from a", report: "On a launch to the bowl from a launch point 200 metres from the NE corner in a SW wind, the two seat glider did not compensate sufficiently for drift so that the parachute and strop assembly almost fell onto the hangar roof. There is evidence in the form of damage to the N. end of the hangar that on another revent occasion the strop assembly struck the hangar whilst being wound in under power.", lessons: "Failure to lay off sufficiently for cross wind drift on a winch launch does imply either or both a lack of consideration of the need for or technique required to avoid the heavy metal components at the glider end of the cable, when falling, causing damage to objects or worse, injuries to people on the ground. Laying off for drift is essential airmanship. If a cable is falling towards people or objects, the winch MUST be stopped.", actions: "Publicised in Safety Lessons Log (SLL)", volume: 2 },
  { id: "2015-10-171", date: "2015-10", displayDate: "October 2015", year: 2015, title: "Safety lesson", report: ". The west ridge was marginally soarable in a 10kt wind. A single seat glider (glider B) joined a right hand circuit from the west behind, below and to the right of the two-seat glider (glider A) ahead of it in the circuit. Glider B's circuit was on the low side and remained inside the circuit of glider A as they both flew the base leg. Glider B passed below glider A as the latter turned onto final, then proceeded further along its base leg and made a low final turn onto final. The instructor in glider A was never aware of the presence of glider B near him whilst in the circuit, seeing it only when it landed. The pilot of glider B stated he had glider A in sight ahead of him during the downwind leg. No radio call from glider B was heard. The proximity caused concern with witnesses. There were no other consequences.", lessons: "Whilst in the opinion of the pilot of glider B, the events were all controlled, he did fly in the blind spot of glider A not knowing if his radio call had been heard. Being lower in the circuit, glider B had priority to land but chose not to do so. It is clear that leaving the ridge below and not far behind the glider A reduced his options for a predictable planned circuit. Lessons that emerge from this …. 1. Leaving landing till low on the ridge reduces options and so can increase potential for conflict with other gliders in the air and on the ground. 2. Flying in the blind spot of another glider which might manoeuvre unpredictably at any time is potentially dangerous. 3. Whilst an in-circuit radio call can be helpful, it can never be depended on to be heard and accurately understood.", actions: "Publicised in safety lessons log (SLL). Circuits topic aired on CPN article. Single seat pilot debriefed and included in Safety Measures", volume: 2 },
  { id: "2015-09-172", date: "2015-09", displayDate: "September 2015", year: 2015, title: "Safety lesson", report: ". On the day, launches and landings were to the North. The wind was light Easterly. The preferred circuit was right hand. Visibility was excellent. Glider A, after tracking south to the west of the field at c.600 feet, then turned left off the South West of the field, tracked east for about 20 seconds, then made a wide 270 degree turn to the right onto approach to the North. About that time, prior to and during the 270 degree turn, glider B turned west to fly a right base leg, then north on final. The two gliders came very close to each other as they flew down the approach. The pilot of the glider A recalled seeing glider B south and ahead of him prior to his turn onto final, The pilot of glider B first saw glider A when it appeared (he estimates) 3m meters ahead and 2m above him. After (a witness estimated) about 10 seconds, the glider tracks diverged and they landed without any significant further incident. The pilot of glider A stated that he flew to the South whilst searching for lift. A video recording of the straight ahead view from the cockpit of glider A shows glider B flying W, then turning right to the N, towards and closing on and slightly below glider A. At this point the pilot of glider A is heard on the video making a radio call announcing as being “...downwind”.", lessons: "This was very nearly a mid air collision and so was a serious incident. Conclusions and lessons from this are as follows. None of the lessons are new. 1. There were plenty of opportunities for each pilot to see the other and take early action to increase separation. This points to a failure to carefully look out and around everywhere when in the circuit. Such scanning is essential. 2. Seeking to soar in the airspace of the circuit or making outward turns inside the circuit, obviously raises the risk of collision. To do so in the base leg and approach area is simply dangerous. It must not be done. 3. The radio call from glider A was misleading about his position. In-circuit radio calls should be as accurate as possible about position in the circuit. 4. Whilst it should not be a position to find oneself in, if flying dangerously close to another aircraft and in it's blind spot, immediate steps should be taken to increase separation. Height and airspeed can be lost by judicious use of airbrakes.", actions: "Publicised in safety lessons log (SLL). Both pilots debriefied. Aspects covered in circuits article in CPN , Dec 2015.", volume: 2 },
  { id: "2015-08-173", date: "2015-08", displayDate: "August 2015", year: 2015, title: "Safety lesson", report: ". After an unusually long wait for the two-seat glider to accelerate on a winch launch after the “All Out” command was given, neither the instructor nor the P2 could release from the cable, so the glider continued to creep forward, The Launch Marshal issued a Stop command. A witness saw that the signal lights did not give the all-out signal, nor a prompt stop signal. The launch was eventually stopped. Afterwards it was found that the strop had entered and jammed in the front wheel box. Reports suggest that the signal lights operator was not trained.", lessons: "From reports received, this was a potentially serious incident. It was fortunate that an all out signal was never transmitted because the glider may well have been launched unable to release from the cable because the strop was trapped in the front wheel housing. This questions whether the glider was being monitored and/or held back if need be during the take up of slack. It has to be concluded that the cable entered the wheel box during the early part of the take up slack phase, because later attempts to release from the cable by normal means failed. Lessons are as follows: 1. The cable and strop should be monitored by the Launch Marshal during take up slack to ensure there is no pull other than on the hook only. 2. Strops should be intact and rigid so that they cannot bend sufficiently to enter the wheel box. 3. Gliders should be held back by a person on each wing tip (with an agreed runner) if being launched on a down slope so that over runs of the cable are prevented. 4. Lights should be operated only by members and they must be competent at that. 5. A launch should be stopped after any abnormally long creep forward (say > 1 metre).", actions: "Publicised in Safety Lessons Log (SLL)", volume: 2 },
  { id: "2015-08-174", date: "2015-08", displayDate: "August 2015", year: 2015, title: "Safety lesson", report: ". The windsock had been removed from its mast. As the large T pin that retains the windsock mast and counterweight vertical was being inserted into position, the mast was caught by a gust which pushed the counterweight against the T pin. The T pin handle deflected towards the windsock support stanchions, crushing the hand of the holder. Treatment in A&E for resulting injuries was required.", lessons: "The weight of the windsock mast and counterbalance is so large that when moving it has significant inertia which could cause injury In more ways than one. Those putting up and taking down the windsock should be aware of this and take care. Means to prevent the T pin from being deflected by the counterweight will be looked at.", actions: "Publicised in Safety Lessons Log (SLL)", volume: 2 },
  { id: "2015-07-175", date: "2015-07", displayDate: "July 2015", year: 2015, title: "The canopy of a two-seat glider was blown", report: "The canopy of a two-seat glider was blown shut by a gust whilst batteries were being removed at end of day. The resultant mechanical shock caused a long crack in the Perspex.", lessons: "This damage requires an expensive (multi-thousand pounds) repair. To avoid this happening never leave a canopy open and not held - even for a second in windy conditions.", actions: "Publicised in safety lessons log (SLL).", volume: 2 },
  { id: "2015-07-176", date: "2015-07", displayDate: "July 2015", year: 2015, title: "Twice on the same day “take up slack”", report: "Twice on the same day “take up slack” was called by the launch marshal whilst the hooker on was attaching the cable, lying on beside the cockpit. The winch was fortunately stopped on both occasions and there were no consequences.", lessons: "The potential for injury to the “hooker on” because of this is potentially serious. Factors contributing to the incident were … LM was not in a position to see the hooker on, Wings had been lifted to level, A long delay whilst the hooker on lay out of sight, and Lack of observance by launch point crew.", actions: "Publicised in safety lessons log (SLL).", volume: 2 },
  { id: "2015-06-177", date: "2015-06", displayDate: "June 2015", year: 2015, title: "At the time of the incident reported above,", report: "At the time of the incident reported above, it was noticed that nothing had been heard on the Camphill Base radio.", lessons: "The Camphill Base radio should be always switched on and adjusted so that it can be heard both inside and outside the launch point vehicle.", actions: "Publicised in safety lessons log (SLL).", volume: 2 },
  { id: "2015-06-178", date: "2015-06", displayDate: "June 2015", year: 2015, title: "Two gliders on r/h circuits came within an", report: "Two gliders on r/h circuits came within an estimated c.100 feet vertically of each other, with no discernable horizontal separation, at the point of the final turn of the higher (two-seater) glider onto approach to land to the west. The pilot of the single seater states his first awareness of the two-seater was whilst both were on base leg when he saw it was ahead of him and higher. The pilot of the two-seater states he left the ridge at c.500 feet (QFE) and was not aware of seeing the single seater until he saw it fly under him in the direction of the base leg whilst he was turning onto approach. The single seater pilot opted to extend his base leg and make his right hand turn onto final further south. Both pilots report they made in-circuit radio calls. Both report not hearing any radio traffic. The two seat glider landed to the north of three other gliders already landed and the single seater to the south of these, both without incident.", lessons: "Evidence indicates that the proximity incident and the consequent concern was avoidable. Although he had priority to land by virtue of being lower in the circuit, on recognising the situation, the decision of the single seat pilot not to use that priority but to extend his base leg was clearly the best in order to reduce potential conflict. However, given that the single seat glider was behind and below the two-seater prior to the point of closest encounter, is it reasonable to expect that the pilot of that aircraft could have seen the glider ahead from the time of entry into the circuit, if not before? Was there then time to increase separation earlier and maybe make a radio call informing the two-seater of his relative position? A number of safety points arise, some of which may have been factors but are not known to have been so. Look out for other gliders joining a circuit from the adjacent ridge from any direction at the same time as you is vitally important. If you are the lowest glider in the circuit you have priority to land and others expect you to use it. If you don’t wish to use that priority you should fly and/or communicate so as to avoid confusion, uncertainty and conflict. Whilst no reliance can be placed on them being made or heard, in circuit radio calls to Camphill Base announcing glider ID, position in the circuit, direction of circuit and landing direction are significantly helpful to others in the circuit so should be made as a matter of routine. Pilots should set glider radios with their speaker volumes adjusted to ensure that in-circuit radio calls received are clearly heard. If the airfield is getting crowded by landed gliders, don't wait till low with little time to plan your circuit.", actions: "Publicised in safety lessons log (SLL). Lower glider pilot debriefed. Safety points aired in CN News article.", volume: 2 },
  { id: "2015-06-179", date: "2015-06", displayDate: "June 2015", year: 2015, title: "The pilot of a single seat glass glider", report: "The pilot of a single seat glass glider launching to the west reported himself that he had a long ground run. After lift off airspeed increased, a climb was started but the speed then fell away. The launch was abandoned at about 100 feet. The landing ahead was completed OK but with minimum airspeed.", lessons: "The pilot ascribed his experience to some temporary local lull in the wind or even a wind reversal. He admits that he should have perhaps abandoned the launch earlier.", actions: "Publicised in safety lessons log (SLL).", volume: 2 },
  { id: "2015-06-180", date: "2015-06", displayDate: "June 2015", year: 2015, title: "A single seat glass glider dragged a wing", report: "A single seat glass glider dragged a wing tip on the ground for at least 10 feet during its take off run. Fortunately there were no consequences.", lessons: "It only takes two seconds for a glider with a wing tip dragging on the ground during a winch launch to enter a cartwheel and crash. Because incidents of this kind cause death and serious injury, the BGA has, for years now, stressed the need to release immediately if wings tips are going down uncontrollably. Pilots must watch out for this, keeping their hand on the release for this reason. Also ensure you have seen the BGA videos on Safer Winch Launching.", actions: "Publicised in safety lessons log (SLL).", volume: 2 },
  { id: "2015-05-181", date: "2015-05", displayDate: "May 2015", year: 2015, title: "During a winch launch to the west the", report: "During a winch launch to the west the wire cable launching a 2-seater lifted the adjacent cable which was also wire The overlapping point of the two cables moved along the launching cable towards the launching glider, whereupon the lifted cable tangled with and shredded the cable parachute. The launch was on the most southerly of a set of 4 cables as presented at the launch point, as was the winch drum driven. None of the winch driver, the retrieve driver or the launch marshal recalled an inadvertent crossing of cables at the start of the cable retrieve or at the launch point.", lessons: "A launch fail is a potentially hazardous event and avoidance of them because of picking up a second cable is as important as any other reason. Apart from the launch failure aspect, there is some danger that the picked up cable or it’s components (parachute, shock rope, strop) can come into contact with the launching glider with potentially serious consequences. The cause of this incident is not established. A launching cable can have another cable crossed over and/or around it as a result of mishandling. Cables can also move towards and wrap around each other during pull out at some point along their length if the path is curved and if the braking tension in cables differs between them. There is no evidence for which of these occurred. However, safety aspects to be re-enforced include the following. Tow outs should be straight to counter any tendency for cables to migrate towards each other and so potentially wrap around each other. Cables laid out on a curved track should be checked for separation before use. Care must be taken to ensure that cables are hooked onto tow out vehicles without crossing and in alignment with the winch drums to which they are attached. Launch marshals must ensure that waiting cables are used strictly in order and never crossed over each other. All at the launch point must be aware of the danger arising from live launching cables catching and towing other cables waiting to be used. Members of the public must be kept well away from cables.", actions: "Publicised in safety lessons log (SLL).", volume: 2 },
  { id: "2015-05-182", date: "2015-05", displayDate: "May 2015", year: 2015, title: "K13 on a introductory flight approached to land", report: "K13 on a introductory flight approached to land passing near to the launch point bus at bus at roof top height.", lessons: "Introductory Flights are meant to be flown with the minimum of risk to the public. As well as not maintaining a safe enough margin of height during the flight, the P1 ran out of options and thus set a poor example to inexperienced pilots.", actions: "Publicised in safety lessons log (SLL).", volume: 2 },
  { id: "2015-03-183", date: "2015-03", displayDate: "March 2015", year: 2015, title: "After changing the winch position from one end", report: "After changing the winch position from one end of the field to the other the tow out weak link snapped on one of the two cables due to lack of length. A length of cable found beside the towed out cables was attached to the drum and the its other end attached to the towed out cable. The lengthened cable was wound in. On the next flying day another length of cable was found on the field. The reasons for that are unknown.", lessons: "It appears that the lengths of cable found were left from breaks on the same or previous days. Whilst it is hard to explain It is not unknown for two breaks to appear to have occurred in the same cable at the same time. Care needs to be taken to ensure that no lengths of cable are left such that they can be drawn into the winch and cause damage or a launch failure.", actions: "Publicised in safety lessons log (SLL).", volume: 2 },
  { id: "2015-03-184", date: "2015-03", displayDate: "March 2015", year: 2015, title: "A pilot was on board a single seat", report: "A pilot was on board a single seat glider preparing for a launch when the previous pilot realised his glasses case was missing. After searching it was discovered that the glasses case was behind the glider seat. The pilot had to get out and the seat fastenings undone to retrieve the case. The pilot whose glasses case was misplaced said that they had fallen from his pocket.", lessons: "This is the second such report in 4 months. Obviously loose objects inside glider fuselages can interfere with the movement of control mechanisms or even jam them. Fatal accidents have occurred from this type of incident. Nothing should be carried in a glider that is not securely inside zipped pockets or attached by straps to the carrier.", actions: "Publicised in safety lessons log (SLL).", volume: 2 },
  { id: "2015-03-185", date: "2015-03", displayDate: "March 2015", year: 2015, title: "Safety lesson", report: ". Repeat. A member when stepping off the rear platform of a tractor prior to it stopping, had his foot caught by a loop of the tow rope that was part of the coil of rope lying on the platform. He was pulled off his feet and dragged some yards, suffering some bruising.", lessons: "See the lesson learned from the earlier incident of this nature date c.10/2/15. The same applies here.", actions: "Publicised in safety lessons log (SLL). Broadcast email issued on this subject.", volume: 2 },
  { id: "2015-03-186", date: "2015-03", displayDate: "March 2015", year: 2015, title: "Safety lesson", report: ". Whilst a glider was on final approach to land to the North at the South end of the field, a vehicle was driven across the airfield and the approach path. On seeing the approaching glider the driver turned away back to the peri-track. The vehicle was not engaged in flying operations. There were no consequences.", lessons: "For what should be obvious reasons, that is to avoid conflict with landing gliders and to avoid causing pilots to have to make late and so potentially dangerous changes to their flight path, vehicles should not be driven onto the airfield during flying operations except in support of those operations and then only with care to ensure that no potential conflict is caused.", actions: "Publicised in safety lessons log (SLL).", volume: 2 },
  { id: "2015-02-187", date: "2015-02", displayDate: "February 2015", year: 2015, title: "Safety lesson", report: ". A single seat glider landed with it’s wheel lowered but not locked down. The pilot stated that he found the undercarriage mechanism stiff to operate, so consequently failed to lock the wheel down or up. The glider had been seen flying low on the west ridge", lessons: "It is suspected that the pilot had less time than he should to overcome any difficulty with completing pre-landing actions properly. Configuring a glider to make a controlled approach and landing involves an increased workload. Sufficient time for that to be completed should be allowed for.", actions: "Publicised in safety lessons log (SLL).", volume: 2 },
  { id: "2015-02-188", date: "2015-02", displayDate: "February 2015", year: 2015, title: "Safety lesson", report: ". A member when stepping off the rear platform of a tractor prior to it stopping, had his foot caught by a loop of the tow rope that was part of the coil of rope lying on the platform. He was pulled off his feet and dragged some yards, suffering injuries which have required medical attention.", lessons: "Whilst it is a habit that many have, stepping off or onto the rear platform of a moving tractor is hazardous to some degree so is advised against. Given that members are willing to accept the risks involved, it will become a safety measure to hang the coil of rope up off the platform to reduce the probability of feet being caught in a loop.", actions: "Publicised in safety lessons log (SLL).", volume: 2 },
  { id: "2015-02-189", date: "2015-02", displayDate: "February 2015", year: 2015, title: "Safety lesson", report: ". Launches were from the North east corner and landings were to the West. The launch point crew waited for a glider to complete an approach and landing which would cross in front of them. The winch cable was close to, but not attached to, the glider and the crew kept clear of it. The landing glider hooked the winch cable on its tail skid during its ground run. The cable end at the launch point was snatched away at high speed", lessons: "This incident is recorded to demonstrate the benefit of considering what might happen, and taking steps to avoid any consequences, in the event that it does. It is good safe practice to not have a cable connected to a glider for launching and standing clear of any cables if a glider is landing such that it may catch and drag a cable during its ground run.", actions: "Publicised in safety lessons log (SLL).", volume: 2 },
  { id: "2015-02-190", date: "2015-02", displayDate: "February 2015", year: 2015, title: "Safety lesson", report: ". In an emergency, to jettison the canopy of the Puchacz, the pins through the hinges of the canopy opening mechanism are withdrawn. On a test of the canopy jettison mechanism the hinge pins failed to pull out. It was found that the tell tale wire used to hold one (of two) hinge pins in place was steel (not copper).", lessons: "Plainly failure to be able to jettison a canopy in an emergency has potentially fatal consequences. To help ensure this use of wrong wire is not repeated, pink enamelled copper wire is now provided and a notice stating that only that must be used is placed beside the hinges.", actions: "The correct wire was made available and notices posted. Also entered into SLL.", volume: 2 },
  { id: "2015-01-191", date: "2015-01", displayDate: "January 2015", year: 2015, title: "Safety lesson", report: ". At the top of a launch, the attention of a pilot flying a K13 solo was drawn by the noise it was making to a partially detached airbrake capping strip. After a carefully flown circuit the glider was landed without any further incident. A defect with the airbrake cap had been previously identified but it was judged airworthy but needing attention.", lessons: "The value of the maxim “If it could be safer, put it right now” is relevant here. However, as well, it is probable that the capping strip was loosened by it being held during DI positive control checks. These strips on K8s, K18s and K13s are only glued on, so pulling up can loosen them. Only the end of the airbrake paddle should be held when testing for positive airbrake closure force.", actions: "Glider taken out of service and immediate repairs effected. Publicised in safety lessons log (SLL). Broadcast email issued on this subject.", volume: 2 },
  { id: "2015-01-192", date: "2015-01", displayDate: "January 2015", year: 2015, title: "Safety lesson", report: ". Whilst the launch point was operational it was found that the outside speaker for Camphill Base was not working. When the radio was turned on and adjusted the volume was low and had interference.", lessons: "The main purpose of the outside speaker on the Camphill Base radio is to alert launch crews of gliders in circuit. It is an important aid to avoiding conflict between launching and landing gliders. All at the launch point especially those managing it and manning the flights logging station should ensure as part of their responsibilities that the radio is on and adjusted so that it an be easily heard and that any faults are reported.", actions: "Fault report prepared.", volume: 2 },
  { id: "2015-01-193", date: "2015-01", displayDate: "January 2015", year: 2015, title: "Safety lesson", report: ". A member whilst walking on the peri-track came close to being struck by a tractor that failed to stop as quickly as expected. It was found that only one of the rear wheels brakes were operating.", lessons: "Tractors have only rear wheel braking. Due allowance needs to be made for this, especially on loose or slippery surfaces, also to the susceptibility to differing braking effectiveness between each wheel.", actions: "Fault report prepared.", volume: 2 },
  { id: "2014-11-194", date: "2014-11", displayDate: "November 2014", year: 2014, title: "Safety lesson", report: ". During the last part of the HASSLL checks, preparatory to an instructional spin and recovery, the instructor heard a clunk and vibration of something falling on to the cockpit floor. It was seen to be a mobile phone. It could not be reached. The flight plan was abandoned. After landing the P2 was debriefed on the need to secure loose objects.", lessons: "Obviously loose objects inside glider fuselages can interfere with the movement of control mechanisms or even jam them. Fatal accidents have occurred from this type of incident. Nothing should be carried in a glider that is not securely inside zipped pockets or attached by straps to the carrier.", actions: "Publicised in safety lessons log (SLL).", volume: 2 },
  { id: "2014-11-195", date: "2014-11", displayDate: "November 2014", year: 2014, title: "Safety lesson", report: ". Whilst launches were to the SSW in a SW wind the winch driver reported that about 1 out of 3 launches had inadequate lay off, (they tracked straight at the winch), one laid off the wrong way and another laid off excessively resulting in a weak link break. Because of the trend the winches were later re-positioned further N. There were no actual launch fails and the winch driver managed to keep all falling cables on the field. The winch driver had asked the launch point to request pilots to lay off more.", lessons: "It was fortunate that there were no consequences. Whilst pilots may get a reminder, good airmanship dictates that pilots apply the necessary lay-off without being asked. As stated in the Pilots and Winching Manuals winches should be positioned to ensure that the falling cable cannot endanger persons or objects on the ground, or fall off site. If winch re-positioning is required to achieve this it should be arranged by the winch driver without delay. However, this measure will not be enough to avoid potentially serious consequences after a launch failure when a pilot has layed off insufficiently or worse (as in this case), the wrong way. Hence the high importance of correct lay-off by pilots.", actions: "Publicised in the SLL", volume: 2 },
  { id: "2014-08-196", date: "2014-08", displayDate: "August 2014", year: 2014, title: "Safety lesson", report: ". A paraglider pilot flying at Bradwell Edge reported that a wooden glider flew over the top of his canopy with a clearance of about 20 feet. No glider pilot flying at the time recalls being that close.", lessons: "The flying characteristics of paragliders can mean that their position horizontally and vertically in relation to a glider is not easy to predict. It is strongly recommended that a safe distance is maintained.", actions: "A CFI 's Notice has been issued", volume: 2 },
  { id: "2014-07-197", date: "2014-07", displayDate: "July 2014", year: 2014, title: "Safety lesson", report: ". The left wing of a club K18 was towed into the trees as it was being towed by the tail on the peri-track towards the hangar. The wing tip holder on the west wing tip shouted warnings which were not responded to by the tractor driver. Damage if any was slight.", lessons: "The lesson is simply the same as that for another incident described above at exactly the same place one month earlier. There is a difference - in this case the wing tip holder was not heard over the sound of the tractor, which reinforces the point that drivers must look back!", actions: "The tractor driver was debriefed.", volume: 2 },
  { id: "2014-07-198", date: "2014-07", displayDate: "July 2014", year: 2014, title: "Safety lesson", report: ". A very similar incident to that of 20 June. A glider landing to the West on a day when launching was to the North, had to land over the moving cables, which were off the ground, behind the tow out vehicle. The result was less room to land and a need to use significant wheel brake to avoid a ground run overshoot.", lessons: "One of the challenges of gliding operations at Camphill is that in some circumstances landing have to be made across the launch line or launch cables. Avoidance of conflict requires careful lookout by ground crew at the launch point and at the winch and in the cable retrieve vehicle. At the launch point in-circuit radio calls should be audible to the launch crew and listened for as well.", actions: "Consideration is being given to equipping the winch and/or retrieve vehicle with air band radios", volume: 2 },
  { id: "2014-06-199", date: "2014-06", displayDate: "June 2014", year: 2014, title: "Safety lesson", report: ". Having been established in a thermal for some 4 minutes the pilot of a DLGC private glider found a visiting vintage glider flying head on at him at his height. The DLGC pilot had no option but to continue in the turn to avoid a head on collision. He estimated the other glider passed by about a wingspan away. No deviation was seen.", lessons: "The incident adds to the history of near misses and even collisions when one pilot or both did not see the other until very late or too late. It goes without saying that this incident reinforces the need to look out, especially at horizon level, nearly all the time. Those in a thermal should expect those flying straight and level to give way to them. Whilst both must be assiduous in looking out, the latter cannot let their attention wander simply because they are cruising. The incident is another that adds to the case for Flarm.", actions: "The visiting pilot was debriefed. The club is to equip its fleet with Flarm", volume: 2 },
  { id: "2014-06-200", date: "2014-06", displayDate: "June 2014", year: 2014, title: "Safety lesson", report: ". The left wing of a visiting vintage glider collided with trees as it was being one person towed by the tail on the peri-track towards the hangar. It is believed that more of the glider than the structure by which the tail skid is attached was damaged.", lessons: "The lesson is simply that when towing , the car or tractor driver MUST pay attention all the time to what is happening behind. A rule of thumb is that tractor drivers should be looking back at what is happening behind as much as they are looking forward. Those towing in cars must have windows down and radio off.", actions: "The visiting owner was debriefed.", volume: 2 },
  { id: "2014-06-201", date: "2014-06", displayDate: "June 2014", year: 2014, title: "Safety lesson", report: ". A single seat glider at the end of what appeared to be a well controlled landing, across a left to right down slope, in light and variable wind, ground looped 180 degrees to the left. There was no damage. The airfield grass was at recommended height.", lessons: "Whilst the reasons for the wing drop and ground loop are not known, it is worth remembering how important it is to avoid potential damage from a ground loop by keeping the wing tips from touching the ground until the glider has come to a stop, especially if grass is longer when a wing on the ground can be dragged backwards.", actions: "Publicised in SLL", volume: 2 },
  { id: "2014-06-202", date: "2014-06", displayDate: "June 2014", year: 2014, title: "Safety lesson", report: ". A glider landing to the West on a day when launching was to the North, had to change approach direction from landing in front of the moving cable retrieve vehicle, to landing over the moving cables behind it. The result was less room to land and a need to use significant wheel brake to avoid a ground run overshoot.", lessons: "One of the challenges of gliding operations at Camphill is that in some circumstances landings have to be made across the launch line or launch cables. Avoidance of conflict requires careful lookout by ground crew at the launch point and at the winch and in the cable retrieve vehicle. At the launch point in-circuit radio calls should be audible to the launch crew and listened for as well.", actions: "Consideration is being given to equipping the winch and/or retrieve vehicle with air band radios", volume: 2 },
  { id: "2014-06-203", date: "2014-06", displayDate: "June 2014", year: 2014, title: "Safety lesson", report: ". During a landing to the North West across the slope in a westerly wind, it was reported that at a few feet, the glider's nose dropped and the uphill side wing tip struck the ground before the glider wheel touched down. During the ensuing ground loop the glider yawed 90 degrees and the fuselage fractured seriously behind the wing. There were no injuries.", lessons: "The pilot appears to have let the uphill wing get too low having not taken adequate account of the slope he was landing across or was flying too slowly to have good aileron control in the turbulence known to be a factor in that location and in those conditions. Pilots of long or low winged gliders should be aware of the danger and land to the west if possible.", actions: "The pilot was debriefed", volume: 2 },
  { id: "2014-06-204", date: "2014-06", displayDate: "June 2014", year: 2014, title: "Safety lesson", report: ". During a launch ground run the downwind wing tip of a single seat wooden glider touched the ground, rose again and the launch continued without further incident. The x-wind was not great, but it was a bit gusty. The upwind wing tip holder reported that the wing was being forced upwards prior to his release. The pilot accepts he may have mishandled the controls.", lessons: "If a glider pilot is alert to the possibility, he will release the cable before the wing tip which is going down uncontrollably has touched the ground. That means glancing sideways to check and obviously the left hand holding the release knob. Pilots must be practiced at prompt and, if needed, dis-coordinated action to keep straight and wings level. Wing tip holders must know that if they feel the wing will lift up or go down on their release they MUST CALL STOP.", actions: "Publicised in the SLL", volume: 2 },
  { id: "2014-06-205", date: "2014-06", displayDate: "June 2014", year: 2014, title: "Safety lesson", report: ". Whilst on a check flight, the instructor initiated a simulated launch failure at a level where it was clearly safe to land ahead but not safe to turn for an abbreviated circuit. The P2 opted to turn. The instructor took over to ensure an incident free landing but nevertheless it involved a very low turn.", lessons: "There's a well known principle that after a launch failure, if it's possible to land ahead then that is the action to take. The reason Is that turning low under high workload has too often lead to fatal spinning accidents or simply crashes from turning without enough height. It's safer to land ahead if there is room.", actions: "Publicised in the SLL", volume: 2 },
  { id: "2014-06-206", date: "2014-06", displayDate: "June 2014", year: 2014, title: "Safety lesson", report: ". Whilst on the launch ground run, the right wing of a T-tail single seat glider touched the ground, the glider yawed to the left, the winch power was cut after the glider had rotated into the climb. Observers said there was a noticeable delay before the nose was lowered, the glider landed \"very heavily\". It is believed the glider was flown again without a full heavy landing check.", lessons: "This incident had more than one potentially serious aspect. It is notoriously the fact that pilots don't notice wing tips going down and releasing as a result. Fatalities from the resulting cartwheels happen. Pilots must look and release with no delay whatsoever. And pilots must be alert to loss of winch power resulting in rapid loss of airspeed and get the glider into a nose down recovery attitude with absolutely no delay. Failure to do this results in at least a mush stall and very heavy landing probably causing damage but often a crash with serious injury.", actions: "Pilot debriefed by an Instructor", volume: 2 },
  { id: "2014-06-207", date: "2014-06", displayDate: "June 2014", year: 2014, title: "Safety lesson", report: ". Whilst being towed using a one man towing kit a glider's wing tip struck and caused damage to the rudder of a parked glider. The driver of the towing vehicle assumed there was clearance.", lessons: "When towing past obstacles it is essential to be sure there is clearance. If there is any doubt get out of the vehicle or have someone else observe the clearance. To be sure of clearance gliders should be parked no closer than 10 metres from the perimeter track.", actions: "Publicised in the SLL", volume: 2 },
  { id: "2014-05-208", date: "2014-05", displayDate: "May 2014", year: 2014, title: "Safety lesson", report: ". A K18 was yawed during its landing ground run (deliberately, claimed the pilot, to avoid running over a winch cables). The result was a significant ground loop during which, in the opinion of an instructor, the wing tip was on the ground. The glider was grounded for inspection. No damage was found.", lessons: "Inducing a ground loop by yawing it with rudder or allowing a wing to drop whilst on the landing ground run is quite likely to cause serious damage to the glider structure. It should only be done in real emergencies. The stick should be fully forward to as far as possible to keep the tail off the ground. In some gliders the wheel is ahead of the centre of gravity. The K18 is one such. This will make a ground loop more likely, more severe, particularly if the wheel brake is also applied.", actions: "Pilot debriefed by an Instructor", volume: 2 },
  { id: "2014-04-209", date: "2014-04", displayDate: "April 2014", year: 2014, title: "Safety lesson", report: ". A plug and socket for engine circuits on a turbo glider were found to be disconnected after its return from annual inspection.", lessons: "This shows the value of a thorough daily inspection, especially after the glider has been dismantled more than for normal derigging.", actions: "Publicised in SLL", volume: 2 },
  { id: "2014-04-210", date: "2014-04", displayDate: "April 2014", year: 2014, title: "Safety lesson", report: ". On experiencing significant difficulty with removing an outer wing section of a 4 piece wing, an unexplained shim was found on one of the locating pins. The glider had recently been away for annual inspection.", lessons: "It would appear wise that a eye is kept open for anything unusual or not normal after annual inspections.", actions: "Publicised in SLL", volume: 2 },
  { id: "2014-04-211", date: "2014-04", displayDate: "April 2014", year: 2014, title: "Safety lesson", report: ". ASI readings falling to zero on the launch were traced to wax obscuring the static ports. Some water cleared from the pipework did not cure the problem. The glider had recently been hard waxed at annual inspection.", lessons: "Clearly static ports should be checked as unobstructed after hard waxing. Water in pipework between pitot or static ports and the ASI can also prevent correct airspeed readings. This may occur from washing or rain. Exposed static ports should be covered if this is a risk.", actions: "Publicised in SLL", volume: 2 },
  { id: "2014-04-212", date: "2014-04", displayDate: "April 2014", year: 2014, title: "Safety lesson", report: ". On reaching for the airbrake lever in a K18, the pilot believes he knocked the canopy catch. It became unhooked. The catch was reset and the glider was landed without further incident. The catch was not reported as unserviceable.", lessons: "The pilot believes he completed pre-launch checks as properly. Extra care needs to be taken with canopy locks on K8s and K18s. The hook mechanism can appear secure but become easily released.", actions: "Publicised in SLL", volume: 2 },
  { id: "2014-04-213", date: "2014-04", displayDate: "April 2014", year: 2014, title: "Safety lesson", report: ". An instructor had to stop a blue link being attached to a glider.", lessons: "The colour codes indicate the breaking force of the safety \"weak link\" in the cable. Too strong and the glider can be over stressed, too weak and a launch failure can be caused. The latter impacts a little on safety, so is to be avoided.", actions: "Publicised in SLL", volume: 2 },
  { id: "2014-04-214", date: "2014-04", displayDate: "April 2014", year: 2014, title: "Safety lesson", report: ". After adjusting the rudder pedals of a K18 and completing pre-launch checks without incident, on applying pressure a rudder pedal became unhooked from it’s adjustment catch and moved right forward into the nose. No defects were found, pre-launch checks were repeated and the flight ensued without further problems", lessons: "This justifiably caused concern because a pilot some years ago at this club parachuted from a K18 when this happened in flight. Pilots should ensure that any adjustments made are completely securely. Feet and footwear should be kept clear of the adjuster mechanism. It's worth knowing that a glider can be flown sufficiently well to land without rudder control.", actions: "Publicised in SLL", volume: 2 },
  { id: "2014-04-215", date: "2014-04", displayDate: "April 2014", year: 2014, title: "Safety lesson", report: ". Whilst being wheeled out of the hangar a glider was turned rapidly so that the un-held wing tip struck the hangar. The glider was slightly marked. The hangar was slightly dented. Nobody admitted to being in charge of the the glider movement.", lessons: "Gliders are very prone to careless damage when being moved into or out of the hangar. Movements should be slow, continually monitored by all involved, with a single person giving instructions until the glider is safely positioned inside or out.", actions: "Publicised in SLL", volume: 2 },
  { id: "2014-04-216", date: "2014-04", displayDate: "April 2014", year: 2014, title: "Safety lesson", report: ". A club single seat glider was found unattended and un-picketed outside the hangar. The glider was monitored until the leaver returned.", lessons: "A glider should never be left un-picketed in the proper way where it cannot be monitored. Damage due from wind gusts is unpredictable. Everyone must consider themselves responsible for correcting and educating re safety breaches of this kind.", actions: "Pilot debriefed on his error on his return to the glider.", volume: 2 },
  { id: "2014-03-217", date: "2014-03", displayDate: "March 2014", year: 2014, title: "A visitor on site for a TL drove", report: "A visitor on site for a TL drove his car across the middle of the operational airfield. There were no consequences. The visitor claimed they had been directed to drive to the launch point. The driver had not obeyed more than one sign advising non-members about where they should not drive.", lessons: "The signage needs reinforcing. Written guidance that advises visitors about probable lack of insurance on the airfield will be replaced by a ban on visitors' cars on the airfield except for the infirm if accompanied by a member.", actions: "Signage to be reinforced. An absolute ban on visitors' cars on the airfield to be invoked (except for the infirm accompanied by a member).", volume: 2 },
  { id: "2014-03-218", date: "2014-03", displayDate: "March 2014", year: 2014, title: "Safety lesson", report: ". Whilst manoeuvring a glider on the back of a car into a parking position a wing tip struck a nearby parked car. No damage.", lessons: "It was fortunate that no expensive damage was done. Manoeuvring gliders on the back of a vehicle in the vicinity of other gliders or vehicles is prone to causing damage. It should be done by hand.", actions: "Pilot debriefed on the day.", volume: 2 },
  { id: "2014-03-219", date: "2014-03", displayDate: "March 2014", year: 2014, title: "Safety lesson", report: ". A K8 parked up at the bungee gates was found to have the canopy unlatched and slightly ajar.", lessons: "Correct picketing includes ensuring that the canopy is closed and locked with the clear vision panel closed. Canopies have been blown open and damaged when this has been forgotten.", actions: "Publicised in SLL", volume: 2 },
  { id: "2014-03-220", date: "2014-03", displayDate: "March 2014", year: 2014, title: "At start of tow to launch point a", report: "At start of tow to launch point a K8 wing tip struck a T hangar. The wing holder was on the other tip. No significant damage.", lessons: "It was luck that there was no damage. Common sense and due care dictates that the wing tip holder be on the side of nearby obstacles. The tractor driver also has some responsibility to avoid such collisions.", actions: "Publicised in SLL", volume: 2 },
  { id: "2014-03-221", date: "2014-03", displayDate: "March 2014", year: 2014, title: "Safety lesson", report: ". Whilst in a check flight a pilot approached to the SW so high that the instructor had to take over and turn S for a safe landing.", lessons: "It appears that the pilot having a check had misjudged his height and/or speed and/or had not selected a safe reference point or if he had, was not using airbrake sufficiently to attain that reference point. Maybe lack of recency was a factor - as it tends to be early in the year. Take more care if out of practice and/or fly with an instructor.", actions: "Pilot debriefed on the day", volume: 2 },
  { id: "2014-03-222", date: "2014-03", displayDate: "March 2014", year: 2014, title: "Safety lesson", report: ". Whilst on a check flight a pilot failed to lock the airbrakes, they opened on the launch, were closed after 5 seconds , and then the pilot released from the launch and landed ahead uneventfully. The P2 had no recollection of releasing.", lessons: "It would appear that the pre-launch cockpit checks were not thoroughly completed and in the haste to close the airbrakes the P2 pulled the cable release as well. Maybe lack of recency was a factor - as it tends to be early in the year.", actions: "Pilot debriefed on the day", volume: 2 },
  { id: "2014-03-223", date: "2014-03", displayDate: "March 2014", year: 2014, title: "Safety lesson", report: ". A single seat glider was observed to make a low final turn prior to an approach to the west.", lessons: "Final turns should be completed by 300 feet agl. This provides a safety margin that minimises any tendency to over rudder the final turn, avoids having the lower wing down in the slower air in the wind gradient, gives more height to accelerate to a safe approach speed, and reduces the risk of undershooting into objects and/or unlandable terrain.", actions: "Pilot debriefed on the day", volume: 2 },
  { id: "2014-03-224", date: "2014-03", displayDate: "March 2014", year: 2014, title: "Safety lesson", report: ". A solo pilot on a check flight, at the S end of the site, east of the winch in a SW wind, admitted he had got too low to complete a normal right hand circuit and that he hadn't considered the option of a shorter left hand circuit. After the instructor's prompt a safe left hand circuit was completed, without any need to shorten the downwind leg and turn in early", lessons: "The circuits available at Camphill are all documented in the Pilots Manual. An approach from the S in a SW wind using a left hand circuit is one of these. It has a shorter track over the ground and requires much less turning. Hence if low, it is considerably safer than the \"normal\" circuit. Solo pilots should be aware of these documented options, consider them and use them when the need arises and the opportunity is there", actions: "Pilot debriefed on the day", volume: 2 },
  { id: "2014-03-225", date: "2014-03", displayDate: "March 2014", year: 2014, title: "In a landing to the west a single", report: "In a landing to the west a single seat glider completed it's landing run on the west side of the perimeter track near the windsock. On debrief the pilot reported his view of instruments was impacted by the sun, he couldn't see the ASI , so he ensured his speed was high to be safe.", lessons: "Running over the edge of the airfield has obvious serious consequences. Landing into low sun has it's hazards: inability to see the instruments and not being able to accurately assess height in the round out. Landings to the west at Camphill are prone to this problem. So the sensible thing is to land in a direction out of sun. To press on when partially blinded by the sun into sun and then add energy as a safety measure is clearly is not safe at all.", actions: "Pilot debriefed on the day", volume: 2 },
  { id: "2014-01-226", date: "2014-01", displayDate: "January 2014", year: 2014, title: "Safety lesson", report: ". Whilst undertaking pre-launch checks for a test flight in a newly rigged K18 it was found that there was interference in the aileron circuit with difficulty moving the stick to the right. It was found that the end of the oxygen bottle was fouling the vertical pushrod. The problem had not been found at DI.", lessons: "Had this not been discovered it could have been very unsettling and potentially dangerous. It should be part of a DI to check that maximum aileron deflections are equal as far as can be seen from the cockpit.", actions: "Attention drawn to this by Safety Lessons Log entry.", volume: 2 },
  { id: "2014-01-227", date: "2014-01", displayDate: "January 2014", year: 2014, title: "Safety lesson", report: ". A K18 landed across the cables to the West and hooked the East cable with its tail skid, pulling it very abruptly from the launch point for maybe 20 metres. No harm was done other than untangling the consequential crossed cables.", lessons: "The incident emphasised the importance of keeping clear of the cables as far as possible, and being particularly careful when handling them when gliders are landing. If it is safe to do so, landing gliders should aim to over fly the cable before touch down.", actions: "Attention of Launch Marshals drawn to this by email sent from Chief Launch Marshal.", volume: 2 },
  { id: "2013-12-228", date: "2013-12", displayDate: "December 2013", year: 2013, title: "Safety lesson", report: ". On a launch to the west the winch driver saw the cable released from the glider and start to fall, straight into the path of a landing glider. The winch driver opted to reel in the cable to avoid any collision with the glider and the cable touched down a short distance ahead of the glider which came to rest without incident. The winch driver admitted to being distracted by swapping hurriedly between winches and so didn't check the circuit prior to launch as is his normal practice.", lessons: "Whilst this incident would have been avoided had the winch driver seen the landing glider earlier, it is primarily the responsibility of the launch point crew to ensure it is safe to launch. It appears that this was the third occurrence on this day of a launch being initiated whilst a glider was in circuit or even on approach. The lesson to be taken on board is clear and stated above.", actions: "Attention of Launch Marshals drawn to this by email sent from Chief Launch Marshal.", volume: 2 },
  { id: "2013-12-229", date: "2013-12", displayDate: "December 2013", year: 2013, title: "Safety lesson", report: ". Whilst at one third of a launch to the W, the reporter saw a 2-seat glider landing to his right at the N end of the field. There were no consequences", lessons: "Same as for similar incident on this day (see next below).", actions: "Attention of Launch Marshals drawn to this by email sent from Chief Launch Marshal.", volume: 2 },
  { id: "2013-12-230", date: "2013-12", displayDate: "December 2013", year: 2013, title: "Safety lesson", report: ". Whilst a launch was being initiated to the W a K8 was seen approaching along the back wall. The reporter called stop. The glider finished right in front of the winches near where the cable would have been dropping.", lessons: "The check that it's \"All clear above and behind…\" prior to initiating a launch must of course include an all round check that no aircraft in circuit might conflict with the launch. The consequences of a conflict are potentially very serious. Whilst there is a particular responsibility on the Launch Marshall, all at the launch point can help with this.", actions: "Attention of Launch Marshals drawn to this by email sent from Chief Launch Marshal.", volume: 2 },
  { id: "2013-12-231", date: "2013-12", displayDate: "December 2013", year: 2013, title: "Safety lesson", report: ". The rectangular hatch for covering the access to the control linkages on an ASW20 was found where it had apparently fallen off the glider.", lessons: "Those with this form of access cover are advised to ensure they are securely fixed by appropriate means. There is a danger that the cover may fall into the controls and jam them.", actions: "Attention drawn to this by Safety Lessons Log entry", volume: 2 },
  { id: "2013-12-232", date: "2013-12", displayDate: "December 2013", year: 2013, title: "Safety lesson", report: ". A launch failed with the glider about 4 feet up. The P2 pushed the stick forward too fast and too quickly for the instructor to avoid the nose wheel striking the ground. After bouncing into the air the glider stopped in about 250m.The instructor was guarding the controls. On inspection, no damage was found.", lessons: "Inexperienced pilots should be aware or made aware that the elevator is quite effective at airspeeds approaching that for launch rotation. After a launch failure at low level, prompt, but less, stick movement is required (than during the climb) to lower the nose to the approach attitude. Instructors need to be alert to the possibility of P2s over controlling in these situations.", actions: "P2 debriefed", volume: 2 },
  { id: "2013-12-233", date: "2013-12", displayDate: "December 2013", year: 2013, title: "Safety lesson", report: ". Pilot brought K18 to the LP, turned it into the quite brisk, soarable westerly wind, and started to walk away, with no one anywhere near it.", lessons: "Gliders (especially wooden gliders that have lighter wing loadings), are susceptible to being blown over and written off as a consequence. Never turn a glider on the ground into a brisk wind without someone in it or holding down the nose.", actions: "Attention of the pilot was drawn to the issue by a senior instructor.", volume: 2 },
  { id: "2013-12-234", date: "2013-12", displayDate: "December 2013", year: 2013, title: "Safety lesson", report: ". On this day there were 3 launch fails from rope breaks on the Skylaunch. After the third use of that winch was suspended. The ropes were known to be in poor condition.", lessons: "A launch failure requires exceptional action and consequently incurs a degree of additional risk. No equipment should be used if known to be faulty and which as a consequence increases risk.", actions: "Referred to the Winch Master", volume: 2 },
  { id: "2013-09-235", date: "2013-09", displayDate: "September 2013", year: 2013, title: "Safety lesson", report: ". At the start of a launch to the North of a K8, after the wing runner on the right wing tip let go of the wing, early in the opinion of some, it dropped to the ground. The glider continued to accelerate, yawed to the right, and lifted off to a small extent, during which sequence the pilot released from the winch cable, the glider came to rest having slid sideways towards the winch and yawed 180 degrees. There was damage to the front skid and there were no injuries.", lessons: "The occurrence had the potential to be a serious accident. Fortunately, the pilot released in time to stop the glider lifting into a cartwheel, from which it could have landed inverted and cause serious, even fatal, injury. The rule to be emphasised here is that if the wing is dropping uncontrollably, release before it hits the ground. Further lessons; ensure the wing runner is capable and is properly briefed and ensure the upwind wing (or the pilot’s chosen one) is being held in a cross wind.", actions: "The CFI issued to all flying members an analysis of issues to be aware of when winch launching.", volume: 2 },
  { id: "2013-09-236", date: "2013-09", displayDate: "September 2013", year: 2013, title: "Safety lesson", report: "", lessons: "In one day the wrong strength weak link was attached to gliders in readiness for a launch on three separate occasions. On two occasions the launch proceeded. In one those two, the link was too weak for the glider, it broke necessitating a failed launch recovery.", actions: "This report shows a lack of care and attention to a simple matter of safety. Weak links are rated and matched to gliders for good technical reasons. Sloppy regard for the correct weak link can mean a launch failure (with its associated increased risks) or an over stressed glider structure.", volume: 1 },
  { id: "2013-09-237", date: "2013-09", displayDate: "September 2013", year: 2013, title: "Safety lesson", report: "", lessons: "During an ABCD walk round of a Puchacz it was noticed that one of the two trim tabs could be moved easily and independently from the other. It was found that the connecting drive wire was fractured. The breakage had the appearance of not being new so there is suspicion that the defect was missed at more than one DI.", actions: "This occurrence demonstrates the value of the ABCD walk round checks. It would also appear to demonstrate the value of checking at DI of a Puchacz that the trim tabs move fully and equally. Because the connecting wire to the trim tab acts by push (as well as pull) it can be kinked and so maybe fracture by being forced. So a positive control check involving force is not advised.", volume: 1 },
  { id: "2013-09-238", date: "2013-09", displayDate: "September 2013", year: 2013, title: "Safety lesson", report: "", lessons: "Just after a glider being launched started to move the wing tip holder noticed that the chock was still in place. He shouted “Stop”. In fact the wheel had by this time gone over it. He let go the wing, and went in front of it while it was moving, apparently to remove the chock. The wing pushed him rather than hit him. The pilots had released from the cable", actions: "It was fortunate the pilots had released. Had that not happened the wing runner would likely have been hit hard, and perhaps been injured. It is important that all concerned do not rush to act without a moment's thought about possible dangers. Whilst, as it turned out, the shout of Stop was not necessary, it was then and always is entirely acceptable for anyone to make that call.", volume: 1 },
  { id: "2013-08-239", date: "2013-08", displayDate: "August 2013", year: 2013, title: "Safety lesson", report: "", lessons: "As a two-seat glider was being towed away from the area in front of the hangar to the launch point, a wing tip struck the private hangar. No damage was reported to the glider or hangar.", actions: "It was fortunate that there was no damage. I does seem that nobody could argue that this occurrence was due to anything other than a straightforward lack of care.", volume: 1 },
  { id: "2013-07-240", date: "2013-07", displayDate: "July 2013", year: 2013, title: "Safety lesson", report: "", lessons: "A wing of a glider being towed along the perimeter track behind a car in the usual tail first configuration with tail dolly and wing dolly, struck a tractor parked outside the perimeter track near the launch point. The glider was seriously damaged. The tractor was parked unusually close to the peri-track (roughly measured as 8 metres from the centre line). There were cars parked in or near the normal tractor parking position.", actions: "It is difficult to judge from the driving seat of a car towing a glider, the clearance at the wing tip. Appropriate care needs to be taken. If there is no help positioned to watch the travel of a wing tip, then the driver is wise to get out to check. A secondary but significantly contributory factor was the position of the parked tractor. Nothing should be parked within 10 metres of the edge of the peri-track (See section 3.2 of the Pilots Manual).", volume: 1 },
  { id: "2013-07-241", date: "2013-07", displayDate: "July 2013", year: 2013, title: "Safety lesson", report: "", lessons: "Whilst being launched, a single seat glider was accelerated in the initial stages so rapidly that it pitched nose up to a steep climb angle in spite of full forward stick. In the opinion of the pilot and witnesses, had the launch failed at that point, a safe recovery would not have been possible. Fortunately the launch continued with no further problems.", actions: "Because of the position of the launch hook below the centre of gravity of the glider, a large forward force at the hook will make a glider pitch nose up. Pilots should be aware of this if they are flying a glider type with relatively ineffective pitch control in this situation. All-moving tail planes may be stalled. Elevators may be ineffective at low speed (say <20kts). A light weight pilot will not help. Winch drivers must be requested by the pilot to accelerate these glider types with due care.", volume: 1 },
  { id: "2013-07-242", date: "2013-07", displayDate: "July 2013", year: 2013, title: "Safety lesson", report: "", lessons: "Whilst on approach to land to the west, a pilot saw another glider climbing past him, on the launch, to his left. The approach was parallel to the launch line, about 50 yards to the north. The cable parachute fell to the north of and close to the landing glider as it rolled to a stop. The pilot of the landing glider had made a radio call and had started his cross wind leg from the north no less than 600 feet.", actions: "This was an uncomfortably close encounter. There is no apparent reason for the approaching glider to not have been noticed prior to the launch. It is obviously extremely important that the person acting as launch marshal takes time and trouble to carefully look out for gliders in the circuit. Others should assist. The launch point radio must be on and audible to the launch marshal and others at the launch point.", volume: 1 },
  { id: "2013-06-243", date: "2013-06", displayDate: "June 2013", year: 2013, title: "Safety lesson", report: "", lessons: "The pilot of a newly rigged glider realised whilst on a launch that he had no elevator control. He released from the cable and after an uncontrolled descent crashed, writing off the glider. The pilot survived the crash with only bruises. Investigation showed that a pin that should have been, was not inserted in the elevator control linkage.", actions: "Whilst the outcome was not as tragic (i.e. fatal) as is typical when an elevator is not connected, the accident has some a very important salutary aspects about which all should be aware. Primarily, such events are entirely avoided by proper attention to and execution of rigging checks and positive control checks during DI. It must be clearly understood who is responsible for rigging integrity and for a thorough DI. And they must be sure that those responsibilities are discharged.", volume: 1 },
  { id: "2013-06-244", date: "2013-06", displayDate: "June 2013", year: 2013, title: "Safety lesson", report: "", lessons: "After a landing to the west, on getting out of his glider, the pilot ran in a direct line from his landing point to the west wind launch point to collect his car, whilst take up slack for another glider was being signalled from the south launch point. The launch team and the winch driver saw what was happening. The launch was stopped.", actions: "It appears that the pilot didn’t look or didn’t see what was happening. Only through the watchfulness of others was a possible accident averted. Gliders, vehicles and persons on the airfield are a potentially serious hazard to launching and landing gliders. Great care must be taken with movements on the airfield. Airmanship must be exercised.", volume: 1 },
  { id: "2013-04-245", date: "2013-04", displayDate: "April 2013", year: 2013, title: "Safety lesson", report: "", lessons: "Whilst a tractor on a glider retrieve was being reversed into position, the rear platform struck and knocked over a member of the glider crew who was retrieving a rudder lock from the tractor. It was subsequently found that the impact had caused a bone fracture.", actions: "It’s all too easy to assume and not check that there is nobody behind a tractor when reversing. Tractors are heavy, powerful and less controllable than cars. There are no mirrors so it’s necessary to deliberately turn one’s head around and be totally sure that nothing or nobody has moved into the danger area before backing.tractors.", volume: 1 },
  { id: "2013-04-246", date: "2013-04", displayDate: "April 2013", year: 2013, title: "Safety lesson", report: "", lessons: "To avoid flying into another landing ahead of it, a glider made a turn so low that a wind tip touched the ground, the glider slewed in the air and landed sideways. The glider was significantly damaged but the pilot was uninjured. Prior to these events, the pilot had been searching for a thermal. Whilst on the downwind leg of what was seen as an already a low and close in circuit, the pilot decided to make a 360 degree turn away from the field to allow another glider, higher and further away from the field, to get ahead. The result was he ended up even lower in the circuit and behind the other glider. The other glider made a normal approach and landing.", actions: "The wind tip having struck the ground, it was fortunate that the glider did not crash nose down (“cartwheel”). The lessons to be learnt or re-enforced are: � Turning when very low can easily have the obvious consequences. That’s one reason why we start approaches at 300 feet and make any direction changes needed early on. � Joining the circuit low makes it more difficult to cope with other circuit traffic and any unexpected sink. So don’t do that. � If you are lower than another glider you have priority in landing and you should avoid confusion by not using that priority. � To turn away from the field whilst in the circuit usually makes a difficult situation worse – or even hazardous if low. � When a pilot sees another landing glider, he should anticipate early any conflict on the normal approach. If he is able to, he should increase separation by landing elsewhere from the expected landing area. � And as we are all taught, if you are very low in the circuit you should land from an abbreviated circuit, which usually means landing away from the normal area in use.", volume: 1 },
  { id: "2013-03-247", date: "2013-03", displayDate: "March 2013", year: 2013, title: "Safety lesson", report: "", lessons: "After an uneventful flight and landing, a pilot found himself unable to exit the aircraft. A metal hook used for routing the laces on his boots had become fouled in the rudder cable. The boot had to be taken off to get out. The pilot believes that in an emergency bailout situation he would have not been able to get out of the aircraft.", actions: "An unusual but nevertheless perhaps an easily repeatable set of circumstances. Be warned that hook type lacing fixings on boots can catch on cables. The clear advice is to avoid this type of footwear if possible and/or take care if the hooks are near cables.", volume: 1 },
  { id: "2013-03-248", date: "2013-03", displayDate: "March 2013", year: 2013, title: "Safety lesson", report: "", lessons: "Whilst a glider was being rolled onto a hangar trolley it was being stationary by hand. One of the holder’s finger tips was nipped and badly gashed.", actions: "Gliders weigh several hundred pounds and trolleys have sharp edges. It does mean getting down on the floor but it is safer to stop a trolley from rolling with a foot when loading or unloading a glider.", volume: 1 },
  { id: "2013-01-249", date: "2013-01", displayDate: "January 2013", year: 2013, title: "Safety lesson", report: "", lessons: "A winch launch was not stopped when the stop light was turned on after the all-out. The lights operator heard STOP called and pressed the stop button and confirmed by looking, that the light was showing continuously. The signal light was checked and found to be perfectly visible at the winch. There was no issue with sunlight. The winch driver did not recall seeing any stop light and stated that he must have been concentrating on the glider. There were no consequences.", actions: "It was fortunate that there was no serious or ongoing reason to stop the launch. However there might have been. For example a wing may have dropped to the ground which could have lead to a very serious accident in which the glider ground looped or \"cart wheeled\". The usually serious consequences of that might be avoided if the winch is promptly stopped. Winch drivers must be vigilent, watch for and respond instantly to STOP signals.", volume: 1 },
  { id: "2013-01-250", date: "2013-01", displayDate: "January 2013", year: 2013, title: "Safety lesson", report: "", lessons: "After the cable retrieve tractor had reached about 100yards from the winch, the winch driver was seen to attempt to halt the retrieve by shouting “stop”. The winch driver and then the launch point switched on their stop signals. A pilot on the field managed to stop the tractor when it had reached over 50% of the run. The reason for the request to stop was that cables being towed out were crossed. Issues with the PMRs used for intercommunication between winch and launch point impacted on sorting the problem.", actions: "Fortunately on this occasion there were no serious reasons for the stop command. But there might have been. There is currently no established practice for stopping retrieves. Those who update guidance in the launch marshals and winch driving manuals are being asked to include a. instructions to use stop lights for this purpose – and b. instructions to retrieve drivers to watch for these signals and stop promptly if seen. The potential for PMRs to be used as a safety aid means that it is important that attention is given to correct any defects.", volume: 1 },
  { id: "2012-12-251", date: "2012-12", displayDate: "December 2012", year: 2012, title: "Safety lesson", report: "", lessons: "During a launch from S to N a simulated launch failure was instigated. There was a small westerly component in the wind. Part of the cable assembly struck a members vehicle parked in the vicinity of the hangar causing some damage.", actions: "Because of the increased possibility of cable assemblies falling on persons or objects off the airfield, it is not normal practice for simulated launch failures to be attempted in the S to N launch direction when there is any west in the wind. If this safety measure is about to be, or has been accidentally overlooked, (as has happened before, see Feb 2010), anyone should point this out. Because of the potential for lethal consequences from falling shackles, care MUST be taken on ANY X-wind launch to lay off against the direction of the wind enough to ensure the cable falls to ground well inside the airfield whatever the height of release.", volume: 1 },
  { id: "2012-12-252", date: "2012-12", displayDate: "December 2012", year: 2012, title: "Safety lesson", report: "", lessons: "A crack of about 40cms was found in the canopy of a two seat glider. It radiated away from the front DV panel aperture starting from the sliding panel rails The sliding panel was found to be jammed. Nothing had been reported or documented either on the jamming or the crack.", actions: "It is almost certainly the case that the crack formed because of misguided over forceful attempts to free up the sliding panel. The result has been a glider out of service for days and many hours work to make a repair which if done off–site would have cost several hundred pounds. Canopies are made of delicate materials and must be treated accordingly. If a panel is jammed get experienced help. Two seaters have two DV panels so if one is jammed use the other. And the rear panel always works best for locking/ unlocking and opening/closing the canopy. And finally - if you make a mistake - safer to own up than any suspicion be left.", volume: 1 },
  { id: "2012-11-253", date: "2012-11", displayDate: "November 2012", year: 2012, title: "Safety lesson", report: "", lessons: "After a light westerly wind reduced, several gliders landed in quick succession towards the south west. The number on the field in the NW quarter reached 7. The number reached that level because some gliders were not recovered as quickly as they might have been.", actions: "There were no consequences other than that a couple of gliders had to land near the launch line (i.e. near the cables). There was empty airfield to land on but options were reduced. Such a situation can be dangerously challenging to early solo pilots or those having to make a low approach. It is a key aspect of good airmanship to clear gliders from the landing area as soon as possible – and even faster in circumstances as described.", volume: 1 },
  { id: "2012-11-254", date: "2012-11", displayDate: "November 2012", year: 2012, title: "Safety lesson", report: "", lessons: "On landing in a cross wind a glider stopped about 20 yards upwind of the line from winch to launch point, about 1/4 of the field length from the launch point. The next launch was preparing to launch without getting that glider moved, when the pilot of the landed glider signalled stop with raised arms. Launch preparation was stopped. The landed glider had dragged a cable with its tail skid. The cable was still under the glider", actions: "Clearly, had the pilot of the landed glider not taken the action he did, or had he not been seen, a launch might have been started with a cable under a glider. Even if a glider is upwind of the cables, the following must be considered: a. has the glider dragged a cable in landing on it or across it? b. could an abandoned launch unavoidably collide with the landed glider by cross wind or downhill yaw?", volume: 1 },
  { id: "2012-07-255", date: "2012-07", displayDate: "July 2012", year: 2012, title: "Safety lesson", report: "", lessons: "On a launch ground run the downwind wing went down and was dragged on the ground for several metres. The pilot did not release. The glider climbed away uneventfully . The wind was 20kts and 60� cross to the launch direction. As is the default practice, the wing runner was on the downwind wing & had been instructed to hold the wing parallel to the slope (downward).", actions: "This sequence of events can and has over time lead to very serious accidents. If the wing on the ground catches an obstacle, the glider yaws, the upper wing lifts, the glider rolls and yaws more, the nose impacts the ground at high speed. This tendency is exacerbated by cross wind from the upper wing side. The pilot’s own analysis shows that he realised the wing had gone down and he should have released without a moment’s hesitation. Nothing more to be said on that! Additionally, the wing tip holder must 1. hold the into wing if the pilot wishes 2. hold the wing such that the into wind wing is not more above the ground than the other 3. MUST shout STOP if the wing is being forced up or down by the wind from the required position.", volume: 1 },
  { id: "2012-07-256", date: "2012-07", displayDate: "July 2012", year: 2012, title: "Safety lesson", report: "", lessons: "The cable retrieve vehicle nearly set off again after a weak link break having re-attached the cable to the vehicle but without a weak link. The retrieve driver had not got permission from the winch to do this. Radio communications were available. The weak link break occurred when the retrieve was resumed after a stop for a landing glider which caused a loop on the winch drum.", actions: "Serious damage to the winch or even injury to the winch driver could have ensued. Fortunately the retrieve driver was stopped from towing the cable without a weak link. A weak link breaks must be taken as a problem indicator. Retrieves should never be resumed after a weak link break without positive clearance and never without a repaired / replaced weak link.", volume: 1 },
  { id: "2012-07-257", date: "2012-07", displayDate: "July 2012", year: 2012, title: "Safety lesson", report: "", lessons: "On a glider retrieve to the launch point, a trial lesson pupil was briefed to walk in front of the glider and stop it rolling forward at the top of the hill. At that point the pupil was then instructed to pull the tow rope off the glider. When the glider started to roll forward the pupil ducked underneath the wing. After shouts, four members ran to the glider and were able to stop it a couple of feet away from another gliders tail.", actions: "Obviously significant damage to at least one glider was only just avoided. Runaway gliders are hard to stop. That is why the person walking in front of the glider must be familiar with gliding, and be prepared and able to stop the glider. Instructors should never assume that TL pupils can comply. Members at the launch point should take over from TL pupils as soon as the glider returns.", volume: 1 },
  { id: "2012-05-258", date: "2012-05", displayDate: "May 2012", year: 2012, title: "Safety lesson", report: "", lessons: "A single seat glider was seen to climb at an alarmingly nose up angle for the first 100 feet. After that the launch continued until a safe release at the normal launch height. There was a significant cross wind and launches were difficult to handle. On debrief the pilot admitted he had not noticed that the seating position in the Ka18 would make it impossible to move the stick fully forward, he had not taken the time to focus his mind on his pre-flight checks nor taken the time to have a pre flight briefing. He had not thought through the differences in the type of glider he would fly, he had not properly checked that he would be able to achieve full control deflection nor had he carried out a thorough assessment of possible eventualities. The pilot had had a stressful morning whilst winch driving", actions: "It was of course extremely fortunate that the weak link did not fail whilst the initial stage of the launch was so steep. The almost inevitable failure to recover from that situation could have been fatal. Clearly the lessons from this incident are that the approach to any flight should never be undertaken whilst stressed, the met. conditions and possible consequences of them must be fully taken on board, and pre-flight checks must always be thoroughly undertaken.", volume: 1 },
  { id: "2012-01-259", date: "2012-01", displayDate: "January 2012", year: 2012, title: "Safety lesson", report: "", lessons: "Whilst soaring in wave lift west of the airfield well above cloud, the pilot saw that the up wind wave gap between clouds had begun to fill in. From reports the west edge of the wave cloud moved upwind obscuring the initially clear view of the airfield. Whilst attempting to descend to regain a view of the airfield the glider descended into cloud. It emerged from the bottom of the cloud about 1km downwind, east of the airfield. Before a landing was made the glider entered a spin and crashed. The pilot was seriously injured and the glider was damaged beyond repair.", actions: "● Know if the forecast shows any tendency towards increasing humidity (and so cloud) ● Monitor cloud amounts in wave gaps constantly and plan a descent immediately if they increase. ● Descend fastest by going to the where the sink is greatest - on the upwind side of the wave gap, ideally with a clear view of the ground. Open airbrakes fully, turn frequently to avoid any cloud and to maintain a good look out for other gliders doing the same. ● Remember that wind aloft in wave is usually stronger so it can take longer to reach a gap to descend through by going upwind than by going downwind. ● Before it's too late to avoid entering cloud, consider flying to any wave gaps downwind for an out landing. ● If you are forced to enter cloud, well before doing so, turn on the turn and slip or artificial horizon, fly straight and level heading upwind, set the trim to 60 - 70 kt,, open the airbrakes brakes to full, note the compass heading, try to maintain heading and speed with gentle control inputs,", volume: 1 },
  { id: "2011-10-260", date: "2011-10", displayDate: "October 2011", year: 2011, title: "Safety lesson", report: "", lessons: "A glider was being towed behind a car using a rigid tow-out bar. At the North end of the peri-track, travelling West there is a significant downhill gradient. The weight and inertia of the Glider caused the tow-out bar to bend on this slope and the Glider’s tailplane came close to colliding with the rear of the tow car. The driver noticed the problem and stopped before an impact.", actions: "A towed glider has a significant amount of weight and inertia and a tow-out bar is most vulnerable when in compression. Expensive damage can be caused to the tailplane of a glider if it impacts with the rear of a car. It is usually possible to choose a route around the airfield that avoids the steeper downhill gradients. Careful driving and a helper are recommended if a downhill section cannot be avoided.", volume: 1 },
  { id: "2011-09-261", date: "2011-09", displayDate: "September 2011", year: 2011, title: "Safety lesson", report: "", lessons: "The Skylaunch winch detached itself from the tow vehicle and rolled back to be stopped by the bungee gates. There was minor damage and no other consequence. The hitch on the winch had been recently changed. The winch driver was unfamiliar with the hitch or its correct operation.", actions: "It was fortunate that the event happened where it did, with no person, car or anything else behind the winch and that the gates stopped the winch from rolling down the ridge with inevitably serious damage and other potential consequences. The hitch was not correctly attached to the tow vehicle. The lesson here is that key instructional points MUST be communicated at the right time to all who must know.", volume: 1 },
  { id: "2011-09-262", date: "2011-09", displayDate: "September 2011", year: 2011, title: "Safety lesson", report: "", lessons: "With the pilots consent, a launch took place whilst a landed glider was about 200 yards downwind of the winch and about 30 yards on the downwind side of the cable line before the launch. The parachute fell d/w of the glider and about 25 yards from the cable line.", actions: "It appears this was a close thing. It was an unnecessary risk. Had the glider not laid off enough, or had there been more cross wind than anticipated, or had the winch failed during the launch, the cable may well have fallen over the landed glider and its crew. A launch should not be undertaken with a glider on the field downwind of the cable unless there is no possibility at all of a drifting cable falling on it.", volume: 1 },
  { id: "2011-09-263", date: "2011-09", displayDate: "September 2011", year: 2011, title: "Safety lesson", report: "", lessons: "The cable retrieve vehicle (Land Rover) set off from the launch point back to the winch with a cable still attached. It was stopped after 50 yards with no consequences.", actions: "Fortunately the vehicle took a clear route and was stopped before the cable was towed around people or gliders or other objects on the ground. The consequences of giving the driver incorrect signals or the driver not ensuring for certain that no cables remain attached can be result in serious injury or expensive repairs. It’s happened before! Care is always required!", volume: 1 },
  { id: "2011-08-264", date: "2011-08", displayDate: "August 2011", year: 2011, title: "Safety lesson", report: "", lessons: "A glider on approach when 6' from the ground the glider nosed down and bounced heavily enough to raise a divot with the main wheel. The pilot had been seen making a low outward turn in a SW wind then hurriedly starting a circuit. He admitted remembering late to lock the undercarriage requiring a change of hands on the stick.", actions: "Lessons here are 1. Circuits pattern for ridge soarable westerly winds should not be tried in SW winds – especially if below 500 feet. See the Pilots Manual. 2. Lack of compliance with the Pilots Manual advice here lead to a hurried lowering of the undercarriage and overlooking the need to lock it. Do not avoidably add workload to crucial phases of a flight. 3. The BGA advises that to avoid worse damage, late attempts to correct unlocked or un-lowered u/c should not be attempted. Such landings on grass rarely cause damage.", volume: 1 },
  { id: "2011-08-265", date: "2011-08", displayDate: "August 2011", year: 2011, title: "Safety lesson", report: "", lessons: "A glider was being reversed on a car at the launch point when its wing tip struck the wing tip of a glider waiting to launch. The impact was sufficient to cause the stationery glider to be moved. There was fortunately no damage.", actions: "Plainly this happened due to lack of sufficient care and/or an assumption, without checking, that there was clearance between the two gliders. Because of the danger of damage, and to preserve the grass, as a matter of principle vehicles should not be taken onto the launch point.", volume: 1 },
  { id: "2011-07-266", date: "2011-07", displayDate: "July 2011", year: 2011, title: "Safety lesson", report: "", lessons: "After a loss of power during the rotation phase of the launch the pilot lowered the nose for a launch failure landing. The cable parachute inflated in front of the glider. The glider flew under the rope cable and landed with it eventually fouling the right wing and yawing the glider that way on the ground run. Minor abrasion damage.", actions: "The inflation of a cable parachute in these circumstances is unusual but not unheard of. If there is a lesson here, if it happens, take as much care as possible to not fly at or under the parachute. Do not lower the nose more than necessary BUT ALWAYS MAINTAINING A SAFE AIRSPEED. This should give the parachute time to collapse and drop below the glider.", volume: 1 },
  { id: "2011-06-267", date: "2011-06", displayDate: "June 2011", year: 2011, title: "Safety lesson", report: "", lessons: "At the top of a launch to the S in a SW wind with the winch at the bowl (i.e. on the W. edge), a pilot was faced with a head on situation with a glider heading N. With “lay-off” bank on to the right to avoid drift, the pilot chose to retain the bank and turn away to the right. There were no consequences", actions: "This incident serves to illustrate the need for added care and discipline to avoid mid air collisions between gliders soaring the ridge and those on the launch. This is particularly so when the winch is positioned close to the edge towards the SW corner of the field in SW winds. Pilots soaring near the winch have a better view than those on the launch and MUST LOOK OUT and KEEP CLEAR of launching gliders that will be laying off to the West.", volume: 1 },
  { id: "2011-05-268", date: "2011-05", displayDate: "May 2011", year: 2011, title: "Safety lesson", report: "", lessons: "At the start of a launch, immediately after the wing tip holder released the tip, it went down onto the ground. The glider was not released from the launch rope / wire and the launch continued with no further consequences.", actions: "This is the second such report in two months. Not that many years ago at Camphill, a member suffered a very serious injury due to a cartwheel following a wing drop. It has happened here. So this message is repeated “IF YOU CANNOT KEEP THE WINGS LEVEL, RELEASE IMMEDIATELY ” If you don’t know whether the wing tip is on or near the ground then you are not paying enough attention to that.", volume: 1 },
  { id: "2011-03-269", date: "2011-03", displayDate: "March 2011", year: 2011, title: "Safety lesson", report: "", lessons: "The winch driver stopped the launch of a glider at about 50 feet. The launch point was up sun from the winch. Observing the light signals reliably required binoculars. The winch driver on his own launched the glider whilst holding the binoculars. In the consequent shaky image it was thought a wing tip had been seen to drop and a stop signal seen. There were no consequences.", actions: "Whilst the winch driver took the right action, clearly safety was compromised by depending on seeing the light signals by using binoculars whilst driving the winch. Being able to see light signals reliably is vital. If there is any difficulty, an observer is mandatory. Other information pointed to the need to keep the windscreen of the Skylaunch clean and to ensure that the lights at the launch point are correctly aligned. DO NOT assume or just hope it will be alright. If it's wrong, don't go ahead - put it right FIRST!", volume: 1 },
  { id: "2011-03-270", date: "2011-03", displayDate: "March 2011", year: 2011, title: "Safety lesson", report: "", lessons: "After the wing tip holder released the wing tip of a glider being launched across the slope at the south end, the right wing tip went down and ran along the ground for some 10 –15 feet for about 2 seconds. The glider continued to launch without further incident.", actions: "Whilst this launch happily did get off the ground, this was one of those occasions when the advice is – IF YOU CANNOT KEEP THE WINGS LEVEL, RELEASE IMMEDIATELY . If the wing stays on the ground, it can get caught. The consequences of not releasing are then very serious, even fatal. The up-most wing can fly, leading to the glider at least “cart-wheeling” and even rolling inverted. It’s all over in a couple of seconds!", volume: 1 },
  { id: "2011-03-271", date: "2011-03", displayDate: "March 2011", year: 2011, title: "Safety lesson", report: "", lessons: "On arrival back at the launch point the tow rope was disconnected from a glider and thrown backwards landing on the wing. The tractor driver, believing the tow cable to be disconnected, set-off to park the tractor. The rope jammed in the aileron slot, causing the glider to be dragged approx. 8 meters sideways before the tractor was stopped. No damage was done. The tractor driver was inexperienced.", actions: "The lack of damage was luck. This could have lead to a very costly and long repair. Attention must always be given to the possibility of the tow rope not being properly detached, and care must be taken that the rope isn't fouling any part of the glider. Tractor drivers must be aware of their responsibility to also ensure that the rope is clear of the glider before they move off. New members must be briefed on this.", volume: 1 },
  { id: "2011-02-272", date: "2011-02", displayDate: "February 2011", year: 2011, title: "Safety lesson", report: "", lessons: "Whilst a cable was being wound in to the west, so that the launch point could be changed, the parachute flew and was taken some 30 yards off track helped by the south westerly wind. Whilst the cable was still moving the parachute and weak link struck a car being attached to a glider. The car suffered about �2000 worth of damage. The driver was out of the way, so was not impacted.", actions: "This was potentially a much more serious accident than it was. It was very fortunate that the driver was not injured. As is well known, when cables are wound in at speed, parachutes can and do fly, and then track sideways. This follows another cable wind-in incident in April 2010. Winches, cables and parachutes can cause serious injury and damage. So whenever winding in cables, utmost care and attention is required at all times.", volume: 1 },
  { id: "2011-01-273", date: "2011-01", displayDate: "January 2011", year: 2011, title: "Safety lesson", report: "", lessons: "Whilst doing release checks it was noticed that the smaller of the two Tost rings at the end of the cable had distorted and was oval. The strop was taken out of service.", actions: "Tost rings almost never distort, but this example shows that it can happen. If this happens they can jam in the hook - which means that the glider cannot release. That is a potentially dangerous occurrence. On every occasion before a cable is attached to a glider the rings should be visually checked for distortion or cracks. Any such weak link must be taken of service and made impossible to use.", volume: 1 },
  { id: "2010-11-274", date: "2010-11", displayDate: "November 2010", year: 2010, title: "Safety lesson", report: "", lessons: "During a launch to 1,300 feet the canopy rapidly misted over on the inside. By ventilation the pilot was able to maintain a restricted view directly forward but internal wiping was ineffective. With only the help of the clear vision panel, the pilot, believing there to be another glider potentially in circuit, decided to extend his flight. When the other glider announced a circuit, and after a suitable period of time, the pilot elected to join the circuit and completed an uneventful landing. The conditions were cold and humid. No other pilot had reported a problem with misting canopies. Canopy jettison was been considered but rejected.", actions: "Canopy jettison could have impacted the integrity of the glider. The decision against was probably for the best. A radio call which drew attention to the difficulties could have been helpful to other gliders flying at the time. Given that no other gliders reported internal condensation, it appears that the owners have learned that their demisting system is not as effective as some. Others should be wary. Whilst not a factor here, it is a recommended practice that a launch should not proceed if the canopy is misting. There is a temptation to assume that the canopy will clear once the launch has started. The experience of this pilot shows that canopy misting can be a real hazard and that a canopy will not always clear when a glider is flying .", volume: 1 },
  { id: "2010-10-275", date: "2010-10", displayDate: "October 2010", year: 2010, title: "Safety lesson", report: "", lessons: "A two seater pilot, short on height in a r/h circuit to land to the SW, and aware of another glider ahead in the circuit, turned in early at the windsock for a shortened circuit and landing in the S half of the airfield. The single seater ahead of the two seater, also on a r/h circuit, turned finals at the trig point and established an approach as the two-seater turned finals. Consequently one followed the other on approach and they finished their landing runs about 250 yards apart. Pilots of both reported they were always aware of the other, and were seeing each other when that was possible. There is no report on whether radio was used to assist.", actions: "The lesson here is in the demonstration of how to manage a situation where two gliders are low and so must necessarily land at much the same time. The pilot in the best position to do so took the initiative, flew an abbreviated circuit, leaving as much space as possible for the other glider to land. The description of events indicates that this was handled safely and without risk, because of good look out, thinking ahead and prompt response. Whilst use of radio has the lowest safety priority (remember 1st aviate, 2nd navigate, 3rd communicate), if it can be safely used to help in these situations, radio should be considered at least.", volume: 1 },
  { id: "2010-10-276", date: "2010-10", displayDate: "October 2010", year: 2010, title: "Safety lesson", report: "", lessons: "On the first launch of the day (of a Puchacz), the Skylaunch winch moved more than a metre sharply sideways towards the other winch. The power was cut and there were no other consequences. The Skylaunch chocks were down, handbrake on, a wooden chock was in front of a rear wheel and its equivalent of a jockey wheel down on its wooden block. The ground was very wet.", actions: "This unexpected consequence of launching on a very wet surface was overcome by adding further ad-hoc chocks. It appears that the Skylaunch needs to be equipped with sufficient wooden chocks so that all four wheels can be chocked. Where possible this winch should be positioned on ground that is not rain sodden and slippery.", volume: 1 },
  { id: "2010-10-277", date: "2010-10", displayDate: "October 2010", year: 2010, title: "Safety lesson", report: "", lessons: "Whilst a cable was being repaired at the winch the cable was pulled from the launch point end before the job was in hand. The cable press was pulled away from those undertaking the repair and reportedly, fingers could have been trapped if they had been holding the cable. Radio communication on the day between winch and launch point was of inconsistent quality.", actions: "It is unsafe to pull a cable away from the winch unless it has been established that the winch operators know that is going to happen and have granted their permission. As well as potential injury to those working at the winch, the winch operators may start the winch and wind a cable in – which can have serious consequences to those handling the free end of a cable. If radio communication is known to be imperfect then no assumptions must be made. Alternative methods and rules of communication must be applied. If winch to launch point radios are not working correctly, or are not operated as they should, then the problem should be referred to the launch marshal, at least for reporting, if not action.", volume: 1 },
  { id: "2010-08-278", date: "2010-08", displayDate: "August 2010", year: 2010, title: "Safety lesson", report: "", lessons: "After the take up slack lights signal had started, the wing runner called “Stop” as he was unsure whether the cable was correctly attached. The lights operator signalled stop. The wing runner picked up the cable to attach it to the glider, when the cable started to move. It was reported that after signalling stop, the lights operator almost immediately cancelled the lights, which the winch driver interpreted as continuation of the normal take up slack signal. There were no consequences because the wing runner let go of the cable as it started to move, the winch driver saw that the wing was down, the launch was stopped.", actions: "It appears that all, - launch marshal, signaller, wing runner and winch driver reacted commendably promptly and correctly – apart from one aspect. The clear lesson is that when a stop signal is given it should left on until the launch marshal gives the instruction to cancel it.", volume: 1 },
  { id: "2010-05-279", date: "2010-05", displayDate: "May 2010", year: 2010, title: "Safety lesson", report: "", lessons: "On two consecutive days, on separate gliders, it was observed that airbrakes came open on the launch. In each case the effect was noticed. There were no consequences; one landed ahead, one closed the brakes and continued to the top of the launch.", actions: "It appears that the pilots did not thoroughly ensure that air brakes were closed AND LOCKED during pre-flight checks. In previous cases where the deployment of the air brakes was not realised, pilots have come to grief whilst not understanding why their sink rate was high.", volume: 1 },
  { id: "2010-05-280", date: "2010-05", displayDate: "May 2010", year: 2010, title: "Safety lesson", report: "", lessons: "The wing tip of a glider fell to the ground during the initial stages of a launch and stayed there for an estimated three seconds. A late call of stop was shouted. Reportedly the lights operator thought that stopping would be more hazardous than continuing so did not stop the launch. The pilot did not release in spite of this action being emphasised at morning briefing. The launch continued uneventfully. It's not known if the pilot was made aware or debriefed about this.", actions: "The is the second such event in only a few weeks. Again, the pilot was lucky to get away with it. Three lessons are these: Never hesitate before shouting stop or pressing the stop button. Always release the moment the wings cannot be kept level. If you wait to see what is going to happen is may be too late. Always ensure that both the pilot and the duty instructor know what happened.", volume: 1 },
  { id: "2010-05-281", date: "2010-05", displayDate: "May 2010", year: 2010, title: "Safety lesson", report: "", lessons: "A glider was about to turn onto approach with a view to a landing to the West. The approach path had been planned for a landing between two gliders that were being prepared for retrieve. One of the car/ glider combinations started to move off across the intended approach path and the glider turned to another approach direction to make sure there was no risk of collision. The glider subsequently landed with no incident.", actions: "Fortunately the landing pilot had enough height, time, skill and space to land elsewhere. A pilot may have little time to plan an approach and wants no doubts about moving obstacles on the field. A thorough and continuous lookout is of critical importance. Bear in mind the severely restricted view when inside a car. It is vital that movements in the landing area are carried out without any possibility of conflict with a landing glider. It is good airmanship and safe practice to remain stationary when a glider is landing, maximise landing space by moving within the landing area parallel to the general landing direction, lower a wing to the ground or stand alongside a vehicle to re-assure a pilot that they have been seen and park the tow vehicle pointing in the intended retrieve direction.", volume: 1 },
  { id: "2010-04-282", date: "2010-04", displayDate: "April 2010", year: 2010, title: "Safety lesson", report: "", lessons: "A glider’s retractable undercarriage was not lowered and the glider landed on its belly. The pilot confessed to operating the wrong lever in the cockpit.", actions: "A “wheel-up” landing is regrettably not an unusual event, most often due to simply overlooking the need to lower the undercarriage, by not carefully carrying out pre-landing checks. The lesson from this incident is to deliberately look at the lever you are grabbing when you are going to lower the undercarriage.", volume: 1 },
  { id: "2010-04-283", date: "2010-04", displayDate: "April 2010", year: 2010, title: "Safety lesson", report: "", lessons: "At the start of a launch from S to N a glider's left wing tip dragged on the ground for a few yards. There was some cross wind from the E. The glider yawed to the left as it came off the ground. Thereafter the launch continued without further incident. The pilot said he was unaware that the tip was on the ground. He did say he thought the wings were not level because the wind had got under the up wind wing.", actions: "Accidents that follow as a result of a wing tip dragging on the ground during a winch launch are some of the most serious in gliding. It very fortunate that this glider did not cartwheel or flip over. The BGA has issued a booklet called Safe Winch Launching and videos of winch launching accidents. These should be mandatory reading/viewing. Amongst several things, the booklet advises that if the wings cannot be kept level during the ground run at the start of a launch the pilot must release immediately. Additionally, the wing tip holder should hold wings parallel to the slope and on the downwind side if there is a cross wind – unless the pilot requests otherwise.", volume: 1 },
  { id: "2010-04-284", date: "2010-04", displayDate: "April 2010", year: 2010, title: "Safety lesson", report: "", lessons: "During a S to N launch, with a W'ly wind component, the cable parachute released during a simulated launch failure landed in the caravan park. Believing an object on the field was the cable parachute, the winch driver wound in the cable. Damage to a caravan and the hangar ensued.", actions: "Fortunately nobody was injured by the parachute, strop or rope when the cable fell or during the wind in and damage was slight. The main lessons arising are these :- In these conditions, if launching is to continue from the south, the launch point must be as far to the west as is practical and lay off to the west must be early and definite. The established club flying rule must be adhered to - that if gliders can sustain 600 feet in hill lift on the west edge, launching must be to the west. The mistake about the location of the parachute points to the need to be absolutely sure if a cable falls towards objects or obstacles, that it can be safely would in. The Winch Operating Manual is helpful on this point.", volume: 1 },
  { id: "2010-04-285", date: "2010-04", displayDate: "April 2010", year: 2010, title: "Safety lesson", report: "", lessons: "A glider was launched from S to N whilst another was in a r/h circuit along the back wall to land to the west. The glider in circuit had not been seen by the launch marshal. No downwind radio call was heard at the launch point on the external radio loudspeaker. There were no consequences.", actions: "In this case it was just fortunate that the launch was far enough ahead of the landing that there was no dangerous conflict. When there is a possibility, because of the wind strength, of a landing to the west launch whilst launching S to N (and even N to S), those in control of the launch must ensure there are no gliders in circuit anywhere that might cause conflict. It reduces the risk of missing this if pre-landing radio calls are made. The external launch point radio speaker must always be on with the volume high enough to be heard around the launch point.", volume: 1 },
  { id: "2010-02-286", date: "2010-02", displayDate: "February 2010", year: 2010, title: "Safety lesson", report: "", lessons: "Just after releasing from a launch a glider took action to avoid conflict with another that was thermal soaring in the area of the winches. The thermalling pilot had not seen the launch in progress and had no operational audio vario. There was snow on the ground. The launching pilot was aware of the thermalling glider during the launch.", actions: "The safety points here - a. it is hazardous to fly at or below winch launch height in the vicinity of the winch. Intensive look out for gliders about to launch must be maintained and the area left if/when that happens. b. flying with snow on the ground obviously increases the likelihood of not seeing gliders below – beware! c. thermal soaring without an audio vario obviously impacts lookout. d. it is not advisable to launch a glider when there is another glider at or below winch launch height in the vicinity of the winch. e. if a launching pilot detects potential conflict during a launch it would safest to abandon the launch", volume: 1 },
  { id: "2010-02-287", date: "2010-02", displayDate: "February 2010", year: 2010, title: "Safety lesson", report: "", lessons: "A winch driver misheard or misapplied a radio call so launched a glider with the wrong power settings. No significant consequences", actions: "To be sure that important information transmitted by radio is received as intended, the receiver repeats the information back. Good practice for winch-launch communications.", volume: 1 },
  { id: "2010-02-288", date: "2010-02", displayDate: "February 2010", year: 2010, title: "Safety lesson", report: "", lessons: "After a simulated medium height launch failure in a light cross wind the cable parachute landed between the winches cave and hangar. The instructor had requested that layoff was delayed a few seconds because of a glider upwind on the field.", actions: "Fortunately there were no people, vehicles or gliders in the area of the winches cave at the time. This was an illustration of the importance of lay off in x-winds and the possible results of not adhering to safe practices assiduously.", volume: 1 },
  { id: "2009-11-289", date: "2009-11", displayDate: "November 2009", year: 2009, title: "Safety lesson", report: "", lessons: "Whilst a pilot was getting out a glider a noise was heard that was taken to be a strap buckle striking the fuselage structure. It was seen during a subsequent launch that the speed to fly ring from the variometer was in the floor of the cockpit.", actions: "Plainly any loose object near the control runs is a potential hazard. If something unusual happens or is heard or something may have been dropped, which that could result in or indicate a loose object, then it's best not assume anything - you should check.", volume: 1 },
  { id: "2009-09-290", date: "2009-09", displayDate: "September 2009", year: 2009, title: "Safety lesson", report: "", lessons: "A glider made approaches to the west that ended up near to, on or crossing the peri-track or required a realignment of landing direction. The pilot was new on type.", actions: "Whatever the view from the cockpit, it is important to adhere to the first principles of approach control and reference point technique. Select and fly to the appropriate approach speed, and use more or less airbrake to control descent towards the reference point. Do not be tempted to lower the nose to get down - you end up lower but too fast and then overshoot.", volume: 1 },
  { id: "2009-09-291", date: "2009-09", displayDate: "September 2009", year: 2009, title: "Safety lesson", report: "", lessons: "In landing to the west a glider undershot and landed in rough ground. An undercarriage door was damaged. The pilot reported had flown the circuit in a way that assumed the wind was lower than it was.", actions: "It is particularly important to judge the wind speed correctly before and during an approach to the west by using all evidence available (e.g. cloud shadows, drift in the circuit, others soaring). Care must be taken not to apply too much air brake and/or for too long and end up too low to reach the landable area. It is essential to establish and continuously monitor your approach to a usable reference point making brake adjustments promptly.", volume: 1 },
  { id: "2009-09-292", date: "2009-09", displayDate: "September 2009", year: 2009, title: "Safety lesson", report: "", lessons: "In an approach to the west, a glider touched down but then flew on to fly over the west edge. Observers say the glider was initially low on approach, but the brakes were then put away and the glider appeared to be flying fast.", actions: "To make an accurate landing requires maintaining the correct speed and continuous monitoring of the gliders path down the glide slope to the reference point, making prompt corrections to speed and airbrake settings if required. Pilots must be wary of becoming fixated on one aspect and must rotate their attention between all things they must control.", volume: 1 },
  { id: "2009-08-293", date: "2009-08", displayDate: "August 2009", year: 2009, title: "Safety lesson", report: "", lessons: "In a circuit that started from the North the glider drifted to the east across the moor in the wind and made a low approach over the wall. Observers expected the landing to be on the moor. At least the last part of the approach was without airbrake.", actions: "It is important to monitor look down angle to the airfield and stay close to the back wall in a circuit for a west to south westerly wind. The unexpected sink over the moor (clutching hand) has previously forced landings on the moor. The Pilots Manual describes circuits to be flown in these and all other conditions.", volume: 1 },
  { id: "2009-08-294", date: "2009-08", displayDate: "August 2009", year: 2009, title: "Safety lesson", report: "", lessons: "A glider rotated into the climb very rapidly, the glider then rolled to the right about 30 degrees, and the glider yawed to the right about 30 degrees. The glider was reoriented to a normal climb without further incident.", actions: "This glider pilot was lucky. From what was observed there is little doubt that the right wing of the glider stalled and the glider was for a moment or two in a “spin on the wire”. Because this is one of the major causes of fatal accidents in gliding, on its website, the BGA has a series of videos that show how a glider spins and crashes during a launch that is mishandled. Every glider pilot should watch these. As well as this, it is essential that the guidance in the BGA winch launching leaflet as applied. Links to both the videos and leaflet are on the members website.", volume: 1 },
  { id: "2009-08-295", date: "2009-08", displayDate: "August 2009", year: 2009, title: "Safety lesson", report: "", lessons: "Tractors were parked at the North East launch point facing down the slope.", actions: "To avoid repeat of previous incidents when tractors have run away, with the obvious risk of consequences, the rule is (its in the Pilots Manual) that tractors are parked across the slope, in gear as well as with parking brake on.", volume: 1 },
  { id: "2009-08-296", date: "2009-08", displayDate: "August 2009", year: 2009, title: "Safety lesson", report: "", lessons: "A pilot turning whilst in a thermal turn saw another glider approaching in a straight path head on and only slightly above. The turning pilot levelled his wings and dived to avoid a collision. It was reported that the approaching glider pilot could not recall having seen the turning glider at that time.", actions: "It was fortunate, it appears, that the level of lookout by one of the pilots was sufficient to avoid a catastrophe. This is the second incident in a short time where a glider below the horizon was not seen. Because mid-air collisions are one of the 3 major causes of fatal accidents in gliding, serious lookout above and below, as well as on the horizon is vital.", volume: 1 },
  { id: "2009-07-297", date: "2009-07", displayDate: "July 2009", year: 2009, title: "Safety lesson", report: "", lessons: "The cable retrieve vehicle set off from the launch point without all cables having been detached. The driver stopped before going far after a shout. There had been some interruption to the unhooking of cables from the vehicle.", actions: "The consequences of dragging cables back to the winch are or can be both dangerous and costly. It is safest and best practice for the driver to check visually before moving off, getting out of the vehicle if necessary, rather than rely on others that all the cables retrieved have been detached.", volume: 1 },
  { id: "2009-07-298", date: "2009-07", displayDate: "July 2009", year: 2009, title: "Safety lesson", report: "", lessons: "The pilot of a glider undertaking a right hand circuit, the preferred one for the day, landing to the west, in spite of looking for any glider on the opposite circuit, saw another glider landing beside him only when on approach. The other glider had undertaken a left hand circuit, was lower and had seen the first before turning finals. The first glider had made a pre-landing radio call. The second glider was not radio equipped. The gliders maintained good separation during their landings.", actions: "The incident shows above all how hard it is to be sure that gliders are seen against the ground, especially if they are just below the horizon. A thorough scanning technique is essential. The incident also shows the risks of not flying the preferred circuit direction. The preferred circuit should be adhered to unless there is a safety reason not to. Thirdly, the incident shows the value of radio calls to alert other pilots of your landing intentions.", volume: 1 },
  { id: "2009-07-299", date: "2009-07", displayDate: "July 2009", year: 2009, title: "Safety lesson", report: "", lessons: "Whilst attempting to soar west of the field in a light SW wind, at a height and position when it was expected that a circuit would be started, a glider was flown North towards Rebellion Knoll. It then turned South along the West edge towards the airfield, but too low to reach it. The attitude of the glider at this time was seen to be nose high and speed slow. The glider landed outside the airfield boundary, on the bungee slope, with a ground loop in long grass. Fortunately there was no injury or damage. Although technically current, the pilot had relatively little recent flying.", actions: "When attempting to soar locally there is a need to be constantly vigilant about whether one is within gliding range of the airfield. Unless at least one field landing option is judged to be safely available, one should not commit to seeking lift out of gliding range. Pilots should be aware of the wind speeds and directions that generate usable hill lift. It is crucial to safety to monitor the ASI when flying low on a ridge, to not be deceived by the apparent high horizon that the attitude is safe and to have a greater than normal margin of airspeed above stall speed to keep control in gusts or be able to safely turn away for a field landing if need be. All this is helped by being in practice.", volume: 1 },
  { id: "2009-07-300", date: "2009-07", displayDate: "July 2009", year: 2009, title: "Safety lesson", report: "", lessons: "On approaching the launch point the cable retrieve vehicle turned towards the gliders waiting for a launch. The polyprop rope cables were consequently dragged sideways at head height to impact people next to a glider near the cable retrieve path. There were fortunately no injury consequences.", actions: "Even if the people and glider had not been close to the retrieve line, the turn and curved tow out track was ill advised because it provoked the possibility of crossed and hence entwined cables/ropes. Cable and./or ropes must always be pulled out in a straight line to minimise the potential of them wrapping around each other – and being dragged towards persons and/or gliders.", volume: 1 },
  { id: "2009-06-301", date: "2009-06", displayDate: "June 2009", year: 2009, title: "Safety lesson", report: "", lessons: "On seeing the unused cable moving as well as the glider at the start of a launch, more than one person at the launch point shouted STOP. The signals operator delayed signalling stop giving his reason afterwards that it was safer to let the glider achieve some height before stopping the launch.", actions: "Whilst the signals operator may have been correct that it is safer to not abort a launch during rotation into the climb, it is nevertheless the golden rule that a shout of STOP must be obeyed immediately. To re-enforce a related point – anybody can and must be allowed to call STOP for any reason without any fear of that call being questioned.", volume: 1 },
  { id: "2009-05-302", date: "2009-05", displayDate: "May 2009", year: 2009, title: "Safety lesson", report: "", lessons: "The take up slack signal was started and the cable started to move before it was realised that someone hidden from view was still lying on the ground, holding the cable, waiting to attach it to the glider. There had been a miscommunication about the glider being ready received by the person managing the launch. There were no consequences.", actions: "This isn’t the first of such incidents. Had the slack been taken up with speed, the hooker on may have been injured. It shows the importance of compliance with the advice in section 6.5 of the Launch Marshals Manual, that launch supervision should take place from a point in front of the glider where any hooking on activity can be seen.", volume: 1 },
  { id: "2009-04-303", date: "2009-04", displayDate: "April 2009", year: 2009, title: "Safety lesson", report: "", lessons: "On trying to exit from a glider after landing a pilot found he could not because his shoelace was caught in the rudder pedal mechanism.", actions: "Plainly in the unlikely event of a bail out anything that impedes exit is life threatening. Care should be taken that footwear and anything in the foot well of a glider do not foul each other.", volume: 1 },
  { id: "2009-03-304", date: "2009-03", displayDate: "March 2009", year: 2009, title: "Safety lesson", report: "", lessons: "A pilot opted to make a left hand circuit in a moderate to fresh south west wind. He found himself high on approach to the west and opted to turn left into the south-west part of the airfield. The glider was seen to be flying in significant turbulence, with apparent difficulty to keep control, before it turned west over the edge. Subsequently enough height was gained to land from the north.", actions: "The south west part of the airfield is bounded largely by the cliff face of “The Bowl”. Because of the steep profile, in winds with a westerly component the lowest air near and to the east of the edge, is full of vortices and “curl over”. This effect is so marked that near ground and near the edge, the wind can be east although the prevailing wind is west. Lest they loose control, gliders should not fly in this volume of air in these conditions. If forced to, or opting to, land at the south end in a south west wind gliders should stay low, away from the edge and expect a turbulent landing. The incident also points to the need to establish early an approach using a valid reference point - especially on approaches to the west.", volume: 1 },
  { id: "2008-12-305", date: "2008-12", displayDate: "December 2008", year: 2008, title: "Safety lesson", report: "", lessons: "On being asked to supervise a launch, a stand in launch marshal after hurriedly scanning for aircraft on approach, in the circuit in use and for obstacles on the airfield started the take up slack request. \"Stop!\" was immediately shouted by others as a glider on an abbreviated opposite circuit turned cross wind in front of the launch point.", actions: "The launch marshal has a significant responsibility to ensure that there is going to be no conflict during the launch. He/she must never hurry - must take time to ensure that all possibilities are assessed.", volume: 1 },
  { id: "2008-10-306", date: "2008-10", displayDate: "October 2008", year: 2008, title: "Safety lesson", report: "", lessons: "A wing of a glider being towed behind a car to the south end launch point struck a car. The glider was consequently damaged so badly it was an insurance write off - beyond economic repair.", actions: "To facilitate unhindered movement of gliders around the perimeter track and to avoid damage occurring as in this incident, vehicles must be parked more than 10 metres (i.e. greater than half a wing span of any Camphill gliders) from the edge of the track.", volume: 1 },
  { id: "2008-10-307", date: "2008-10", displayDate: "October 2008", year: 2008, title: "Safety lesson", report: "", lessons: "After getting low whilst soaring on the south edge in a brisk South-Westerly wind, a pilot elected to fly a left hand circuit across the clough and moor. He found himself in serious sink and just cleared the \"back wall\" on approach.", actions: "The \"clutching hand\" is a well known phenomenon at Camphill. In a South-Westerly wind, air forced up over the ridge descends into the clough and over the moor as the ground level falls away to the East. Gliders on approach in those areas in these conditions can find themselves sinking so fast and so much that they cannot reach the airfield. That is why circuits avoid those areas in strong SW winds. If low on the S edge, the advice is find possible lift on the South West corner. If at a sufficient height, start a tight circuit from there as described in the Pilots Manual.", volume: 1 },
  { id: "2008-09-308", date: "2008-09", displayDate: "September 2008", year: 2008, title: "Safety lesson", report: "", lessons: "A glider on approach had to change direction and extend it's approach glide path because a vehicle towing a glider across the airfield moved into the intended landing path. Although he believed he had looked sufficiently, the vehicle driver was not aware of the approaching glider - apparently because his views was obscured from within his car.", actions: "Plainly any moving obstacle (a person, vehicle, glider on tow) on the airfield when it is active presents a significant hazard. The larger the obstacle the greater the hazard. The responsibility of preventing an accident caused by a moving obstacle is with the person in control of it. There MUST be certainty that there is no conflict with a launch or landing. This incident shows that to be certain, there is a need to look up in all directions as well.", volume: 1 },
  { id: "2008-08-309", date: "2008-08", displayDate: "August 2008", year: 2008, title: "Safety lesson", report: "", lessons: "Whilst release checks were being carried out on the K13 prior to first launch of the day, the hook failed to release the cable when the knob was pulled. It was discovered that the instructors heel was preventing movement of the actuating lever on the hook mechanism.", actions: "Instructors should be aware that this is possible in at least one of the K13s and keep their left foot clear of the hook. Such obstruction could prevent quick release in the event that it were needed - which could be critical.", volume: 1 },
  { id: "2008-08-310", date: "2008-08", displayDate: "August 2008", year: 2008, title: "Safety lesson", report: "", lessons: "Two gliders started their circuit for a west wind landing at the same time, one from the bowl and one, lower, from over the trig point. Their tracks looked to conflict on the cross wind leg. Then it appeared that the higher pilot then took action to widen separation on the approach and landing. No radio call was heard from the higher glider.", actions: "It seems apparent that if these pilots were each observing the other from earlier in the circuit their proximity to each other in the circuit could and should have been avoided. The increased collision risk in the circuit MUST be recognised and it is vitally important to be looking for and anticipating the flight paths of gliders on potentially conflicting tracks. And to help in all this, it is good airmanship to make pre-landing radio calls.", volume: 1 },
  { id: "2008-08-311", date: "2008-08", displayDate: "August 2008", year: 2008, title: "Safety lesson", report: "", lessons: "Airbrakes opened on a launch - at about 200 feet. The pilot noticed and closed the airbrakes and there were no consequences. The glider had been moved forward during/after pre-flight checks.", actions: "This was a failure either to complete pre-launch checks or was a consequence of opening the airbrakes during the re-positioning prior to launch. Gliders can be launched successfully with the ABs open, the pilot then, unaware of this believes he/she is in heavy sink and can fail to complete a normal circuit/landing. This event highlights the importance and value of uninterrupted pre-launch checks, followed by the check question by the hooker on that \"brakes are closed and locked?\".", volume: 1 },
  { id: "2008-08-312", date: "2008-08", displayDate: "August 2008", year: 2008, title: "Safety lesson", report: "", lessons: "A canopy open whilst pre-launch checks were being undertaken in a cross wind blew closed. It was not being held at the time. There were no consequences.", actions: "Canopies can fracture if they suffer shock like this. This could have needed a very expensive repair. Open canopies MUST be held at all times in gusty conditions.", volume: 1 },
  { id: "2008-07-313", date: "2008-07", displayDate: "July 2008", year: 2008, title: "Safety lesson", report: "", lessons: "The launch point and surrounding area was set up and organised such that cars and gliders were parked near the peri-track so that gliders being towed could collide with them without diversion, a glider was parked within the launch point, at least one vehicle was amongst gliders on the launch point and gliders were positioned so that there was a danger of collisions on a sloping launch point. There was, fortunately, no consequential damage on this occasion.", actions: "Lack of good organisation, discipline and airmanship at the launch point leads at least to stressed pilots and very likely to damaged gliders. Lessons from past damage incidents have taught us that vehicles and gliders must be parked > 10m from the edge of the peri-track. Vehicles must not risk running over wings by being amongst gliders at the launch point. Gliders on slopes need attendance and/or chocks. Unused gliders should be picketed well away from the launch line.", volume: 1 },
  { id: "2008-06-314", date: "2008-06", displayDate: "June 2008", year: 2008, title: "Safety lesson", report: "", lessons: "The “All out” signal had been given, the wing runner stumbled and had to let go of the wing prematurely. The Pilot was not able to control the glider in the rolling plane and pulled the cable release before the wing tip touched the ground. The Pilot had his hand on the Cable release knob at the start of the launch and was able to take very prompt action which avoided an accident.", actions: "When, on a winch launch, a tip touches the ground it can yaw the glider so much that the lower wing stays stalled and on the ground whilst the upper wing lifts. The glider can then quickly roll inverted, inevitably causing serious injury and damage. Many such accidents have occurred. Pilots should be very alert to the possibility that a wing tip has touched the ground and/or, having realised it, should release from the launch cable immediately.", volume: 1 },
  { id: "2008-06-315", date: "2008-06", displayDate: "June 2008", year: 2008, title: "Safety lesson", report: "", lessons: "Someone had unhooked a cable from the tow out Land Rover and had hold of the top end of the drogue parachute with his back to the airfield when the K13 landed across the cables and caught that cable. This snatched the chute from his hand with enough speed to inflate the drogue chute. There was fortunately no injury.", actions: "It is not unusual for landing gliders to pull cables. Had the \"unhooker\" put his hand through the loop on the chute rather than just gripping around it, then that might have been serious consequences. So best handle cables and parachutes in a way that if accidentally pulled away they do not cause injury. Also, it is worth checking if gliders are landing across cables before/when handling.", volume: 1 },
  { id: "2008-03-316", date: "2008-03", displayDate: "March 2008", year: 2008, title: "Safety lesson", report: "", lessons: "Immediately after being brought out of the hangar in gusty conditions and whilst still in the lee of the hangar the rudder of a K13 was slammed over and fractured.", actions: "This graphically illustrates why rudder locks are used. It also illustrates again how gusty it can be on the lee side of the hangar. Whilst the norm is to get a rudder lock on to gliders as soon as they are picketed outside the hangar, clearly it is necessary to get the rudder lock on as soon as the glider tail is outside in windy conditions.", volume: 1 },
  { id: "2008-01-317", date: "2008-01", displayDate: "January 2008", year: 2008, title: "Safety lesson", report: "", lessons: "A K13 was blown 6 feet to the East across the grass picketing area in front of the hangar after the wind raised the picketed wing. The strength of the west wind and associated turbulence had increased. Launches had been stopped.", actions: "Clearly the picketing of the glider was inadequate for the conditions. This was nearly a costly incident - the glider was in real danger of being blown over. This also shows that in spite of being relatively sheltered, the lee side of the hangar can be subject to strong gusts. Gliders should be put in the hangar if the wind and/or gustiness is such that normal flying cannot take place. If not possible, then extreme picketing measures are required, and gliders should not be left unattended.", volume: 1 },
  { id: "2008-01-318", date: "2008-01", displayDate: "January 2008", year: 2008, title: "Safety lesson", report: "", lessons: "A few pilots landing to the west approached over the airfield boundary below the safest height, and some undershot the normal landing area. It was seen that little or no airbrake was used on most part of the approaches. The pilots had been soaring in strong wave. During their flights, wind had increased from about 20kts to about 30kts perhaps gusting to 40kts westerly. Turbulence over the field had caused launching to be stopped.", actions: "The approach paths observed arose from - a. allowing the glider to drift down wind in the turn onto and during the cross wind leg. b. use of airbrakes on the cross wind leg exacerbating the impact of sink leading to a low final turn. c. too early use of airbrakes and inappropriate flap setting on the approach leading to a low angle of approach. d. starting the circuit low for the conditions. It appeared that pilots had not correctly assessed the wind strength and/or the affect of that. Pilots should be able to establish that approximately by comparing ASI readings with ground speed and the angle of crabbing required. To ensure a safe landing to west in high wind conditions pilots MUST fly a high cross wind leg close to the airfield boundary. The effect of high wind, sink over the downwind boundary and judicious use of airbrake will ensure a safe high angle of descent to a reference point half way across the airfield. If a safe approach in high wind conditions requires flying faster than allowed with landing flap, then landing flap should not be used.", volume: 1 },
  { id: "2008-01-319", date: "2008-01", displayDate: "January 2008", year: 2008, title: "Safety lesson", report: "", lessons: "Whilst some gliders were flying high in wave, wind increased from about 20kts to about 30kts perhaps gusting to 40kts westerly and turbulence over the field caused launching to be stopped. After landing pilots indicated that the information given over the radio did not adequately describe the conditions – especially re turbulence and wind speed. There was also uncertainty on the ground about the protocol for giving advice over the radio as opposed to just passing on facts and observations. The hand held anemometer at the launch point could not be used due to a flat battery.", actions: "To assist pilots to make the right and safe decisions, information given over the radio to pilots must be purely factual. In terms of wind speed that means ideally at least an estimated figure, together with a value for gusting and the known presence and location of turbulence, adding moderate or severe as appropriate. No advice should be given. Reliable anemometer data should be available at the launch point. This would be is assisted by DI of and rectification of defects in equipment for the purpose.", volume: 1 },
  { id: "2007-12-320", date: "2007-12", displayDate: "December 2007", year: 2007, title: "Safety lesson", report: "", lessons: "A car crossed the airfield whilst a glider was launching. The pilot abandoned the launch before the glider left the ground.", actions: "This shows the benefits of pilots and launch point crew being alert to anyone crossing the airfield, who are either unaware of dangers or not thinking about them. Great care must be given when briefing visitors to the airfield. Non-members cars are not permitted airside. This also emphasises the need for warning signage.", volume: 1 },
  { id: "2007-09-321", date: "2007-09", displayDate: "September 2007", year: 2007, title: "Safety lesson", report: "", lessons: "Part way up the launch, the canopy opened. Fortunately all was well in the end but not until after an \"interesting\" period. The pilot reports that normal pre-flight checks had been completed but there had been a slight distraction whilst closing and locking the canopy.", actions: "It appears that pre-flight checks did not additionally include ensuring that the canopy did not lift when pushed upwards. This incident shows the value of checking that what looks locked really is locked.", volume: 1 },
  { id: "2007-09-322", date: "2007-09", displayDate: "September 2007", year: 2007, title: "Safety lesson", report: "", lessons: "The undercarriage structure of a glider suffered damage during a heavy landing. The glider landed to the West, into low sun. It had flown a circuit judged a little high and fast for the conditions. The wind strength had dropped during the flight.", actions: "Landing into low sun can cause loss of sight of the ground immediately ahead, thus impairing height judgement during the round out. Where there is an option, a line which is not directly into sun should be taken. Landing to the West at Camphill requires more than average attention to positioning and speed control - and making appropriate adjustments for wind strength.", volume: 1 },
  { id: "2007-08-323", date: "2007-08", displayDate: "August 2007", year: 2007, title: "Safety lesson", report: "", lessons: "A glider being launched from a slight down slope over ran the strop. The strop wrapped itself round the main wheel. This was noticed by the launch point crew who signalled to stop the launch - and the launch was stopped. The glider flew only a few yards and came to a halt with no consequences.", actions: "The consequences of a glider not being able to release from the cable at the top of a launch are make this a potentially serious incident. To prevent over-runs on down slopes gliders should be held back on any down slope during take up slack by a person on each wing tip. Not implicated here, but strops that have become too flexible from damage must not be used. This apart, the lessons are about what went right. The launch point crew and the winch driver were observant and acted promptly and correctly.", volume: 1 },
  { id: "2007-07-324", date: "2007-07", displayDate: "July 2007", year: 2007, title: "Safety lesson", report: "", lessons: "During an approach to land, the pilot found that once unlocked, one airbrake failed to deployed. The pilot was able to compensate for the in-balance, carried out a low approach then an otherwise uneventful landing. It was subsequently found that the Hotelier linkage to the a/b was not connected. The linkage was is good condition so could not have been properly connected during rigging. Pre-launch checks did not reveal the problem.", actions: "It is notoriously easy to fail to connect Hotelier linkages correctly. So it is important that the correct approach is used. It is recommended that for a/b's they are not locked when connecting. Due care must be applied, when checking for correct connection, to compensate for any impediment caused by a small access hatch, particularly in strong sunshine. Once a safe procedure for such critical safety tasks have been worked out, it is vital that the procedure is adhered to, with extra care taken not to deviate from this by being distracted or being in a hurry.", volume: 1 },
  { id: "2007-06-325", date: "2007-06", displayDate: "June 2007", year: 2007, title: "Safety lesson", report: "", lessons: "A member was advised (before they did so) not to handle a winch cable until the previous cable had been pulled in and could be seen to have stopped near the winch.", actions: "It is possible that a cable on the ground can be snagged by a cable that is being drawn in by the winch. This can present an un-expected and dangerous hazard particularly if the snagged cable is being handled at the time. It is a golden rule that cables must not be handled whilst the winch engine is running.", volume: 1 },
  { id: "2007-06-326", date: "2007-06", displayDate: "June 2007", year: 2007, title: "Safety lesson", report: "", lessons: "When a glider ran across cables on landing a normal projection on the skid mounting caught and dragged a cable. The stranded wire weak link in the tow out linkage broke and the hands of the person detaching the cable from the tow out vehicle at the time were lacerated. The cable was found to be standing above the ground in coils suggesting work hardening.", actions: "It is safest to assume, especially when handling cables, that when landing grounds runs cross cables, gliders can drag the cable. Glider pilots should aim to avoid running over cables on the ground. If dragged the cable can cause damage to the glider and maybe injury to anyone in contact with the cable. Sections of cables which have a permanent set which leaves them standing above ground level in coils should be cut out.", volume: 1 },
  { id: "2007-06-327", date: "2007-06", displayDate: "June 2007", year: 2007, title: "Safety lesson", report: "", lessons: "A landing run at speed through uneven ground bordering a cross-airfield road resulted in significant structural damage to the fuselage. This followed other landing runs observed crossing the road.", actions: "This accident demonstrates the importance of ensuring that the airfield surface, especially bordering roads, is sufficiently even. Because the edges of roads are prone to ridges and depressions, pilots should make conscious efforts to land so that they are not crossed during the ground run, especially during the early (faster) part.", volume: 1 },
  { id: "2007-05-328", date: "2007-05", displayDate: "May 2007", year: 2007, title: "Safety lesson", report: "", lessons: "Whilst undertaking a reciprocal landing the option was taken to use the skid on the K13 to reduce the ground run. The glider stopped nearer the airfield boundary that intended. This was believed to be due to due to wet grass. There was no other consequence.", actions: "Braking distances on wet grass can be longer whether using a wheel brake or skid. If allowed distance for overshoot is reduced to a minimum then an accident may well ensue.", volume: 1 },
  { id: "2007-05-329", date: "2007-05", displayDate: "May 2007", year: 2007, title: "Safety lesson", report: "", lessons: "During the launch run the pilots head struck the canopy and consequently the canopy was fractured. It was found that the pilot had less than an inch clearance above his head, his shoulder straps were slack, he was supported by a soft cushion and the rudder pedals were asymmetrically adjusted. The pilot was flying this type for the first time.", actions: "It is very important to be securely and safely installed in the cockpit before flying. This is much more important before a first flight on type. Soft cushions must never be used in cockpits. Care and time must be taken to ensure that all controls can be reached easily and that rudder pedals are correctly set.", volume: 1 },
  { id: "2007-05-330", date: "2007-05", displayDate: "May 2007", year: 2007, title: "Safety lesson", report: "", lessons: "After the \"all out\" signal was given by lights the glider continued to inch forward for 50 yards. When the stop signal was given the glider was launched - with no consequences.", actions: "Nobody should proceed to act in response to any signals or commands unless they clearly understand what those signals or commands mean or imply. Light signals to control glider launches are fully described in Laws and Rules.", volume: 1 },
  { id: "2007-03-331", date: "2007-03", displayDate: "March 2007", year: 2007, title: "Safety lesson", report: "", lessons: "In a strong wind, with a significant crosswind component, the wingtip holder found it difficult to raise the downwind wing tip from the ground and then to keep the wings level. Had he let go, the wingtip would have dropped heavily back to the ground. On being told of this, the pilot found that he had to hold the stick fully over, in order to balance the wings. This surprised the pilot. This position was held during most of the subsequent ground run and un-eventful launch.", actions: "If a wing tip touches the ground during the launch ground run there is a significant danger that the Glider will rotate uncontrollably about that wingtip causing a damaging accident, usually resulting in serious injury. If a wing tip holder finds it difficult to keep the wings level the pilot will not be aware that there is a potential problem. As was done in this case, it is of vital importance that the pilot is informed before the launch is allowed to start. If the launch sequence has started then the Wing tip holder should shout “STOP” so that the launch does not proceed.", volume: 1 },
  { id: "2007-03-332", date: "2007-03", displayDate: "March 2007", year: 2007, title: "Safety lesson", report: "", lessons: "The order to take up slack was given whilst the cable was still being hooked onto the glider. The acting launch marshal could not see the the hooker on. The launch was stopped before any further incident.", actions: "This is the fourth incident of its type that has been reported in this log. Fortunately there have been no injuries. The launch marshal must either attach the cable themselves or MUST stand in front of the glider in a position to see the hooker on has completed the task and is clear of the glider.", volume: 1 },
  { id: "2007-01-333", date: "2007-01", displayDate: "January 2007", year: 2007, title: "Safety lesson", report: "", lessons: "A two seater launching to the west was seen to drop its starboard wing firmly onto the ground and yaw to the right slightly. Neither pilot released. It then took off and safely completed the launch.", actions: "When, on a winch launch, a tip touches the ground it can yaw the glider so much that the lower wing stays stalled and on the ground whilst the upper wing lifts. The glider can then quickly roll inverted, inevitably causing serious injury and damage. Many such accidents have occurred. Pilots should be very alert to the possibility that a wing tip is has touched the ground and/or, having realised it, should release from the launch cable immediately.", volume: 1 },
  { id: "2006-12-334", date: "2006-12", displayDate: "December 2006", year: 2006, title: "Safety lesson", report: "", lessons: "After a wave flight a white card pilot under instruction flew down the base leg for a landing to the west at an agreed 60 knots minimum. After flying further than ideal the pupil when prompted executed a “low-ish” final turn. There was further prompting but the speed began to decay. The instructor took control at 50 knots, and completed (in his words) “a rather ragged landing but without damage to persons or property.”", actions: "The incident demonstrated the effect of the conditions prevailing and the need for alertness and positive action to adjust from the way a glider is flown in more benign conditions. In some conditions sink on the cross wind over the moor can be higher than normal. The wind gradient over the field in wave conditions can much greater. Rotor can even make the landing down wind. This incident reminds us that low experience pilots may not be able to recognise and/or react to dangers soon enough and for their safety they will be restricted in what they are allowed to, or are expected to attempt in such conditions.", volume: 1 },
  { id: "2006-10-335", date: "2006-10", displayDate: "October 2006", year: 2006, title: "Safety lesson", report: "", lessons: "The Instructor and Pupil had boarded the glider. It was to be the last launch of the day as a dark area of cloud and rain had been approaching. As the pre-flight checks were started, lightning was seen in the storm cloud. Although the cloud was still some way off a decision was made not to fly.", actions: "This is a good example of application of a B.G.A. Laws and Rules, Recommended Practice 28. This one says: “…winch launching should not take place if lightning strikes have been observed or it is anticipated they are imminent within 5 miles (i.e. 25 seconds between flash and thunder)… “", volume: 1 },
  { id: "2006-10-336", date: "2006-10", displayDate: "October 2006", year: 2006, title: "Safety lesson", report: "", lessons: "Gliders were being put away in a deluge of rain. The glider and tractor combination stopped in front of the hangar. The tractor driver quickly got off the tractor to help to pull the glider into the hangar. The wing nearest the open hangar door was held, but in the downpour, nobody noticed the tractor in the way of the other wing which struck the up-right of the tractor’s roll over bar. The impact caused a dent in the leading edge of the glider’s wing.", actions: "A job requiring a team of helpers should have one leader. Every member of that team has a responsibility for safe practice. If a task must be finished quickly or if there are unusual distractions then it is important that the team take special care and is particularly vigilant.", volume: 1 },
  { id: "2006-06-337", date: "2006-06", displayDate: "June 2006", year: 2006, title: "Safety lesson", report: "", lessons: "A glider returned to the airfield low after heavy unexpected sink. The approach from the east was to the middle of the airfield followed by a turn to land reciprocal to take off direction. The glider struck a tractor at the launch point and crossed the airfield boundary. There was slight damage.", actions: "Pilots need to be wary of heavy sink when low and so the margins for recovery are small. Reciprocal landings in an emergency are a reasonable airmanship option but care must be taken to consider the effects of landing down wind. A longer than normal ground run must be minimised by strict speed control. And wind gradient effects act in reverse to normal.", volume: 1 },
  { id: "2006-03-338", date: "2006-03", displayDate: "March 2006", year: 2006, title: "Safety lesson", report: "", lessons: "On a gusty day, wind WSW, the Puchacz was parked facing South, just outside the Northern hangar doors, right wing weighted down. The glider was momentarily lifted a foot off the ground by a gust.", actions: "The incident revealed how much in some conditions, the wind can accelerate in vortices and gusts round buildings. The lesson is that care should be taken to picket gliders correctly, even in the lee of buildings.", volume: 1 },
  { id: "2006-03-339", date: "2006-03", displayDate: "March 2006", year: 2006, title: "Safety lesson", report: "", lessons: "Whilst seeing a take up slack light signal, the winch driver noticed someone in front of the glider. Being in doubt, the winch driver obtained clarification by radio. The launch point said they were testing the lights and thought or assumed no winch driver was at the winch.", actions: "Good observation and safety principles were applied by the winch driver. This avoided what might have lead to damage and/or injury. Signal lights tests must be specifically agreed between launch point and winch. It is unsafe to assume anything where an accident could ensue if the assumption is wrong.", volume: 1 },
  { id: "2006-02-340", date: "2006-02", displayDate: "February 2006", year: 2006, title: "Safety lesson", report: "", lessons: "A glider was being towed, by car, from the launch back to the trailer park, round the peri-track. The driver was using a \"one man tow-out\" system. The wing tip was driven into a plantation of trees alongside part of the peri-track.", actions: "When carrying out a procedure which is out of the ordinary or not regularly practiced – extra vigilance is required.", volume: 1 },
  { id: "2006-02-341", date: "2006-02", displayDate: "February 2006", year: 2006, title: "Safety lesson", report: "", lessons: "A glider was being towed back to the launch point on the peri-track. A car had been parked within a wingspan of the peri-track. While still being towed and in an effort to move the glider away from the car, the wing tip holder tried to steer the glider onto the airfield but the main wheel of the glider skidded on the lip of the grass and the glider stayed on the road. The wing tip hit a glancing blow to the car. There was no damage to the glider wing tip.", actions: "Most car insurance policies do not provide cover for \"airside\" on an airfield. Cars should not be parked where they might cause a hazard and keys should be left in the vehicle in case they need to be moved. The tractor driver is in the best position to see if a wingtip is too close to an obstruction and should stop the tractor until the obstruction is cleared. It is important that tractor drivers keep looking behind to check that all is well.", volume: 1 },
  { id: "2006-02-342", date: "2006-02", displayDate: "February 2006", year: 2006, title: "Safety lesson", report: "", lessons: "A pilot was chatting to a new member as he prepared his glider for a launch. As he was strapping into the cockpit he realised he had left the rudder lock in place.", actions: "Camphill pilots are encouraged to walk round the glider and check that the control surfaces are moving in the correct sense, when operated by the controls in the cockpit, before boarding. Any obvious signs of damage will be spotted and it is a double check that \"towing out gear\" and the rudder lock have been removed and placed in a safe place. It is also a check that other hazards such as tyres and wing bags are clear of the glider. It is important that a pilot is not distracted. Nor should the pilot allow themselves to be distracted when carrying out safety procedures. If interrupted they should repeat the procedure.", volume: 1 },
  { id: "2006-02-343", date: "2006-02", displayDate: "February 2006", year: 2006, title: "Safety lesson", report: "", lessons: "The \"all out\" signal had been given before the cable was tight. The Winch driver had responded by accelerating. The pilot pulled the release before any damage was done. The person who had put the cable on had not pulled the shock rope ahead of the glider to check it was secure and, at the same time, stretched the weak link assembly in front so that there was no hidden slack under the glider.", actions: "Practice at Camphill is that the Launch Marshall should stand in front of the glider as the cable is hooked on to make sure they can see that all is properly prepared for the launch. It is recommended that the \"All out\" signal is given when the glider is seen to be moving forward. Anybody can shout \"stop\". There are separate and independent stop buttons available on the Launch point vehicle that over-ride the usual control box. The Pilot can always refuse a launch by pulling the release knob in the cockpit, must be alert to hazards and react quickly to a warning to \"stop!\"", volume: 1 },
  { id: "2005-12-344", date: "2005-12", displayDate: "December 2005", year: 2005, title: "Safety lesson", report: "", lessons: "After the strength (15mph) of the WSW cross wind was pointed out to the crew of a glider as they were boarding, a decision was made to immediately change the position of the winches from the SW corner.", actions: "One of the flying rules of the club (ref 2.7 of the Camphill Pilots Manual) states that \"Winches must be placed in such a position, and pilots must control their launch, to ensure that the falling cable cannot endanger persons or objects on the ground, or fall off-site, even if the winch fails or the cable breaks.\". If on a full height launch to the SW there is a cable break or winch failure or launch without \"lay-off\", then in a brisk wind with westerly component the cable parachute could be swept across the adjoining public road.", volume: 1 },
  { id: "2005-11-345", date: "2005-11", displayDate: "November 2005", year: 2005, title: "Safety lesson", report: "", lessons: "One glider was yawed during the landing ground run and executed a 180 degree ground loop towards and near to a collision hazard. Another was turned from it's landing run November 2005towards the peri-track.", actions: "Unless there is a good reason - i.e. for safety, it is poor airmanship to yaw a glider away from it's landing direction. The yaw can become uncontrollable and can consequently cause damage. And a change in direction could place the glider into the path of another glider landing behind.", volume: 1 },
  { id: "2005-11-346", date: "2005-11", displayDate: "November 2005", year: 2005, title: "Safety lesson", report: "", lessons: "One glider landed wheel up and another was damaged when an attempt was made to lower the u/c just prior to landing.", actions: "Landing wheel up is indicates inattention to pre-landing actions and check. Pilots should stick to a routine and should be aware of dangers of being distracted. Also, lowering the undercarriage during the final stages of landing is hazardous - BGA Recommended Practice 26 mentions this.", volume: 1 },
  { id: "2005-10-347", date: "2005-10", displayDate: "October 2005", year: 2005, title: "Safety lesson", report: "", lessons: "The launch of a glider continued to a height 10 to 20 feet, after lifting off with a wing tip on the ground. The launch was then abandoned, the winch driver having cut the power. During the ground run and airborne phases the glider yawed 45 degrees in the direction of the lower wing tip. The glider landed without further incident.", actions: "The consequence of a pilot not releasing the winch wire the moment a wing has touched the ground are potentially very serious - it could be fatal. The glider can very quickly yaw - in which case the glider may ground loop with a high forward speed causing serious and widespread damage. The upper wing may fly whilst the other remains on the ground, in which case the glider can execute a roll with yaw and a dive into the ground causing serious injuries. Pilots must therefore be alert to wing tips striking the ground, and release immediately if this happens, preferably before the event. Not known to be a factor in this case - once the glider is moving, wing tip holders must not over-ride a strong tendency for the wing tip to drop or rise because this prevents the pilot being able to sense that his ailerons are wrongly set.", volume: 1 },
  { id: "2005-09-348", date: "2005-09", displayDate: "September 2005", year: 2005, title: "Safety lesson", report: "", lessons: "A member riding in a standing position on the rear platform of a moving tractor was injured when his leg came into contact with the rear wheel.", actions: "Those riding on the rear platform should recognise this can be hazardous if they do not keep a firm grip on the roll bar with both hands and feet inside the platform edge. Tractor drivers must exercise due caution about rough ground and sharp steering when carrying passengers.", volume: 1 },
  { id: "2005-08-349", date: "2005-08", displayDate: "August 2005", year: 2005, title: "Safety lesson", report: "", lessons: "A glider on base leg down back wall and motor glider also on base leg along back wall in opposite direction saw each other late. Avoiding action involved the motor glider turning away from the airfield.", actions: "There is normally a preferred direction for circuits. Unless there are good reasons not to (e.g. for safety or emergency) that direction should be complied with. If not complying with the preferred circuit, extra attention to look out is required to see potential conflict in plenty of time to take controlled proximity avoidance action.", volume: 1 },
  { id: "2005-08-350", date: "2005-08", displayDate: "August 2005", year: 2005, title: "Safety lesson", report: "", lessons: "A two seater undertaking a trial lesson flew a well banked 180 degree LH turn completed at less than safest height to an approach to land between the hangar and west wind cable run.", actions: "This circuit is more demanding than others. If this circuit is used, due allowance must be made for height lost in the final turn. It is policy to fly TLs in a way that minimises avoidable risk.", volume: 1 },
  { id: "2005-08-351", date: "2005-08", displayDate: "August 2005", year: 2005, title: "Safety lesson", report: "", lessons: "A two seater undertaking training for landings to the west over ran the west edge peritrack by about a gliders length.", actions: "Because there is no overshoot area, approaches to the west require an early establishment of an approach at the correct speed to a reference point not more than half way across the airfield. If this not be achievable, action to over fly the edge or change landing direction must be taken early. Wheel brakes should not be depended on, and if fitted ought to be serviceable. (Not known to be factor in this case).", volume: 1 },
  { id: "2005-07-352", date: "2005-07", displayDate: "July 2005", year: 2005, title: "Safety lesson", report: "", lessons: "A glider joined a thermal by flying underneath one in the thermal from behind and then pulling up in front it. The joining glider ended up less than a glider's length in front of the established glider causing the latter to have to take collision avoidance action.", actions: "The proximity reported indicates that the joining glider's action significantly risked a mid-air collision by flying such that each glider could not continuously see the other. Joining, soaring and leaving a thermal are situations of increased hazard. There are clear and specific Recommended Practices in BGA Laws & Rules at RP21, 22 and 23. These must be complied with.", volume: 1 },
  { id: "2005-06-353", date: "2005-06", displayDate: "June 2005", year: 2005, title: "Safety lesson", report: "", lessons: "Cable retrieve Land Rover was stopped a third of way back to winches because one side of spreader bar had been left extended. Nothing had been hit by it.", actions: "The extended spreader bar projects about a metre from the side of Land Rover. It would cause serious injury if it struck a person or significant damage if it struck (say) another vehicle. It is essential that drivers take prime responsibility for ensuring the bar is safety withdrawn and latched before moving off. Those unhitching cables must enhance safety by ensuring the bar is stowed correctly.", volume: 1 },
  { id: "2005-05-354", date: "2005-05", displayDate: "May 2005", year: 2005, title: "Safety lesson", report: "", lessons: "After a low level cable break and cable snarl up on winch, cable was pulled out by launch point crew, without warning or agreement with the winch crew.", actions: "Winch crews often have to handle cables and cable drums. This can be hazardous. Before any move is made to pull cables from the winch, by hand or vehicle, a clear signal of agreement from the winch crew must be obtained. A similar incident was reported in July 2003.", volume: 1 },
  { id: "2005-05-355", date: "2005-05", displayDate: "May 2005", year: 2005, title: "Safety lesson", report: "", lessons: "Shock rope found knotted round the weak link cable, tightly, thus appearing to have been used that way in a launch.", actions: "It appears that the weak link was by passed by this thus defeating the purpose of the weak link - which is to limit to a safe level the launching loads on the glider structure. Anything wrong with the assembly at the glider end of the cable is more likely to be noticed if is laid out in front of the glider prior to launch.", volume: 1 },
  { id: "2003-09-356", date: "2003-09", displayDate: "September 2003", year: 2003, title: "Safety lesson", report: "", lessons: "After launch failure on S to N launch in NW wind., cable ended up across public road at wall top height.", actions: "The consequences of a road user colliding with a cable across the road would be serious. In a strong NW wind the launch point must not be so near the east boundary that a cable can drift over the road after a launch failure.", volume: 1 },
  { id: "2003-09-357", date: "2003-09", displayDate: "September 2003", year: 2003, title: "Safety lesson", report: "", lessons: "Exposed wing mirror bracket found projecting from bus at head level. Adjusted.", actions: "A good example of potential for injury being identified and action being taken to prevent it.", volume: 1 },
  { id: "2003-09-358", date: "2003-09", displayDate: "September 2003", year: 2003, title: "Safety lesson", report: "", lessons: "K18 rudder adjustment coupling separated on launch, making pedal unreachable. Landed without incident.", actions: "The design of rudder adjustment on this type (same on K7/13 & K13) needs care to ensure that the linkage is fully engaged before the pilot climbs in and is not dislodged before launch.", volume: 1 },
  { id: "2003-09-359", date: "2003-09", displayDate: "September 2003", year: 2003, title: "Safety lesson", report: "", lessons: "Glider taken to launch point without DI book signed.", actions: "A DI is a responsible task. DI's on club aircraft are required by a BGA Operational Regulation. Those taking their responsibility properly will not forget to sign the DI book.", volume: 1 },
  { id: "2003-09-360", date: "2003-09", displayDate: "September 2003", year: 2003, title: "Safety lesson", report: "", lessons: "A glider without radio, no. 2 in circuit, cramped circuit and was not seen by glider no. 1 in circuit", actions: "There is always potential for conflict between gliders flying a non-standard circuit pattern (for any one of many reasons) and those on a standard circuit. Consequently, it is essential that pilots in circuit look around carefully and continuously, ready to avoid other gliders if need be.", volume: 1 },
  { id: "2003-08-361", date: "2003-08", displayDate: "August 2003", year: 2003, title: "Safety lesson", report: "", lessons: "Take up slack signal given whilst tractor was being driven across a/f.", actions: "Severe injury and/or damage could be caused if a cable launching a glider strikes a tractor. Anyone venturing onto the airfield must STOP and before proceeding must be certain that they are not about to interfere with a launch or landing. As in this case, pilots, launch point and winch crews must be always alert for those who forget to stop and look.", volume: 1 },
  { id: "2003-08-362", date: "2003-08", displayDate: "August 2003", year: 2003, title: "Safety lesson", report: "", lessons: "Visiting motor glider flown low (est. 50 feet) over launch point on departure.", actions: "Good airmanship dictates that visiting pilots get permission to undertake such manoeuvres. They should not generally be given permission because low passes over the airfield are not permitted by the local flying rules because of the increased potential for accidental conflict with circuit traffic.", volume: 1 },
  { id: "2003-08-363", date: "2003-08", displayDate: "August 2003", year: 2003, title: "Safety lesson", report: "", lessons: "Glider made steeply banked 90 degree final turn inside SE boundary \"below tree top height\" before landing.", actions: "Circuit planning and circuit management should normally (i.e. unless unavoidable) be carried out with sufficient margins to avoid low final turns and their associated hazards.", volume: 1 },
  { id: "2003-08-364", date: "2003-08", displayDate: "August 2003", year: 2003, title: "Safety lesson", report: "", lessons: "Unzipped bag in compartment behind rear seat on Puchacz allowed objects to fall out.", actions: "Good airmanship and concern for safety requires that loose objects that could interfere with controls are not loose in the cockpit. Care is needed about bags and pockets.", volume: 1 },
  { id: "2003-08-365", date: "2003-08", displayDate: "August 2003", year: 2003, title: "Safety lesson", report: "", lessons: "Launch to west stopped late when another glider noticed flying low on west edge.", actions: "There is always potential for conflict between gliders hill soaring on the west edge and gliders being launched to the west. In this incident proper action was taken to minimise the risk. Gliders on the edge must also be aware of the potential conflict when they pass the launch line.", volume: 1 },
  { id: "2003-08-366", date: "2003-08", displayDate: "August 2003", year: 2003, title: "Safety lesson", report: "", lessons: "A low approach and pull up for base leg on TL flight", actions: "It is good airmanship and required practice to conduct trial flights with the minimum of additional risk such as these.", volume: 1 },
  { id: "2003-08-367", date: "2003-08", displayDate: "August 2003", year: 2003, title: "Safety lesson", report: "", lessons: "Public are parking cars on a/f", actions: "To reduce the risk of damage from and to cars and to avoid complications arising from lack of airside insurance cover, non-members cars are not normally allowed on the airfield.", volume: 1 },
  { id: "2003-08-368", date: "2003-08", displayDate: "August 2003", year: 2003, title: "Safety lesson", report: "", lessons: "Member of public walked across a/f just prior to launch.", actions: "The need for appropriate warning notices is clear. Even with these in place, launch point and winch crews must be alert for those who have not complied with warnings. Any directions to visitors must include a clear warning to not cross the airfield.", volume: 1 },
  { id: "2003-08-369", date: "2003-08", displayDate: "August 2003", year: 2003, title: "Safety lesson", report: "", lessons: "Finger injured when caught in cable tractor out riggers when closing.", actions: "Everyone should take care to foresee potential injury and pay attention to their own and others personal safety.", volume: 1 },
  { id: "2003-07-370", date: "2003-07", displayDate: "July 2003", year: 2003, title: "Safety lesson", report: "", lessons: "Trial flight launched with rudder lock still on glider.", actions: "Good airmanship requires that a pilot thinks about and carries out certain checks before getting into the glider and before proceeding to launch. This includes basic checks that no rudder lock is on and that all controls move fully and freely. On trial lessons extra care is required to ensure basics are not overlooked. In addition, everyone at the launch point, especially launch marshals, should be looking for and drawing attention to hazards.", volume: 1 },
  { id: "2003-07-371", date: "2003-07", displayDate: "July 2003", year: 2003, title: "Safety lesson", report: "", lessons: "Cable pulled off winch by launch point crew without warning, thus potentially injuring winch driver.", actions: "Winch crews often have to handle cables and cable drums. This can be hazardous. Before any move is made to pull cables from the winch, by hand or vehicle, a clear signal of agreement from the winch crew must be obtained.", volume: 1 },
  { id: "2003-07-372", date: "2003-07", displayDate: "July 2003", year: 2003, title: "Safety lesson", report: "", lessons: "Car driven by member of public across a/f whilst cables being towed out and gliders in circuit. Driver had been told to \"drive up track\".", actions: "The need for appropriate warning notices is clear. Even with these in place, launch point and winch crews must be alert for those who have not complied with warnings. Any directions to visitors must include a clear warning to not cross the airfield.", volume: 1 },
  { id: "2003-07-373", date: "2003-07", displayDate: "July 2003", year: 2003, title: "Safety lesson", report: "", lessons: "Base leg low over bungey gates wall, final turn below trees height after abandoning attempt to soar down wind of a/f in SE wind", actions: "Incidents of this type are avoided if pilots do not soar low, down wind of the airfield and in sink caused by a/the ridge. It is poor airmanship and potentially dangerous to fly low over objects on the approach and make low final turns. There is little or no margin for error or unexpected gusts.", volume: 1 },
  { id: "2003-07-374", date: "2003-07", displayDate: "July 2003", year: 2003, title: "Safety lesson", report: "", lessons: "Glider landed wheel up.", actions: "Wheel up landings can cause irritatingly costly damage. Not a significant safety issue but could be indicative of the pilot not carrying out all pre-landing checks - including some which might have more serious consequences.", volume: 1 },
  { id: "2003-07-375", date: "2003-07", displayDate: "July 2003", year: 2003, title: "Safety lesson", report: "", lessons: "After cable break in launch to SW, parachute landed in caravan park. Wind had increased from light to ridge soarable with wave during the day.", actions: "The consequences of a cable parachute assembly striking a person on the ground would be serious. The club's flying rules (see Pilots Manual) require in a south west wind winches are positioned so that falling cables cannot be blown off the airfield.", volume: 1 },
  { id: "2003-07-376", date: "2003-07", displayDate: "July 2003", year: 2003, title: "Safety lesson", report: "", lessons: "Signalling box button labelling was not clear.", actions: "The labelling on the unit should be clear and unambiguous.", volume: 1 },
  { id: "2003-06-377", date: "2003-06", displayDate: "June 2003", year: 2003, title: "Safety lesson", report: "", lessons: "Take up slack signal given before cable hooker-on, hidden by Puchacz fuselage, was clear.", actions: "The launch marshal must either attach the cable themselves or commence supervision of the launch by standing in a position where he/she can see if anyone else is still attaching the cable.", volume: 1 },
  { id: "2003-06-378", date: "2003-06", displayDate: "June 2003", year: 2003, title: "Safety lesson", report: "", lessons: "Visiting glider approached from over moor, lost approach speed in wind gradient, landed heavily and ground looped.", actions: "If a glider descends into the wind gradient without sufficient speed it can be impossible to maintain flying speed and the glider will consequently \"stall-in\". The ASI must be continually monitored. The chosen approach speed must be maintained by lowering the nose in the wind gradient. Air brakes should also be reduced if the need for increased speed is great and the rate of descent is high.", volume: 1 },
  { id: "2003-06-379", date: "2003-06", displayDate: "June 2003", year: 2003, title: "Safety lesson", report: "", lessons: "Visiting glider flew low base leg and final turn with wing tip estimated as 5 feet from ground. Wind gusting to 40kts.", actions: "In a high wind there is a significant wind gradient. There is a danger, in a low turn, of the lower wing being stalled, thus inducing a spin-in. In any event it will be more difficult to roll out of the turn. In high wind conditions, to be safe, circuits must be started from 500 feet or more and the approach made from a final turn at more than 300 feet.", volume: 1 },
  { id: "2003-06-380", date: "2003-06", displayDate: "June 2003", year: 2003, title: "Safety lesson", report: "", lessons: "Wing tip of glider being towed back to launch point struck aileron of parked glider. No damage.", actions: "Ground handling requires a lot of care and attention if damage or injury is not to be incurred.", volume: 1 },
  { id: "2003-06-381", date: "2003-06", displayDate: "June 2003", year: 2003, title: "Safety lesson", report: "", lessons: "Launch to south in SW wind without lay-off resulted in cable falling over public road.", actions: "The consequences of a road user colliding a cable across the road would be very serious. The club's flying rules (see Pilots Manual) require that in a south west wind winches are positioned so the road is not down wind of the winches.", volume: 1 },
  { id: "2003-06-382", date: "2003-06", displayDate: "June 2003", year: 2003, title: "Safety lesson", report: "", lessons: "Visiting glider left parked without being picketed. Seen to be rocking from tip to tip in the wind.", actions: "Good airmanship demands that care is taken of gliders by picketing them in accordance with principles to found in the Pilots Manual.", volume: 1 },
  { id: "2003-06-383", date: "2003-06", displayDate: "June 2003", year: 2003, title: "Safety lesson", report: "", lessons: "\"Landings too low\" for 25kt west wind conditions.", actions: "The significant wind gradient in strong west wind conditions mean that there is a danger, in a low turn, of the lower wing being stalled, thus inducing a spin-in. In these conditions, to be safe, the approach must be from a final turn at no less than 300 feet. See the Pilots Manual.", volume: 1 },
  { id: "2003-06-384", date: "2003-06", displayDate: "June 2003", year: 2003, title: "Safety lesson", report: "", lessons: "Training flight had to abandon soaring after being subject to competitive flying (being \"cut-up\") by a single seater.", actions: "Pilots should exercise good airmanship by making allowances for the competence of trainee pilots and the demands on the instructing them when flying with two seaters.", volume: 1 },
  { id: "2003-06-385", date: "2003-06", displayDate: "June 2003", year: 2003, title: "Safety lesson", report: "", lessons: "Cable hooked on to K13 through skid. Seen and launch stopped.", actions: "A cable trapped in the skid may not be releasable and that could have very serious consequences. Close supervision of those unfamiliar with hooking on is required. Good observation of detail at the launch point paid off in this case. It is less likely that any part of the cable assembly will foul any part of the glider if it is all in front of the glider at start of launch.", volume: 1 },
  { id: "2003-06-386", date: "2003-06", displayDate: "June 2003", year: 2003, title: "Safety lesson", report: "", lessons: "A paraglider at 400 feet obstructed the downwind part of the circuit SW wind circuit. Calls on the HG/PG radio were ineffective.", actions: "Because the west ridge is soared regularly by hang gliders and para gliders, pilots should be prepared for them being in the circuit pattern. Less experienced pilots should choose not to fly or should land if they feel they will be obstructed. Consideration must be given to suspending launching or changing launch points if the HG/PG traffic is too great for safe flying.", volume: 1 },
  { id: "2003-06-387", date: "2003-06", displayDate: "June 2003", year: 2003, title: "Safety lesson", report: "", lessons: "Propane storage tank valve left open.", actions: "To minimise the possibility of leakage the valve should be left closed.", volume: 1 },
  { id: "2003-06-388", date: "2003-06", displayDate: "June 2003", year: 2003, title: "Safety lesson", report: "", lessons: "Canopy jettison on Puchacz operated accidentally during ground run over track. No damage.", actions: "Care needs to be taken in the Puchacz, especially with trial lesson P2s, to ensure that hands are kept clear of the canopy catch levers and are not inadvertently operated.", volume: 1 },
  { id: "2003-06-389", date: "2003-06", displayDate: "June 2003", year: 2003, title: "Safety lesson", report: "", lessons: "A child was seen to be operating the lights signalling control box.", actions: "It clearly and unwisely adds risk if anyone other than a member or other responsible adult, familiar with the commands and controls, operates a key signalling system upon which safety depends.", volume: 1 },
  { id: "2003-05-390", date: "2003-05", displayDate: "May 2003", year: 2003, title: "Safety lesson", report: "", lessons: "The winch drew in a cable which was attached to a car (for purpose of pulling the cable off the field), pulling the car one third of the airfield. The car driver had notified the winch driver of the intention.", actions: "When non-standard or unusual procedures are undertaken, it is essential there is no misunderstanding. Before winding in cables after cable breaks, it is essential that a double check is made that the cable is not going to injure persons, damage gliders, vehicles, buildings, or any other object. When pulling cables attached to the winch, a weak link should always be used.", volume: 1 },
  { id: "2003-05-391", date: "2003-05", displayDate: "May 2003", year: 2003, title: "Safety lesson", report: "", lessons: "A glider on approach from east passed in front of glider on approach from north - apparently close and at same height - they apparently had not seen each other.", actions: "The circuit is a major danger area for mid-air collision. It is unforgivable to not exercise the scan cycle assiduously when in the circuit. That means looking up and to each side as well as straight ahead.", volume: 1 },
  { id: "2003-05-392", date: "2003-05", displayDate: "May 2003", year: 2003, title: "Safety lesson", report: "", lessons: "Winch applied full power when STOP signalled. (Pilot had released).", actions: "Pilot should be alert to unduly rapid take up of slack. Winch drivers must always take care they are reading the signalling lights correctly and take the safest action if they are unsure. \"Snatched\" launches can easily cause significant damage/injury.", volume: 1 },
  { id: "2003-05-393", date: "2003-05", displayDate: "May 2003", year: 2003, title: "Safety lesson", report: "", lessons: "Glider wing tip struck ground during ground run.", actions: "On the assumption that this was during take off, the lesson is that if a wing strikes the ground the release should be pulled immediately. Gliders can ground loop or roll inverted very quickly as a result of a wing tip on the ground causing serious injury and serious damage.", volume: 1 },
  { id: "2003-05-394", date: "2003-05", displayDate: "May 2003", year: 2003, title: "Safety lesson", report: "", lessons: "A glider joining another in a thermal at the same height established an overlapping circle, forcing the first glider there to abandon the thermal.", actions: "The risk of collision is increased when joining other gliders in a thermal. The risk must be minimised by flying in the same direction in concentric circles. BGA Recommended Practice applies.", volume: 1 },
  { id: "2003-05-395", date: "2003-05", displayDate: "May 2003", year: 2003, title: "Safety lesson", report: "", lessons: "Launching cable picked up another cable during launch. Launch abandoned at 600 ft - no consequences.", actions: "As was apparently demonstrated in this case, pilots should be sensitive to launches that do not allow the normal rate of climb and abandon them early enough to make a safe landing. The incident also demonstrates the need to keep clear of unused cables.", volume: 1 },
  { id: "2003-05-396", date: "2003-05", displayDate: "May 2003", year: 2003, title: "Safety lesson", report: "", lessons: "An unattended glider on a down slope rolled forward in the launch queue and impacted the rudder of the glider ahead.", actions: "If gliders are to be left without a brake person in front whilst in the launch queue the wheel must be chocked.", volume: 1 },
  { id: "2003-05-397", date: "2003-05", displayDate: "May 2003", year: 2003, title: "Safety lesson", report: "", lessons: "Member injured by being struck by trailing edge of wing during ground handling.", actions: "Significant and painful injuries can be caused by impact between people and wings. Everyone must be trained to be aware of the hazards and take care when lifting wings or rotating or moving gliders.", volume: 1 },
  { id: "2003-05-398", date: "2003-05", displayDate: "May 2003", year: 2003, title: "Safety lesson", report: "", lessons: "Cable tractor left on slope not properly braked or in gear started to roll away.", actions: "Members must remember and apply the guidance in the Pilots Manual. Park tractors across any slope, brake fully on and in gear.", volume: 1 },
  { id: "2003-05-399", date: "2003-05", displayDate: "May 2003", year: 2003, title: "Safety lesson", report: "", lessons: "The wrong wing tip was held on retrieve to west wind launch point.", actions: "All should be aware and reminded of the basics of ground handling - described in the Pilots Manual. In strong winds, holding the upwind wing tip prevents blow over.", volume: 1 },
  { id: "2003-04-400", date: "2003-04", displayDate: "April 2003", year: 2003, title: "Safety lesson", report: "", lessons: "After a release to simulate a low level cable break, the parachute continued to move because the winch cable was being wound in.", actions: "When a launch fails or the glider releases when low, the launch must be stopped immediately using the winch brake. All winch drivers must be trained to do this without fail. Failure to do so can cause the parachute to fly up into the glider.", volume: 1 },
  { id: "2003-04-401", date: "2003-04", displayDate: "April 2003", year: 2003, title: "Safety lesson", report: "", lessons: "Retrieve of two-seat glider direct to launch point obstructed landing area.", actions: "It is good airmanship and reduces risk to retrieve gliders via the peri-track.", volume: 1 },
  { id: "2003-04-402", date: "2003-04", displayDate: "April 2003", year: 2003, title: "Safety lesson", report: "", lessons: "Visitors were walking across on the airfield as a glider was preparing to launch. They had been told to \"go up the airfield\".", actions: "The need for appropriate warning notices is clear. Even with these in place, launch point and winch crews must be alert for wandering persons. Any directions to visitors must include a clear warning to not cross the airfield.", volume: 1 },
  { id: "2003-04-403", date: "2003-04", displayDate: "April 2003", year: 2003, title: "Safety lesson", report: "", lessons: "In light east wind conditions, there were a number of unnecessarily low approaches over the boundary and bus.", actions: "It is poor airmanship and potentially dangerous to fly low over people or objects on the approach. It can be and should be avoided by turning in earlier when getting low in the circuit.", volume: 1 },
  { id: "2003-04-404", date: "2003-04", displayDate: "April 2003", year: 2003, title: "Safety lesson", report: "", lessons: "There is uncertainty on whether it is best practice to stop the cable tractor for landing gliders or not.", actions: "The advised practice is to not stop for landing gliders unless a collision or damage / injury from moving cables will clearly ensue. See the Pilots Manual.", volume: 1 },
  { id: "2003-04-405", date: "2003-04", displayDate: "April 2003", year: 2003, title: "Safety lesson", report: "", lessons: "Two-seat glider on finals flew 10 feet over the launch point bus.", actions: "It is poor airmanship and potentially dangerous to fly low over people or objects on the approach. It can be and often is a result of failure to turn in earlier when getting low in the circuit.", volume: 1 },
  { id: "2003-03-406", date: "2003-03", displayDate: "March 2003", year: 2003, title: "Safety lesson", report: "", lessons: "The launch marshal and pilot about to launch failed to notice the change in wind direction from light NE to 8 kts SE.", actions: "Due to slow build of airspeed a downwind launch can induce rotation at too low an airspeed and will require a long, high ground speed landing run in event of a failed launch. It can also over speed winches. Wind direction and strength should be monitored before every launch.", volume: 1 },
  { id: "2003-03-407", date: "2003-03", displayDate: "March 2003", year: 2003, title: "Safety lesson", report: "", lessons: "A car was driven through gliders at the launch point.", actions: "Cars on launch points can be hazardous. Because of the risk of damage this should be avoided it at all possible.", volume: 1 },
  { id: "2003-03-408", date: "2003-03", displayDate: "March 2003", year: 2003, title: "Safety lesson", report: "", lessons: "Nylon shock rope found in cable assembly.", actions: "Members should be made aware of the hazard of recoil from the elasticity of nylon ropes and that only hemp ropes are permitted as shock ropes.", volume: 1 },
  { id: "2003-03-409", date: "2003-03", displayDate: "March 2003", year: 2003, title: "Safety lesson", report: "", lessons: "Pair of gloves found under seat of K13.", actions: "Any DI must include a search for objects that should not be left in a glider. It is particularly important to be vigilant on types that allow objects to fall under seats where control runs could be fouled.", volume: 1 },
  { id: "2003-03-410", date: "2003-03", displayDate: "March 2003", year: 2003, title: "Safety lesson", report: "", lessons: "On closing DV panel in Puchacz at top of launch, pupil touched and moved the canopy catch.", actions: "Care needs to be taken in the Puchacz, especially with trial lesson P2s, to ensure the canopy is not inadvertently opened. P1's should hold the rear lever firmly locked when front DV panel adjustments are made in flight.", volume: 1 },
  { id: "2003-03-411", date: "2003-03", displayDate: "March 2003", year: 2003, title: "Safety lesson", report: "", lessons: "Two-seat glider landed on cables after low approach.", actions: "It is inconsiderate to land on the cables if it can safely be avoided. A low approach can be and often is a result of failure to turn in earlier when getting low in the circuit.", volume: 1 },
  { id: "2003-03-412", date: "2003-03", displayDate: "March 2003", year: 2003, title: "Safety lesson", report: "", lessons: "People handling cables when gliders still on launch.", actions: "The launching cable can catch on and drag other cables on the ground. Dragged cables can inflict severe injury. Cables should be handled only when the previous one is fully wound in.", volume: 1 },
  { id: "2003-03-413", date: "2003-03", displayDate: "March 2003", year: 2003, title: "Safety lesson", report: "", lessons: "Visitors walked across the airfield. Apparently had not been given explicit instructions to not cross the airfield.", actions: "The need for appropriate warning notices is clear. Even with these in place, launch point and winch crews must be alert for wandering persons. Any directions to visitors must include a clear warning to not cross the airfield.", volume: 1 },
  { id: "2003-03-414", date: "2003-03", displayDate: "March 2003", year: 2003, title: "Safety lesson", report: "", lessons: "Two-seat gliders flew low over launch point on approach - one with brakes open.", actions: "It is poor airmanship and potentially dangerous to fly low over people or objects on the approach. It can be and often is a result of failure to turn in earlier when getting low in the circuit.", volume: 1 },
  { id: "2003-03-415", date: "2003-03", displayDate: "March 2003", year: 2003, title: "Safety lesson", report: "", lessons: "Parachutes were found to be 6 days past the six monthly inspection date.", actions: "A watch needs to be kept routinely and at DI on the inspection renewal dates shown on the board in the hangar workshop to ensure re-packs are undertaken approximately every 6 months.", volume: 1 },
  { id: "2003-03-416", date: "2003-03", displayDate: "March 2003", year: 2003, title: "Safety lesson", report: "", lessons: "Twice on one day a two-seat glider was flying over the winch and so held up launching.", actions: "As well as being inconsiderate to pilots waiting to launch, flying in the vicinity of the launch line has a dangerous collision risk. Pilots must maintain acute positional awareness near the airfield if at or below launch height.", volume: 1 },
  { id: "2003-03-417", date: "2003-03", displayDate: "March 2003", year: 2003, title: "Safety lesson", report: "", lessons: "The parachute on the cable assembly was not in front of the glider at launch start.", actions: "It is less likely that any part of the cable assembly will foul any part of the glider if it is all in front of the glider at start of launch and there is less likelihood of the glider being yawed during the start of the launch.", volume: 1 },
  { id: "2003-03-418", date: "2003-03", displayDate: "March 2003", year: 2003, title: "Safety lesson", report: "", lessons: "Whilst taking up slack on from a downhill position at the N end, the glider over-ran the cable and back released. There was no second wing tip holder. STOP was not called before All Out.", actions: "Over-running the cable is potentially dangerous; launching could proceed with part of the cable assembly caught on the glider. Down hill launches should be avoided if possible. If unavoidable, both wing tips should be held. Launches must be STOPPED immediately there is any over-run.", volume: 1 },
  { id: "2003-03-419", date: "2003-03", displayDate: "March 2003", year: 2003, title: "Safety lesson", report: "", lessons: "A winch observer reported that winching took place close to \"pedestrian traffic\"", actions: "Cables under power are extremely hazardous. All concerned with launching must watch out for persons near cables, at the launch point, at the winches and on the airfield - and stop launching if that happens.", volume: 1 },
  { id: "2003-03-420", date: "2003-03", displayDate: "March 2003", year: 2003, title: "Safety lesson", report: "", lessons: "After a pilot released (believing he was over-running), the light signaller required two requests to signal STOP.", actions: "Launch marshals must be sure that light signallers operators understand how to operate the signals and can see/hear their commands.", volume: 1 },
  { id: "2003-03-421", date: "2003-03", displayDate: "March 2003", year: 2003, title: "Safety lesson", report: "", lessons: "Launch signals were started without the wing tip being held. The pilot realised and released. There was some confusion about the signalling buttons. There was apparently no solo pilot in charge.", actions: "Launching is potentially hazardous. To ensure safety, qualified launch marshals are now mandatory. They must be sure that light signallers operators understand how to operate the signals and can see/hear launch marshals' commands.", volume: 1 },
];

/** Years present, newest first. */
export const safetyLessonYears: number[] = [2026, 2025, 2024, 2023, 2022, 2021, 2020, 2019, 2018, 2017, 2016, 2015, 2014, 2013, 2012, 2011, 2010, 2009, 2008, 2007, 2006, 2005, 2003];

/** How many years are shown before the member asks for more. */
export const SAFETY_LOG_RECENT_YEARS = 5;

export const safetyLogSource =
  'https://dlgc.org.uk/members/safety/SftyLssnsLg.asp';
